import chess

MOTIF_NAME = 'material-parity king hook pressure'
MOTIF_DESCRIPTION = 'With material roughly balanced, the side to move has pressure against a home-rank central king or a castled king shelter hook.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm

    def rr(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def val(pt):
        if pt == chess.PAWN:
            return 100
        if pt == chess.KNIGHT:
            return 320
        if pt == chess.BISHOP:
            return 330
        if pt == chess.ROOK:
            return 500
        if pt == chess.QUEEN:
            return 900
        return 0

    mat = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        mat += val(pt) * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        mat += 35
    if len(board.pieces(chess.BISHOP, opp)) >= 2:
        mat -= 35
    if mat < -120 or mat > 180:
        return False

    ok = board.king(opp)
    if ok is None:
        return False
    of = chess.square_file(ok)
    orank = chess.square_rank(ok)

    def developed(color):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, color):
                if rr(sq, color) >= 1:
                    n += 1
        return n

    dev_stm = developed(stm)
    dev_opp = developed(opp)

    def central_pawn(color):
        for sq in board.pieces(chess.PAWN, color):
            if chess.square_file(sq) in (3, 4) and 3 <= rr(sq, color) <= 5:
                return True
        return False

    def f_hook(color):
        for sq in board.pieces(chess.PAWN, color):
            if chess.square_file(sq) == 5 and rr(sq, color) >= 2:
                return True
        return False

    def safeish(sq):
        return len(board.attackers(opp, sq)) <= len(board.attackers(stm, sq)) + 1

    central_home = rr(ok, opp) == 0 and 2 <= of <= 5
    if central_home:
        q_close = False
        for q in board.pieces(chess.QUEEN, stm):
            if rr(q, stm) >= 3 and chess.square_distance(q, ok) <= 3:
                q_close = True

        direction = 1 if stm == chess.WHITE else -1
        rook_aim = False
        for rsq in board.pieces(chess.ROOK, stm):
            if rr(rsq, stm) >= 1 and abs(chess.square_file(rsq) - of) <= 1:
                rf = chess.square_file(rsq)
                ranks = range(chess.square_rank(rsq) + direction, 8, 1) if direction == 1 else range(chess.square_rank(rsq) + direction, -1, -1)
                for r in ranks:
                    sq = chess.square(rf, r)
                    pc = board.piece_at(sq)
                    if pc:
                        if pc.color == opp and (rr(sq, opp) <= 1 or pc.piece_type in (chess.ROOK, chess.QUEEN)):
                            rook_aim = True
                        break
                    if r == orank:
                        rook_aim = True
                        break

        near_minor = False
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if rr(sq, stm) >= 3 and chess.square_distance(sq, ok) <= 2 and safeish(sq):
                    near_minor = True

        front_dir = -1 if opp == chess.BLACK else 1
        pressure = set()
        for depth in range(0, 4):
            r = orank + front_dir * depth
            if 0 <= r < 8:
                for f in range(of - 2, of + 3):
                    if 0 <= f < 8:
                        sq = chess.square(f, r)
                        for a in board.attackers(stm, sq):
                            pc = board.piece_at(a)
                            if pc and pc.color == stm and pc.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
                                pressure.add(a)

        if f_hook(opp) and central_pawn(stm) and dev_stm >= dev_opp - 1 and board.fullmove_number <= 18:
            return True
        if q_close and dev_stm >= dev_opp - 1:
            return True
        if (rook_aim or near_minor) and dev_stm >= dev_opp - 1 and len(pressure) >= 1:
            return True
        if len(pressure) >= 3 and dev_stm >= dev_opp:
            return True

    flank_king = rr(ok, opp) <= 1 and (of <= 1 or of >= 6)
    if flank_king:
        front_dir = -1 if opp == chess.BLACK else 1
        zone_attackers = set()
        shelter_hit = False
        for depth in range(1, 4):
            r = orank + front_dir * depth
            if not 0 <= r < 8:
                continue
            for f in range(of - 2, of + 3):
                if not 0 <= f < 8:
                    continue
                sq = chess.square(f, r)
                for a in board.attackers(stm, sq):
                    pc = board.piece_at(a)
                    if pc and pc.color == stm and pc.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
                        zone_attackers.add(a)
                if depth == 1 and abs(f - of) <= 1:
                    target = board.piece_at(sq)
                    if target and target.color == opp and target.piece_type == chess.PAWN:
                        for a in board.attackers(stm, sq):
                            pc = board.piece_at(a)
                            if pc and pc.color == stm and pc.piece_type in (chess.QUEEN, chess.BISHOP):
                                shelter_hit = True
        if shelter_hit and len(zone_attackers) >= 2 and dev_stm >= dev_opp - 1:
            return True

    return False

import chess

MOTIF_NAME = 'balanced castling lead and invader tempo'
MOTIF_DESCRIPTION = 'Without a large material edge, the side to move has a castling/development initiative, a safe major-piece invader, or a protected tempo on an overextended queen.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = (0, 100, 320, 330, 500, 900, 0)

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def rr(sq):
        return rel(sq, stm)

    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None:
        return False

    mat = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        mat += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        mat += 35
    if len(board.pieces(chess.BISHOP, opp)) >= 2:
        mat -= 35
    if mat > 180 or mat < -260:
        return False

    def castles(color):
        return board.has_kingside_castling_rights(color) or board.has_queenside_castling_rights(color)

    def pawn_att(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.color == color and p.piece_type == chess.PAWN:
                n += 1
        return n

    def safe_king(color):
        k = board.king(color)
        if k is None:
            return False
        f = chess.square_file(k)
        r = chess.square_rank(k)
        if not (rel(k, color) <= 1 and (f <= 2 or f >= 5)):
            return False
        step = 1 if color == chess.WHITE else -1
        shelter = 0
        for df in (-1, 0, 1):
            for d in (1, 2):
                nf, nr = f + df, r + step * d
                if 0 <= nf < 8 and 0 <= nr < 8:
                    p = board.piece_at(chess.square(nf, nr))
                    if p and p.color == color and p.piece_type == chess.PAWN:
                        shelter += 1
        danger = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8 and board.attackers(not color, chess.square(nf, nr)):
                    danger += 1
        return shelter >= 1 and danger <= 5

    safe_stm = safe_king(stm)
    own_castle = castles(stm)
    opp_castle = castles(opp)

    def dev_score(color):
        s = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, color):
                r = rel(sq, color)
                if r >= 2:
                    s += 2
                elif r == 1:
                    s += 1
        for sq in board.pieces(chess.ROOK, color):
            r = rel(sq, color)
            f = chess.square_file(sq)
            if r >= 3:
                s += 2
            elif r >= 1 or f in (3, 4):
                s += 1
        for sq in board.pieces(chess.QUEEN, color):
            if rel(sq, color) >= 2:
                s += 1
        if safe_king(color):
            s += 2
        return s

    def zone_pressure():
        pieces = set()
        ef = chess.square_file(ek)
        er = chess.square_rank(ek)
        for df in range(-2, 3):
            for dr in range(-2, 3):
                nf, nr = ef + df, er + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    sq = chess.square(nf, nr)
                    for a in board.attackers(stm, sq):
                        p = board.piece_at(a)
                        if p and p.color == stm and p.piece_type != chess.KING:
                            pieces.add(a)
        return len(pieces)

    press = zone_pressure()
    dev_stm = dev_score(stm)
    dev_opp = dev_score(opp)
    enemy_home_center = rr(ek) >= 6 and 2 <= chess.square_file(ek) <= 5

    center_pawn = False
    for psq in board.pieces(chess.PAWN, stm):
        if chess.square_file(psq) in (3, 4) and rr(psq) >= 3:
            center_pawn = True
            break

    if mat >= -120 and enemy_home_center and safe_stm:
        lead = dev_stm - dev_opp
        if lead >= 3 and (press >= 1 or center_pawn):
            return True
        if lead >= 2 and press >= 3:
            return True

    if mat >= -80 and enemy_home_center and (not opp_castle) and (own_castle or safe_stm):
        adv = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if rr(sq) >= 3:
                    adv += 1
        if adv >= 2 and dev_stm + 1 >= dev_opp:
            return True

    def guarded_enough(sq):
        defenders = len(board.attackers(stm, sq))
        attackers = len(board.attackers(opp, sq))
        pa = pawn_att(opp, sq)
        if attackers == 0:
            return True
        if pa > 0:
            return defenders >= pa + 1 and attackers <= defenders + 1
        return defenders >= 1 and attackers <= defenders + 1

    for pt in (chess.QUEEN, chess.ROOK):
        for sq in board.pieces(pt, stm):
            r = rr(sq)
            f = chess.square_file(sq)
            if pt == chess.QUEEN:
                deep = r >= 6 or (r >= 5 and (f <= 1 or f >= 6 or chess.square_distance(sq, ek) <= 3))
            else:
                deep = r >= 5 or (r >= 4 and 2 <= f <= 5)
            if not deep or not guarded_enough(sq):
                continue
            target = r >= 6 or chess.square_distance(sq, ek) <= 3
            for t in board.attacks(sq):
                p = board.piece_at(t)
                if p and p.color == opp:
                    if p.piece_type in (chess.QUEEN, chess.ROOK):
                        target = True
                    elif p.piece_type in (chess.BISHOP, chess.KNIGHT) and pt == chess.ROOK:
                        target = True
                    elif p.piece_type == chess.PAWN and r >= 5 and chess.square_distance(t, ek) <= 2:
                        target = True
            if target and (safe_stm or press >= 2 or (pt == chess.QUEEN and r >= 6)):
                return True

    if mat >= -140 and (safe_stm or own_castle):
        moves = None
        for qsq in board.pieces(chess.QUEEN, opp):
            qf = chess.square_file(qsq)
            qr = rr(qsq)
            if not (qf in (0, 1, 6, 7) and 2 <= qr <= 5):
                continue
            harass = False
            for t in board.attacks(qsq):
                p = board.piece_at(t)
                if p and p.color == stm and p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
                    harass = True
                    break
            if not harass:
                continue
            if moves is None:
                moves = list(board.legal_moves)
            for mv in moves:
                if board.is_capture(mv):
                    continue
                p = board.piece_at(mv.from_square)
                if not p or p.color != stm or p.piece_type not in (chess.KNIGHT, chess.BISHOP):
                    continue
                if rr(mv.to_square) < 2:
                    continue
                if rr(mv.to_square) <= rr(mv.from_square) and rr(mv.from_square) > 1:
                    continue
                board.push(mv)
                ok = False
                moved = board.piece_at(mv.to_square)
                if moved and moved.color == stm and qsq in board.attacks(mv.to_square):
                    d = len(board.attackers(stm, mv.to_square))
                    a = len(board.attackers(opp, mv.to_square))
                    if d >= 1 and pawn_att(opp, mv.to_square) == 0 and a <= d + 1:
                        ok = True
                board.pop()
                if ok:
                    return True

    return False

import chess

MOTIF_NAME = 'secure central grip and pawn targets'
MOTIF_DESCRIPTION = 'With material roughly balanced, the side to move has a safe king and either a supported central pawn grip or clearly better pressure on weak enemy pawns.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}
    mat = 0
    for pt, v in vals.items():
        mat += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        mat += 30
    if len(board.pieces(chess.BISHOP, opp)) >= 2:
        mat -= 30
    if mat < -120 or mat > 180 or board.is_check():
        return False

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def forward(color):
        return 1 if color == chess.WHITE else -1

    def king_safe(color):
        k = board.king(color)
        if k is None:
            return False
        enemy = not color
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        danger = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = kf + df, kr + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    if board.attackers(enemy, chess.square(nf, nr)):
                        danger += 1
        queens = bool(board.pieces(chess.QUEEN, chess.WHITE) or board.pieces(chess.QUEEN, chess.BLACK))
        if not queens:
            return danger <= 5
        shield = 0
        step = forward(color)
        for df in (-1, 0, 1):
            nf = kf + df
            if 0 <= nf < 8:
                for d in (1, 2):
                    nr = kr + step * d
                    if 0 <= nr < 8:
                        p = board.piece_at(chess.square(nf, nr))
                        if p and p.color == color and p.piece_type == chess.PAWN:
                            shield += 1
                            break
        if (kf <= 2 or kf >= 5) and shield >= 2 and danger <= 4:
            return True
        if rel(k, color) == 0 and board.has_castling_rights(color) and danger <= 2:
            return True
        return False

    safe = king_safe(stm)
    if not safe:
        return False

    def defended_by_piece(sq, color):
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.color == color and p.piece_type != chess.KING:
                return True
        return False

    center = []
    for sq in board.pieces(chess.PAWN, stm):
        f = chess.square_file(sq)
        rr = rel(sq, stm)
        if 2 <= f <= 5 and 3 <= rr <= 5:
            center.append((sq, f, rr, defended_by_piece(sq, stm)))

    dev = 0
    for pt in (chess.KNIGHT, chess.BISHOP):
        for sq in board.pieces(pt, stm):
            if rel(sq, stm) >= 2:
                dev += 1

    supports = sum(1 for x in center if x[3])
    pair = False
    for i in range(len(center)):
        for j in range(i + 1, len(center)):
            if abs(center[i][1] - center[j][1]) == 1 and abs(center[i][2] - center[j][2]) <= 1:
                if (center[i][2] >= 4 or center[j][2] >= 4 or len(center) >= 3) and (center[i][3] or center[j][3]):
                    pair = True

    if dev >= 2 and ((len(center) >= 3 and supports >= 2) or pair):
        return True

    def pawn_file_counts(color):
        a = [0] * 8
        for sq in board.pieces(chess.PAWN, color):
            a[chess.square_file(sq)] += 1
        return a

    def pressure(attacker, victim):
        vf = pawn_file_counts(victim)
        score = 0
        step = forward(victim)
        for sq in board.pieces(chess.PAWN, victim):
            attackers = []
            for a in board.attackers(attacker, sq):
                p = board.piece_at(a)
                if p and p.color == attacker and p.piece_type not in (chess.KING, chess.PAWN):
                    attackers.append(p.piece_type)
            if not attackers:
                continue
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            isolated = (f == 0 or vf[f - 1] == 0) and (f == 7 or vf[f + 1] == 0)
            pawn_def = False
            for a in board.attackers(victim, sq):
                p = board.piece_at(a)
                if p and p.color == victim and p.piece_type == chess.PAWN:
                    pawn_def = True
            nr = r + step
            blocked = False
            if 0 <= nr < 8:
                p = board.piece_at(chess.square(f, nr))
                blocked = bool(p and p.color == attacker)
            vrel = rel(sq, victim)
            major = any(pt in (chess.ROOK, chess.QUEEN) for pt in attackers)
            multi = len(attackers) >= 2
            weak = isolated or blocked or vrel >= 4 or (not pawn_def and (vrel >= 3 or major or multi))
            if weak:
                s = 1
                if major:
                    s += 1
                if vrel >= 4 or blocked:
                    s += 1
                if not pawn_def:
                    s += 1
                if multi:
                    s += 1
                score += min(s, 4)
        return score

    p1 = pressure(stm, opp)
    if p1 >= 4 and p1 >= pressure(opp, stm) + 3:
        return True
    return False

import chess

MOTIF_NAME = 'overloaded central shield and structural edge'
MOTIF_DESCRIPTION = 'The side to move has a coordinated attack on a pinned central king shield, a safe knight fork, or a queenless pawn-structure edge at material parity.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def matdiff():
        vals = {chess.PAWN: 1.0, chess.KNIGHT: 3.2, chess.BISHOP: 3.3, chess.ROOK: 5.0, chess.QUEEN: 9.0}
        s = 0.0
        for pt, v in vals.items():
            s += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        if len(board.pieces(chess.BISHOP, stm)) >= 2:
            s += 0.25
        if len(board.pieces(chess.BISHOP, opp)) >= 2:
            s -= 0.25
        return s

    def safe_flank(color):
        k = board.king(color)
        if k is None:
            return False
        f = chess.square_file(k)
        return rel(k, color) <= 1 and (f <= 2 or f >= 5)

    def zone_squares(ek):
        ef = chess.square_file(ek)
        er = chess.square_rank(ek)
        out = []
        for f in range(max(0, ef - 2), min(7, ef + 2) + 1):
            for r in range(max(0, er - 2), min(7, er + 2) + 1):
                sq = chess.square(f, r)
                if rel(sq, opp) <= 2:
                    out.append(sq)
        return out

    def central_shield():
        if board.is_check() or len(board.pieces(chess.QUEEN, stm)) == 0 or not safe_flank(stm):
            return False
        ek = board.king(opp)
        if ek is None or rel(ek, opp) > 1:
            return False
        ef = chess.square_file(ek)
        if ef not in (3, 4):
            return False
        fr = chess.square_rank(ek) + (1 if opp == chess.WHITE else -1)
        if fr < 0 or fr > 7:
            return False
        front = chess.square(ef, fr)
        fp = board.piece_at(front)
        if not (fp and fp.color == opp and fp.piece_type == chess.PAWN):
            return False
        line = False
        for pt in (chess.ROOK, chess.QUEEN):
            for s in board.pieces(pt, stm):
                if chess.square_file(s) == ef and front in board.attacks(s):
                    line = True
        if not line:
            return False
        score = 0
        heavy = 0
        front_hit = False
        for sq in zone_squares(ek):
            p = board.piece_at(sq)
            if not p or p.color != opp or p.piece_type == chess.KING:
                continue
            at = list(board.attackers(stm, sq))
            if not at:
                continue
            add = 1
            if p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                add += 1
            if sq == front:
                add += 1
                front_hit = True
            h = False
            for a in at:
                ap = board.piece_at(a)
                if ap and ap.color == stm and ap.piece_type in (chess.QUEEN, chess.ROOK):
                    h = True
            if h:
                heavy += 1
            if len(board.attackers(opp, sq)) <= len(at) + 1 or sq == front:
                score += add
        return front_hit and heavy >= 2 and score >= 4

    def shattered_center():
        if board.is_check() or len(board.pieces(chess.QUEEN, stm)) == 0 or not safe_flank(stm):
            return False
        if matdiff() < -3.5:
            return False
        ek = board.king(opp)
        if ek is None or rel(ek, opp) > 1:
            return False
        ef = chess.square_file(ek)
        if ef not in (3, 4):
            return False
        fr = chess.square_rank(ek) + (1 if opp == chess.WHITE else -1)
        if fr < 0 or fr > 7:
            return False
        front = chess.square(ef, fr)
        fp = board.piece_at(front)
        if fp and fp.color == opp and fp.piece_type != chess.PAWN:
            return False
        holes = 0
        for f in range(max(0, ef - 1), min(7, ef + 1) + 1):
            p = board.piece_at(chess.square(f, fr))
            if not (p and p.color == opp and p.piece_type == chess.PAWN):
                holes += 1
        if holes < 2:
            return False
        zs = zone_squares(ek)
        act = 0
        major = False
        for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
            for s in board.pieces(pt, stm):
                hit = any(z in board.attacks(s) for z in zs)
                if hit or (pt == chess.QUEEN and chess.square_distance(s, ek) <= 4):
                    if pt == chess.QUEEN:
                        act += 2
                        major = True
                    elif pt == chess.ROOK:
                        act += 1
                        major = True
                    else:
                        act += 1
        for p in board.pieces(chess.PAWN, stm):
            if rel(p, stm) >= 4 and abs(chess.square_file(p) - ef) <= 2:
                act += 1
        return major and ((holes >= 3 and act >= 4) or act >= 5)

    def knight_fork():
        if board.is_check():
            return False
        legal = set(board.legal_moves)
        for n in board.pieces(chess.KNIGHT, stm):
            for to in board.attacks(n):
                p0 = board.piece_at(to)
                if p0 and p0.color == stm:
                    continue
                mv = chess.Move(n, to)
                if mv not in legal:
                    continue
                b = board.copy(stack=False)
                b.push(mv)
                q = r = 0
                for t in b.attacks(to):
                    p = b.piece_at(t)
                    if p and p.color == opp:
                        if p.piece_type == chess.QUEEN:
                            q += 1
                        elif p.piece_type == chess.ROOK:
                            r += 1
                bad = False
                for a in b.attackers(opp, to):
                    ap = b.piece_at(a)
                    if ap and ap.piece_type in (chess.PAWN, chess.KING):
                        bad = True
                if bad and len(b.attackers(stm, to)) == 0:
                    continue
                cap_major = p0 and p0.color == opp and p0.piece_type in (chess.QUEEN, chess.ROOK)
                if (b.is_check() and (q + r >= 1 or cap_major)) or (q >= 1 and q + r >= 2):
                    return True
        return False

    def structural_edge():
        if board.is_check():
            return False
        if len(board.pieces(chess.QUEEN, stm)) or len(board.pieces(chess.QUEEN, opp)):
            return False
        m = matdiff()
        if m < -0.1 or m > 1.6:
            return False
        if len(board.pieces(chess.PAWN, stm)) < len(board.pieces(chess.PAWN, opp)):
            return False

        def weakness(color):
            files = [0] * 8
            pawns = list(board.pieces(chess.PAWN, color))
            for p in pawns:
                files[chess.square_file(p)] += 1
            doubled = sum(c - 1 for c in files if c > 1)
            iso = 0
            for p in pawns:
                f = chess.square_file(p)
                if (f == 0 or files[f - 1] == 0) and (f == 7 or files[f + 1] == 0):
                    iso += 1
            islands = 0
            prev = False
            for c in files:
                now = c > 0
                if now and not prev:
                    islands += 1
                prev = now
            return 2 * doubled + iso + max(0, islands - 1)

        def passed_score(color):
            score = 0
            for p in board.pieces(chess.PAWN, color):
                f = chess.square_file(p)
                r = chess.square_rank(p)
                blocked = False
                for e in board.pieces(chess.PAWN, not color):
                    if abs(chess.square_file(e) - f) <= 1:
                        er = chess.square_rank(e)
                        if (color == chess.WHITE and er > r) or (color == chess.BLACK and er < r):
                            blocked = True
                            break
                rr = rel(p, color)
                if not blocked and rr >= 3:
                    s = rr - 2
                    for a in board.attackers(color, p):
                        ap = board.piece_at(a)
                        if ap and ap.color == color and ap.piece_type == chess.PAWN:
                            s += 1
                            break
                    for ro in board.pieces(chess.ROOK, color):
                        if chess.square_file(ro) == f:
                            rrk = chess.square_rank(ro)
                            if (color == chess.WHITE and rrk < r) or (color == chess.BLACK and rrk > r):
                                s += 1
                                break
                    score += s
            return score

        def kingact(color):
            k = board.king(color)
            f = chess.square_file(k)
            return rel(k, color) + (2 if 2 <= f <= 5 else 0) - (1 if f in (0, 7) else 0)

        ws, wo = weakness(stm), weakness(opp)
        ps, po = passed_score(stm), passed_score(opp)
        score = 2 * (wo - ws) + 2 * (ps - po) + kingact(stm) - kingact(opp)
        return score >= 5 and (wo >= ws + 2 or ps >= po + 2 or (wo > ws and ps > po))

    return central_shield() or shattered_center() or knight_fork() or structural_edge()

import chess

MOTIF_NAME = 'wing pawn tempo and central knight wedge'
MOTIF_DESCRIPTION = 'The side to move has a protected wing-pawn tempo on an advanced piece, a complementary fifth-rank knight wedge, or a queen-and-pawn phalanx against a central king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    sk = board.king(stm)
    ek = board.king(opp)
    if sk is None or ek is None:
        return False

    vals = [0, 100, 320, 330, 500, 900, 0]

    def rr(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def mat_diff():
        m = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            m += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        if len(board.pieces(chess.BISHOP, stm)) >= 2:
            m += 35
        if len(board.pieces(chess.BISHOP, opp)) >= 2:
            m -= 35
        return m

    md = mat_diff()

    def castle(c):
        return board.has_kingside_castling_rights(c) or board.has_queenside_castling_rights(c)

    def ring(k):
        f = chess.square_file(k)
        r = chess.square_rank(k)
        out = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df or dr:
                    nf = f + df
                    nr = r + dr
                    if 0 <= nf < 8 and 0 <= nr < 8:
                        out.append(chess.square(nf, nr))
        return out

    def safe(c):
        k = board.king(c)
        if k is None:
            return False
        if castle(c):
            return True
        f = chess.square_file(k)
        a = d = 0
        for s in ring(k):
            if board.attackers(not c, s):
                a += 1
            if board.attackers(c, s):
                d += 1
        if len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK)) == 0:
            return a <= d + 2
        if f <= 2 or f >= 5:
            return a <= d + 2
        return False

    def central_home(c):
        k = board.king(c)
        return k is not None and rr(k, c) <= 1 and 2 <= chess.square_file(k) <= 5

    def pawn_tempo():
        if md < -60 or md > 160 or not safe(stm):
            return False
        for mv in board.legal_moves:
            if mv.promotion or board.is_capture(mv):
                continue
            pc = board.piece_at(mv.from_square)
            if not pc or pc.color != stm or pc.piece_type != chess.PAWN:
                continue
            to = mv.to_square
            f = chess.square_file(to)
            if 2 <= f <= 4 or rr(to, stm) < 3:
                continue
            b2 = board.copy(stack=False)
            b2.push(mv)
            da = len(b2.attackers(stm, to))
            if da == 0 or len(b2.attackers(opp, to)) > da + 1:
                continue
            for t in b2.attacks(to):
                p = b2.piece_at(t)
                if not p or p.color != opp or p.piece_type not in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                    continue
                if rr(t, stm) < 4:
                    continue
                aa = len(b2.attackers(stm, t))
                dd = len(b2.attackers(opp, t))
                if aa + 1 >= dd and (p.piece_type >= chess.ROOK or rr(to, stm) >= 4 or dd <= aa):
                    return True
        return False

    def knight_wedge():
        if md < -80 or md > 180 or not safe(stm):
            return False
        en_kn = len(board.pieces(chess.KNIGHT, opp))
        st_kn = len(board.pieces(chess.KNIGHT, stm))
        en_bi = len(board.pieces(chess.BISHOP, opp))
        for n in board.pieces(chess.KNIGHT, stm):
            if not (2 <= chess.square_file(n) <= 5 and rr(n, stm) >= 4):
                continue
            defs = board.attackers(stm, n)
            if not defs:
                continue
            good_def = False
            pawn_def = False
            for a in defs:
                ap = board.piece_at(a)
                if ap and ap.piece_type != chess.KING:
                    good_def = True
                if ap and ap.piece_type == chess.PAWN:
                    pawn_def = True
            if not good_def or len(board.attackers(opp, n)) > len(defs) + 2:
                continue
            if en_kn == 0 and en_bi >= 2 and (pawn_def or len(defs) >= 2):
                return True
            for t in board.attacks(n):
                p = board.piece_at(t)
                if not p or p.color != opp or p.piece_type not in (chess.QUEEN, chess.ROOK, chess.KNIGHT, chess.BISHOP):
                    continue
                aa = len(board.attackers(stm, t))
                dd = len(board.attackers(opp, t))
                if p.piece_type in (chess.QUEEN, chess.ROOK) and aa >= dd:
                    return True
                if p.piece_type in (chess.KNIGHT, chess.BISHOP) and (st_kn >= en_kn or pawn_def) and aa + 1 >= dd:
                    if rr(t, stm) >= 4 or chess.square_distance(t, ek) <= 2:
                        return True
        return False

    def queen_phalanx():
        if md < -140 or md > 220:
            return False
        if not board.pieces(chess.QUEEN, stm) or board.pieces(chess.QUEEN, opp):
            return False
        if not central_home(opp):
            return False
        if not (castle(stm) or rr(sk, stm) <= 1 or safe(stm)):
            return False
        pawns = 0
        core = False
        for p in board.pieces(chess.PAWN, stm):
            f = chess.square_file(p)
            if 2 <= f <= 5 and rr(p, stm) >= 3:
                pawns += 1
                if f in (3, 4):
                    core = True
        if pawns < 2 or not core:
            return False
        for q in board.pieces(chess.QUEEN, stm):
            if 2 <= chess.square_file(q) <= 5 and rr(q, stm) >= 3:
                return True
        return False

    return pawn_tempo() or knight_wedge() or queen_phalanx()

import chess

MOTIF_NAME = 'supported central pawn tempo versus sleepy pieces'
MOTIF_DESCRIPTION = 'With material close, the side to move has a safe king and either a development bind from enemy back-rank minors or a supported central pawn break that gains time on a piece.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    V = {chess.PAWN: 2, chess.KNIGHT: 6, chess.BISHOP: 6, chess.ROOK: 10, chess.QUEEN: 18}

    def rr(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def material(c):
        m = 0
        for pt, v in V.items():
            n = len(board.pieces(pt, c))
            m += v * n
            if pt == chess.BISHOP and n >= 2:
                m += 1
        return m

    mat = material(stm) - material(opp)
    if mat < -4 or mat > 4 or board.is_check():
        return False

    qtot = len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK))

    def ksafe(c):
        k = board.king(c)
        if k is None or len(board.attackers(not c, k)):
            return False
        f = chess.square_file(k)
        r = rr(k, c)
        if qtot == 0 and r <= 2:
            return True
        if r == 0 and f in (1, 2, 6, 7):
            return True
        if r == 1 and f in (0, 1, 2, 5, 6, 7):
            return True
        if r == 0 and f == 4:
            return board.has_kingside_castling_rights(c) or board.has_queenside_castling_rights(c)
        return False

    if not ksafe(stm):
        return False

    def sleepy(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                if rr(s, c) == 0:
                    n += 1
        return n

    def active(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                if rr(s, c) > 0:
                    mob = 0
                    for a in board.attacks(s):
                        p = board.piece_at(a)
                        if p is None or p.color != c:
                            mob += 1
                    if rr(s, c) >= 2 or mob >= 3:
                        n += 1
        return n

    def space(c):
        sc = 0
        for s in board.pieces(chess.PAWN, c):
            f = chess.square_file(s)
            r = rr(s, c)
            if 2 <= f <= 5 and r >= 3:
                sc += 1
                if r >= 4:
                    sc += 1
        return sc

    sd = sleepy(opp) - sleepy(stm)
    sp = space(stm) - space(opp)

    if sd >= 2 and active(stm) >= 2 and sp >= 0:
        return True
    if sd >= 1 and active(stm) >= 2 and (sp >= 2 or (sp >= 1 and active(opp) <= 2)):
        return True

    oking = board.king(opp)
    opp_rights = board.has_kingside_castling_rights(opp) or board.has_queenside_castling_rights(opp)
    opp_central = oking is not None and rr(oking, opp) <= 1 and chess.square_file(oking) in (3, 4) and not opp_rights
    context = sd >= 1 or sp >= 3 or opp_central

    for mv in list(board.legal_moves):
        p = board.piece_at(mv.from_square)
        if p is None or p.color != stm or p.piece_type != chess.PAWN or mv.promotion:
            continue
        to = mv.to_square
        if not (2 <= chess.square_file(to) <= 5 and rr(to, stm) >= 3):
            continue
        cap = board.piece_at(to)
        capv = V.get(cap.piece_type, 0) if cap is not None and cap.color == opp else 0
        board.push(mv)
        own = len(board.attackers(stm, to))
        enemy = len(board.attackers(opp, to))
        epawns = 0
        for a in board.attackers(opp, to):
            q = board.piece_at(a)
            if q is not None and q.piece_type == chess.PAWN:
                epawns += 1
        safe = own + 1 >= enemy and not (epawns and own == 0)
        hit = 0
        if safe:
            for a in board.attacks(to):
                q = board.piece_at(a)
                if q is not None and q.color == opp:
                    hit = max(hit, V.get(q.piece_type, 0))
        board.pop()
        if not safe:
            continue
        if (capv >= 10 or hit >= 10) and (sp >= 0 or sd >= 0 or opp_central):
            return True
        if context and (capv >= 6 or hit >= 6):
            return True

    return False

import chess

MOTIF_NAME = 'under-material checking spear against exposed king'
MOTIF_DESCRIPTION = 'Without a material surplus, the side to move has a coordinated pawn, minor, or rook spear against an exposed enemy king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    sk = board.king(stm)
    ok = board.king(opp)
    if sk is None or ok is None or board.is_check():
        return False

    V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
         chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0}
    mat = 0
    for p in board.piece_map().values():
        mat += V[p.piece_type] if p.color == stm else -V[p.piece_type]
    if mat < -650 or mat > 150:
        return False

    def rr(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def cnt(pt, c):
        return len(board.pieces(pt, c))

    def central_king(c):
        k = board.king(c)
        return k is not None and rr(k, c) <= 1 and 2 <= chess.square_file(k) <= 5

    def bad_king(c):
        k = board.king(c)
        if k is None:
            return False
        kf = chess.square_file(k)
        if rr(k, c) >= 2 or (2 <= kf <= 5 and rr(k, c) <= 1):
            return True
        near = 0
        loose = 0
        for ps in board.pieces(chess.PAWN, c):
            if abs(chess.square_file(ps) - kf) <= 1:
                r = rr(ps, c)
                if r == 1:
                    near += 1
                elif r == 2:
                    loose += 1
        if near <= 1:
            return True
        if near + loose <= 2:
            for ps in board.pieces(chess.PAWN, not c):
                if rr(ps, not c) >= 3 and chess.square_distance(ps, k) <= 3:
                    return True
        return False

    def pressure(c, k, rad):
        s = 0
        for sq, p in board.piece_map().items():
            if p.color != c or p.piece_type == chess.KING:
                continue
            for a in board.attacks(sq):
                if chess.square_distance(a, k) <= rad:
                    s += 2 if p.piece_type in (chess.QUEEN, chess.ROOK) else 1
                    break
        return s

    def wedge():
        kf = chess.square_file(ok)
        for ps in board.pieces(chess.PAWN, stm):
            if abs(chess.square_file(ps) - kf) <= 1 and rr(ps, stm) >= 3:
                if len(board.attackers(stm, ps)):
                    return True
                for a in board.attacks(ps):
                    if chess.square_distance(a, ok) <= 3:
                        return True
        return False

    def developed_minors():
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if rr(sq, stm) >= 2 or chess.square_distance(sq, ok) <= 4:
                    n += 1
        return n

    def spear():
        for sq, p in board.piece_map().items():
            if p.color != stm:
                continue
            d = chess.square_distance(sq, ok)
            r = rr(sq, stm)
            if p.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP) and r >= 4 and d <= 3:
                return True
            if p.piece_type == chess.ROOK and r >= 4:
                if d <= 2 or chess.square_file(sq) == chess.square_file(ok) or chess.square_rank(sq) == chess.square_rank(ok):
                    return True
        return False

    def pawn_attacked(b, c, sq):
        for a in b.attackers(c, sq):
            p = b.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    bad = bad_king(opp)
    central = central_king(opp)
    if not bad:
        return False

    moves = list(board.legal_moves)
    castle = any(board.is_castling(m) for m in moves)
    rad = 3 if central else 2
    pval = pressure(stm, ok, rad)
    own_ok = (not bad_king(stm)) or castle or mat >= 0 or pval >= 6
    if not own_ok:
        return False

    minors = cnt(chess.KNIGHT, stm) + cnt(chess.BISHOP, stm)

    if central and cnt(chess.QUEEN, stm) and minors >= 3:
        if developed_minors() >= 2 and wedge() and pval >= 5:
            return True

    if not central and cnt(chess.QUEEN, stm) and (minors >= 2 or cnt(chess.ROOK, stm) >= 2):
        if spear() and pval >= 4:
            return True

    if pval < 3:
        return False

    for m in moves:
        pc = board.piece_at(m.from_square)
        if not pc or pc.color != stm or pc.piece_type not in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK):
            continue
        if rr(m.to_square, stm) < 4 and chess.square_distance(m.to_square, ok) > 3:
            continue
        nb = board.copy(stack=False)
        nb.push(m)
        if not nb.is_check():
            continue
        to = m.to_square
        a = len(nb.attackers(opp, to))
        d = len(nb.attackers(stm, to))
        if pc.piece_type == chess.ROOK:
            safe = d >= a
        else:
            safe = d + 1 >= a and not (pawn_attacked(nb, opp, to) and d < a)
        if not safe:
            continue
        high = False
        for t in nb.attacks(to):
            q = nb.piece_at(t)
            if q and q.color == opp and q.piece_type in (chess.QUEEN, chess.ROOK):
                high = True
                break
        if high or central or rr(to, stm) >= 5:
            return True

    return False

import chess
import math

MOTIF_NAME = "castling reserve versus loosened king"
MOTIF_DESCRIPTION = "The side to move has castling reserve or a safer flank king while the opponent has a loose flank shelter or an exposed central king, with material close enough for king safety to matter."

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    side = board.turn
    enemy = not side

    values = {
        chess.PAWN: 100,
        chess.KNIGHT: 320,
        chess.BISHOP: 330,
        chess.ROOK: 500,
        chess.QUEEN: 900,
    }

    def king_square(color: bool) -> int:
        kings = list(board.pieces(chess.KING, color))
        if not kings:
            return -1
        return kings[0]

    def relative_rank(square: int, color: bool) -> int:
        rank = chess.square_rank(square)
        return rank if color == chess.WHITE else 7 - rank

    own_king = king_square(side)
    enemy_king = king_square(enemy)
    if own_king < 0 or enemy_king < 0:
        return False

    material = 0
    for piece_type, value in values.items():
        material += value * (len(board.pieces(piece_type, side)) - len(board.pieces(piece_type, enemy)))

    if len(board.pieces(chess.BISHOP, side)) >= 2:
        material += 30
    if len(board.pieces(chess.BISHOP, enemy)) >= 2:
        material -= 30

    if material < -180 or material > 240:
        return False

    def has_legal_castle(color: bool) -> bool:
        if color != board.turn:
            return False
        for move in board.legal_moves:
            if board.is_castling(move):
                return True
        return False

    def on_flank(color: bool) -> bool:
        square = king_square(color)
        file_index = chess.square_file(square)
        return file_index <= 2 or file_index >= 5

    def pawn_shelter_damage(color: bool) -> int:
        square = king_square(color)
        file_index = chess.square_file(square)
        rank_index = chess.square_rank(square)

        if not on_flank(color):
            return 2 if board.has_castling_rights(color) else 6

        files = range(0, 3) if file_index <= 2 else range(5, 8)
        direction = 1 if color == chess.WHITE else -1
        damage = 0

        for file_to_check in files:
            found_pawn = False
            for step in (1, 2):
                rank_to_check = rank_index + direction * step
                if 0 <= rank_to_check < 8:
                    piece = board.piece_at(chess.square(file_to_check, rank_to_check))
                    if piece and piece.color == color and piece.piece_type == chess.PAWN:
                        found_pawn = True
                        if step == 2:
                            damage += 1
                        break
            if not found_pawn:
                damage += 2

        return damage

    def king_zone_pressure(attacker: bool, defender: bool) -> int:
        square = king_square(defender)
        king_file = chess.square_file(square)
        king_rank = chess.square_rank(square)
        forward = -1 if defender == chess.WHITE else 1

        zone = set()
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                file_index = king_file + df
                rank_index = king_rank + dr
                if 0 <= file_index < 8 and 0 <= rank_index < 8:
                    zone.add(chess.square(file_index, rank_index))

            file_index = king_file + df
            rank_index = king_rank + 2 * forward
            if 0 <= file_index < 8 and 0 <= rank_index < 8:
                zone.add(chess.square(file_index, rank_index))

        weights = {
            chess.PAWN: 1,
            chess.KNIGHT: 3,
            chess.BISHOP: 3,
            chess.ROOK: 5,
            chess.QUEEN: 7,
            chess.KING: 0,
        }

        pressure = 0
        for target in zone:
            for attacker_square in board.attackers(attacker, target):
                piece = board.piece_at(attacker_square)
                if piece:
                    pressure += weights[piece.piece_type]

        return pressure

    def pawn_levers_near_king(attacker: bool, defender: bool) -> int:
        square = king_square(defender)
        enemy_file = chess.square_file(square)
        score = 0

        for pawn_square in board.pieces(chess.PAWN, attacker):
            if relative_rank(pawn_square, attacker) >= 3 and chess.square_distance(pawn_square, square) <= 4:
                file_distance = abs(chess.square_file(pawn_square) - enemy_file)
                if file_distance <= 2:
                    score += 2 if file_distance <= 1 else 1

        return score

    def center_openness() -> int:
        score = 0
        for file_index in (3, 4):
            pawns_on_file = 0
            for rank_index in range(8):
                piece = board.piece_at(chess.square(file_index, rank_index))
                if piece and piece.piece_type == chess.PAWN:
                    pawns_on_file += 1
            if pawns_on_file == 0:
                score += 2
            elif pawns_on_file == 1:
                score += 1
        return score

    def king_risk(color: bool) -> int:
        square = king_square(color)
        file_index = chess.square_file(square)
        risk = pawn_shelter_damage(color) + king_zone_pressure(not color, color)

        if 3 <= file_index <= 4 and relative_rank(square, color) <= 1 and not board.has_castling_rights(color):
            risk += 5

        return risk

    own_risk = king_risk(side)
    enemy_risk = king_risk(enemy)

    own_castle_reserve = has_legal_castle(side)
    own_safe_flank = on_flank(side) and pawn_shelter_damage(side) <= 5 and own_risk <= 10
    own_king_ok = own_castle_reserve or own_safe_flank

    if not own_king_ok:
        return False

    enemy_pressure = king_zone_pressure(side, enemy)
    enemy_levers = pawn_levers_near_king(side, enemy)

    if on_flank(enemy) and pawn_shelter_damage(enemy) >= 4:
        if enemy_risk >= own_risk + 4 and (enemy_pressure >= 5 or enemy_levers >= 2):
            return True

    enemy_file = chess.square_file(enemy_king)
    if 2 <= enemy_file <= 5 and relative_rank(enemy_king, enemy) <= 2 and not board.has_castling_rights(enemy):
        if enemy_risk >= own_risk + 3 and (enemy_pressure >= 5 or center_openness() >= 3):
            return True

    return False

import chess
import math

MOTIF_NAME = "wing pawn roller and queen net"
MOTIF_DESCRIPTION = "The side to move has a safe king and either a supported advanced wing-pawn roller aimed at the enemy king or a lower-piece move that traps or wins the enemy queen."

def motif(fen: str) -> bool:
    try:
        board = chess.Board(fen)
    except Exception:
        return False

    stm = board.turn
    opp = not stm

    values = {
        chess.PAWN: 100,
        chess.KNIGHT: 320,
        chess.BISHOP: 330,
        chess.ROOK: 500,
        chess.QUEEN: 900,
    }

    def rel_rank(square: int, color: bool) -> int:
        r = chess.square_rank(square)
        return r if color == chess.WHITE else 7 - r

    def make_square(file_index: int, relative_rank: int, color: bool):
        if file_index < 0 or file_index > 7 or relative_rank < 0 or relative_rank > 7:
            return None
        return chess.square(file_index, relative_rank if color == chess.WHITE else 7 - relative_rank)

    def near_squares(square: int, radius: int):
        f = chess.square_file(square)
        r = chess.square_rank(square)
        result = []
        for df in range(-radius, radius + 1):
            for dr in range(-radius, radius + 1):
                if df == 0 and dr == 0:
                    continue
                nf = f + df
                nr = r + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    result.append(chess.square(nf, nr))
        return result

    def material_balance() -> int:
        total = 0
        for pt, val in values.items():
            total += val * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        if len(board.pieces(chess.BISHOP, stm)) >= 2:
            total += 35
        if len(board.pieces(chess.BISHOP, opp)) >= 2:
            total -= 35
        return total

    if board.is_check():
        return False

    own_king = board.king(stm)
    enemy_king = board.king(opp)
    if own_king is None or enemy_king is None:
        return False

    if material_balance() < -160:
        return False

    def pawn_shield_count(color: bool) -> int:
        king = board.king(color)
        if king is None:
            return 0
        kf = chess.square_file(king)
        front_rank = rel_rank(king, color) + 1
        count = 0
        for df in (-1, 0, 1):
            sq = make_square(kf + df, front_rank, color)
            if sq is not None:
                piece = board.piece_at(sq)
                if piece is not None and piece.color == color and piece.piece_type == chess.PAWN:
                    count += 1
        return count

    def own_king_safe() -> bool:
        kf = chess.square_file(own_king)
        danger = 0
        for sq in near_squares(own_king, 1):
            danger += len(board.attackers(opp, sq))
        shield = pawn_shield_count(stm)

        if kf in (0, 1, 6, 7):
            return danger <= 3 or (shield >= 1 and danger <= 7)

        if rel_rank(own_king, stm) == 0 and board.has_castling_rights(stm):
            return danger <= 4

        return shield >= 1 and danger <= 5

    if not own_king_safe():
        return False

    def wing_pawn_roller() -> bool:
        enemy_king_file = chess.square_file(enemy_king)

        if rel_rank(enemy_king, opp) > 2:
            return False

        wing_files = range(0, 4) if enemy_king_file <= 3 else range(4, 8)

        advanced_pawns = []
        for sq in board.pieces(chess.PAWN, stm):
            if chess.square_file(sq) in wing_files and rel_rank(sq, stm) >= 3:
                advanced_pawns.append(sq)

        if not advanced_pawns:
            return False

        close_zone = near_squares(enemy_king, 1)
        wider_zone = near_squares(enemy_king, 2)

        attack_support = 0
        major_behind = False
        minor_behind = False

        for sq, piece in board.piece_map().items():
            if piece.color != stm or piece.piece_type == chess.KING:
                continue

            attacks = board.attacks(sq)
            if any(target in attacks for target in close_zone):
                if piece.piece_type in (chess.QUEEN, chess.ROOK):
                    attack_support += 2
                else:
                    attack_support += 1

            if chess.square_file(sq) in wing_files and rel_rank(sq, stm) <= 3:
                if piece.piece_type in (chess.QUEEN, chess.ROOK):
                    major_behind = True
                elif piece.piece_type in (chess.KNIGHT, chess.BISHOP):
                    minor_behind = True

        connected_or_supported = False
        for p in advanced_pawns:
            pf = chess.square_file(p)
            pr = rel_rank(p, stm)
            for other in advanced_pawns:
                if other == p:
                    continue
                of = chess.square_file(other)
                orr = rel_rank(other, stm)
                if abs(of - pf) <= 1 and abs(orr - pr) <= 1:
                    connected_or_supported = True

            for df in (-1, 1):
                support_sq = make_square(pf + df, pr - 1, stm)
                if support_sq is not None:
                    piece = board.piece_at(support_sq)
                    if piece is not None and piece.color == stm and piece.piece_type == chess.PAWN:
                        connected_or_supported = True

        hook_target = False
        for sq in wider_zone:
            piece = board.piece_at(sq)
            if piece is None or piece.color != opp or piece.piece_type == chess.KING:
                continue
            attackers = len(board.attackers(stm, sq))
            defenders = len(board.attackers(opp, sq))
            if attackers >= 2 and attackers >= defenders:
                hook_target = True
                break

        weak_enemy_shelter = pawn_shield_count(opp) <= 1

        if len(advanced_pawns) >= 2 and connected_or_supported and major_behind:
            if attack_support >= 2 or weak_enemy_shelter or hook_target:
                return True

        if len(advanced_pawns) >= 2 and connected_or_supported and minor_behind:
            if attack_support >= 3 and (weak_enemy_shelter or hook_target):
                return True

        if len(advanced_pawns) >= 1 and major_behind and hook_target and attack_support >= 2:
            return True

        return False

    def queen_net() -> bool:
        enemy_queens = list(board.pieces(chess.QUEEN, opp))
        if not enemy_queens:
            return False

        for move in board.legal_moves:
            moving_piece = board.piece_at(move.from_square)
            if moving_piece is None or moving_piece.color != stm:
                continue
            if moving_piece.piece_type not in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK):
                continue

            captured_piece = board.piece_at(move.to_square)
            if captured_piece is not None and captured_piece.color == opp and captured_piece.piece_type == chess.QUEEN:
                return True

            trial = board.copy(stack=False)
            trial.push(move)

            remaining_queens = list(trial.pieces(chess.QUEEN, opp))
            if not remaining_queens:
                return True

            attacker_piece = trial.piece_at(move.to_square)
            if attacker_piece is None or attacker_piece.color != stm:
                continue

            for queen_square in remaining_queens:
                if queen_square not in trial.attacks(move.to_square):
                    continue

                defender_count = len(trial.attackers(opp, move.to_square))
                support_count = len(trial.attackers(stm, move.to_square))

                if defender_count > support_count + 1:
                    continue
                if attacker_piece.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP) and defender_count > support_count:
                    continue

                queen_escape_squares = 0
                queen_can_capture_attacker_safely = False

                for reply in trial.legal_moves:
                    if reply.from_square != queen_square:
                        continue

                    reply_board = trial.copy(stack=False)
                    reply_board.push(reply)

                    queen_after = reply.to_square
                    queen_piece = reply_board.piece_at(queen_after)
                    if queen_piece is None or queen_piece.color != opp or queen_piece.piece_type != chess.QUEEN:
                        continue

                    if reply.to_square == move.to_square and not reply_board.attackers(stm, queen_after):
                        queen_can_capture_attacker_safely = True
                        break

                    if not reply_board.attackers(stm, queen_after):
                        queen_escape_squares += 1
                        if queen_escape_squares > 4:
                            break

                if not queen_can_capture_attacker_safely and queen_escape_squares <= 4:
                    return True

        return False

    return wing_pawn_roller() or queen_net()

import chess

MOTIF_NAME = 'bad bishop bind and active rook conversion'
MOTIF_DESCRIPTION = 'With material close, the side to move exploits a color-complex bad bishop, superior simplified rook activity, or a safe en-passant resource.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0}

    def cnt(pt, c):
        return len(board.pieces(pt, c))

    mat = 0
    for p in board.piece_map().values():
        v = V[p.piece_type]
        mat += v if p.color == stm else -v
    if cnt(chess.BISHOP, stm) >= 2:
        mat += 30
    if cnt(chess.BISHOP, opp) >= 2:
        mat -= 30

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def pawn_on_file(c, f):
        n = 0
        for ps in board.pieces(chess.PAWN, c):
            if chess.square_file(ps) == f:
                n += 1
        return n

    def pawn_def(c, sq):
        for a in board.attackers(c, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    def pawn_hit(c, sq):
        for a in board.attackers(c, sq):
            p = board.piece_at(a)
            if p and p.color == c and p.piece_type == chess.PAWN:
                return True
        return False

    def active_king(c):
        k = board.king(c)
        if k is None:
            return 0
        f = chess.square_file(k)
        s = rel(k, c)
        if 2 <= f <= 5:
            s += 1
        return s

    def danger(c):
        k = board.king(c)
        if k is None:
            return 9
        bad = 0
        kr = chess.square_rank(k)
        kf = chess.square_file(k)
        step = 1 if c == chess.WHITE else -1
        if cnt(chess.QUEEN, not c) and rel(k, c) >= 3:
            bad += 2
        for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
            sh = False
            for d in (1, 2):
                rr = kr + step * d
                if 0 <= rr < 8:
                    p = board.piece_at(chess.square(f, rr))
                    if p and p.color == c and p.piece_type == chess.PAWN:
                        sh = True
            if not sh:
                bad += 1
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    sq = chess.square(f, r)
                    if len(board.attackers(not c, sq)) > len(board.attackers(c, sq)) + 1:
                        bad += 1
        return bad

    def center_locked():
        n = 0
        for ps in board.pieces(chess.PAWN, chess.WHITE):
            f = chess.square_file(ps)
            r = chess.square_rank(ps)
            if 2 <= f <= 5 and r < 7:
                p = board.piece_at(chess.square(f, r + 1))
                if p and p.color == chess.BLACK and p.piece_type == chess.PAWN:
                    n += 1
        return n

    def bad_bishop(c):
        best = 0
        pawns = list(board.pieces(chess.PAWN, c))
        for bs in board.pieces(chess.BISHOP, c):
            col = (chess.square_file(bs) + chess.square_rank(bs)) & 1
            same = 0
            central = 0
            ownblock = 0
            for ps in pawns:
                pf = chess.square_file(ps)
                if ((pf + chess.square_rank(ps)) & 1) == col:
                    same += 1
                    if 2 <= pf <= 5:
                        central += 1
            mob = 0
            for t in board.attacks(bs):
                p = board.piece_at(t)
                if p and p.color == c:
                    if p.piece_type == chess.PAWN:
                        ownblock += 1
                    continue
                mob += 1
            s = same * 2 + central + ownblock * 2 - mob
            if rel(bs, c) <= 1:
                s += 2
            if mob <= 3:
                s += 2
            if mob >= 8:
                s -= 3
            if s > best:
                best = s
        return best

    def good_knights(c):
        s = 0
        good = 0
        for ns in board.pieces(chess.KNIGHT, c):
            f = chess.square_file(ns)
            r = rel(ns, c)
            q = 0
            if 2 <= f <= 5:
                q += 2
                if r >= 2:
                    q += 2
                if r >= 3:
                    q += 2
            else:
                if f in (1, 6) and r >= 2:
                    q += 1
                if f in (0, 7):
                    q -= 2
            if r >= 4:
                q += 1
            if len(board.attackers(c, ns)):
                q += 2
            if pawn_hit(not c, ns):
