            hit = 0
            for t in board.attacks(ns):
                p = board.piece_at(t)
                if p and p.color != c:
                    hit += 2 if p.piece_type in (chess.ROOK, chess.QUEEN, chess.KING) else 1
            if hit > 3:
                hit = 3
            q += hit
            if q >= 4:
                good += 1
            s += q
        if good >= 2:
            s += 3
        return s

    def minor_activity(c):
        s = good_knights(c)
        for bs in board.pieces(chess.BISHOP, c):
            mob = 0
            hit = 0
            for t in board.attacks(bs):
                p = board.piece_at(t)
                if p and p.color == c:
                    continue
                mob += 1
                if p and p.color != c:
                    hit += 1
            if hit > 3:
                hit = 3
            q = mob + hit * 2
            if rel(bs, c) >= 2:
                q += 1
            s += q
        if cnt(chess.BISHOP, c) >= 2:
            s += 3
        b = bad_bishop(c)
        if b > 4:
            s -= b - 4
        return s

    def weak_pawns(c):
        files = [0] * 8
        for ps in board.pieces(chess.PAWN, c):
            files[chess.square_file(ps)] += 1
        n = 0
        for ps in board.pieces(chess.PAWN, c):
            f = chess.square_file(ps)
            iso = (f == 0 or files[f - 1] == 0) and (f == 7 or files[f + 1] == 0)
            doubled = files[f] > 1
            defended = pawn_def(c, ps)
            attacked = len(board.attackers(not c, ps)) > 0
            if iso and (attacked or not defended):
                n += 1
            if doubled:
                n += 1
            if attacked and not defended:
                n += 1
        return n

    def rook_activity(c):
        total = 0
        for rs in board.pieces(chess.ROOK, c):
            f = chess.square_file(rs)
            r = rel(rs, c)
            own = pawn_on_file(c, f)
            enemy = pawn_on_file(not c, f)
            q = 0
            if own == 0:
                q += 2
                if enemy == 0:
                    q += 1
            if r >= 3:
                q += r - 1
            if r >= 5:
                q += 2
            if len(board.attackers(c, rs)):
                q += 1
            hits = 0
            for t in board.attacks(rs):
                p = board.piece_at(t)
                if p and p.color != c:
                    if p.piece_type == chess.PAWN:
                        hits += 1
                    elif p.piece_type == chess.KING:
                        hits += 3
                    elif p.piece_type in (chess.ROOK, chess.QUEEN):
                        hits += 2
                    else:
                        hits += 1
            if hits > 5:
                hits = 5
            total += q + hits
        return total

    def max_rook_rel(c):
        m = -1
        for rs in board.pieces(chess.ROOK, c):
            r = rel(rs, c)
            if r > m:
                m = r
        return m

    def passed_after(b, c, sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for ff in range(max(0, f - 1), min(7, f + 1) + 1):
            for ps in b.pieces(chess.PAWN, not c):
                if chess.square_file(ps) == ff:
                    pr = chess.square_rank(ps)
                    if (c == chess.WHITE and pr > r) or (c == chess.BLACK and pr < r):
                        return False
        return True

    def safe_ep():
        if board.ep_square is None:
            return False
        for m in board.legal_moves:
            pc = board.piece_at(m.from_square)
            if not pc or pc.color != stm or pc.piece_type != chess.PAWN:
                continue
            if m.to_square != board.ep_square:
                continue
            if chess.square_file(m.from_square) == chess.square_file(m.to_square):
                continue
            if board.piece_at(m.to_square) is not None:
                continue
            cap_sq = chess.square(chess.square_file(m.to_square), chess.square_rank(m.from_square))
            cp = board.piece_at(cap_sq)
            if not cp or cp.color != opp or cp.piece_type != chess.PAWN:
                continue
            nb = board.copy(stack=False)
            nb.push(m)
            ats = len(nb.attackers(opp, m.to_square))
            dfs = len(nb.attackers(stm, m.to_square))
            ok = nb.king(opp)
            near = ok is not None and chess.square_distance(ok, m.to_square) <= 3
            adv = rel(cap_sq, opp) >= 3 or rel(m.to_square, stm) >= 4
            if adv and (ats <= dfs + 1 or passed_after(nb, stm, m.to_square)):
                return True
            if near and ats <= dfs + 2:
                return True
        return False

    if mat >= -180 and safe_ep():
        return True

    qtot = cnt(chess.QUEEN, stm) + cnt(chess.QUEEN, opp)
    if not (-240 <= mat <= 170):
        return False

    pawn_total = cnt(chess.PAWN, stm) + cnt(chess.PAWN, opp)
    locked = center_locked()
    bad_opp = bad_bishop(opp) if cnt(chess.BISHOP, opp) else 0
    safe = qtot == 0 or danger(stm) <= danger(opp) + 2

    if cnt(chess.KNIGHT, stm) and bad_opp >= 6 and safe:
        gk = good_knights(stm)
        okn = good_knights(opp)
        if gk >= 6 and gk + 3 >= okn and (locked or pawn_total >= 12):
            return True

    if qtot == 0 and cnt(chess.KNIGHT, stm) > cnt(chess.KNIGHT, opp) and mat >= -100:
        if bad_opp >= 3 and good_knights(stm) >= 4 and active_king(stm) + 1 >= active_king(opp):
            return True

    if qtot == 0 and bad_opp >= 5:
        ma = minor_activity(stm)
        mb = minor_activity(opp)
        ra = rook_activity(stm)
        rb = rook_activity(opp)
        if ma >= mb + 2 and ra + 2 >= rb and active_king(stm) + 1 >= active_king(opp):
            return True
        if mat >= -60 and ma >= mb and ra >= rb + 4 and weak_pawns(opp) >= weak_pawns(stm):
            return True

    if qtot == 0 and cnt(chess.ROOK, stm) and mat >= -130:
        ra = rook_activity(stm)
        rb = rook_activity(opp)
        wd = weak_pawns(opp) - weak_pawns(stm)
        if ra >= rb + 6 and wd >= 1 and active_king(stm) + 2 >= active_king(opp):
            return True
        if max_rook_rel(stm) >= 5 and ra >= rb + 4 and wd >= 0 and mat >= -70:
            return True

    return False

import chess

MOTIF_NAME = 'safe queen middlegame activity edge'
MOTIF_DESCRIPTION = 'With material roughly level and queens on, the side to move has a safe flank king and a clear activity or target edge.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}
    if board.king(stm) is None or board.king(opp) is None or board.is_check():
        return False
    if len(board.pieces(chess.QUEEN, stm)) == 0 or len(board.pieces(chess.QUEEN, opp)) == 0:
        return False

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def mat(c):
        s = 0
        for pt, v in vals.items():
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 35
        return s

    m = mat(stm) - mat(opp)
    if m > 95 or m < -135:
        return False

    def shield(c):
        k = board.king(c)
        f = chess.square_file(k)
        r = chess.square_rank(k)
        d = 1 if c == chess.WHITE else -1
        s = 0
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf < 8:
                nr = r + d
                if 0 <= nr < 8:
                    p = board.piece_at(chess.square(nf, nr))
                    if p and p.color == c and p.piece_type == chess.PAWN:
                        s += 2
                nr = r + 2 * d
                if 0 <= nr < 8:
                    p = board.piece_at(chess.square(nf, nr))
                    if p and p.color == c and p.piece_type == chess.PAWN:
                        s += 1
        return s

    def risk(c):
        k = board.king(c)
        f = chess.square_file(k)
        r = chess.square_rank(k)
        rr = rel(k, c)
        wt = {chess.PAWN: 1, chess.KNIGHT: 2, chess.BISHOP: 2, chess.ROOK: 3, chess.QUEEN: 4}
        s = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf = f + df
                nr = r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    for a in board.attackers(not c, chess.square(nf, nr)):
                        p = board.piece_at(a)
                        if p:
                            s += wt.get(p.piece_type, 0)
        if rr <= 1 and f in (3, 4):
            s += 8
        if rr <= 1 and f in (0, 1, 2, 5, 6, 7):
            s -= 2
        s -= shield(c)
        return max(0, s)

    def flank_safe(c):
        k = board.king(c)
        f = chess.square_file(k)
        rr = rel(k, c)
        rk = risk(c)
        if rr <= 1 and f in (0, 1, 2, 5, 6, 7):
            return shield(c) >= 2 and rk <= 14
        if rr == 2 and f in (0, 1, 6, 7):
            return rk <= 9
        return False

    if not flank_safe(stm):
        return False

    def file_pawn(f, c):
        for sq in board.pieces(chess.PAWN, c):
            if chess.square_file(sq) == f:
                return True
        return False

    def pawn_attacked_by(c, sq):
        for a in board.attackers(c, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    def passed_score(c):
        e = not c
        s = 0
        for sq in board.pieces(chess.PAWN, c):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            rr = rel(sq, c)
            blocked = False
            ranks = range(r + 1, 8) if c == chess.WHITE else range(r - 1, -1, -1)
            for nf in range(max(0, f - 1), min(7, f + 1) + 1):
                for nr in ranks:
                    p = board.piece_at(chess.square(nf, nr))
                    if p and p.color == e and p.piece_type == chess.PAWN:
                        blocked = True
                        break
                if blocked:
                    break
            if not blocked:
                add = rr * 5
                if rr >= 4:
                    add += 8
                if len(board.attackers(c, sq)):
                    add += 4
                s += add
        return s

    def activity(c):
        e = not c
        s = 0
        for sq in board.pieces(chess.PAWN, c):
            f = chess.square_file(sq)
            rr = rel(sq, c)
            if 2 <= f <= 5 and rr >= 2:
                s += (rr - 1) * 3
            if rr >= 4:
                s += 3
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, c):
                f = chess.square_file(sq)
                rr = rel(sq, c)
                mob = 0
                for t in board.attacks(sq):
                    p = board.piece_at(t)
                    if p is None or p.color != c:
                        mob += 1
                if pt == chess.KNIGHT:
                    s += mob * 2
                    if 2 <= f <= 5:
                        s += 5
                    if 2 <= f <= 5 and rr >= 3:
                        s += 13
                    if f in (0, 7):
                        s -= 14
                    elif f in (1, 6) and rr >= 3:
                        s -= 5
                    if rr <= 1:
                        s -= 4
                    if 2 <= f <= 5 and rr >= 3 and len(board.attackers(c, sq)) and not pawn_attacked_by(e, sq):
                        s += 8
                elif pt == chess.BISHOP:
                    s += mob * 2
                    if mob >= 7:
                        s += 6
                    if rr <= 1 and mob <= 3:
                        s -= 8
                elif pt == chess.ROOK:
                    s += mob
                    ownp = file_pawn(f, c)
                    enemyp = file_pawn(f, e)
                    if not ownp and not enemyp:
                        s += 14
                    elif not ownp and enemyp:
                        s += 8
                    if rr == 6:
                        s += 18
                    elif rr == 5:
                        s += 8
                    if f in (3, 4) and not ownp:
                        s += 5
                else:
                    s += mob // 2
                    if 2 <= f <= 5 and 2 <= rr <= 4:
                        s += 5
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 15
        for csq in (chess.D4, chess.E4, chess.D5, chess.E5):
            s += 2 * len(board.attackers(c, csq))
            p = board.piece_at(csq)
            if p and p.color == c:
                s += 7 if p.piece_type == chess.PAWN else 5
        return s

    def target_score(c):
        e = not c
        bases = {chess.KNIGHT: 16, chess.BISHOP: 16, chess.ROOK: 28, chess.QUEEN: 42}
        s = 0
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, e):
                att = board.attackers(c, sq)
                if not att:
                    continue
                defs = board.attackers(e, sq)
                low = False
                pawnhit = False
                for a in att:
                    ap = board.piece_at(a)
                    if ap:
                        if ap.piece_type == chess.PAWN:
                            pawnhit = True
                        if vals.get(ap.piece_type, 10000) < vals[pt]:
                            low = True
                if not defs:
                    s += bases[pt]
                elif len(att) > len(defs) and low:
                    s += bases[pt] // 2
                elif pawnhit:
                    s += 8
        return s

    au = activity(stm)
    ao = activity(opp)
    tu = target_score(stm)
    to = target_score(opp)
    ku = risk(stm)
    ko = risk(opp)
    pd = passed_score(stm) - passed_score(opp)
    if ku > 14 or ku > ko + 6 or to > tu + 24:
        return False
    score = (au - ao) + (tu - to) + 3 * (ko - ku) + pd + m // 20
    return score >= 38 and (au >= ao + 16 or tu >= to + 16 or ko >= ku + 5 or pd >= 16)

import chess

MOTIF_NAME = 'compensated central bind and rook-pair edge'
MOTIF_DESCRIPTION = 'Without a large raw material edge, the side to move has a compensated positional bind from an exposed central king, an active rook-pair imbalance, or a central pawn grip against unchallenged bishops.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def val(pt):
        if pt == chess.PAWN:
            return 1
        if pt in (chess.KNIGHT, chess.BISHOP):
            return 3
        if pt == chess.ROOK:
            return 5
        if pt == chess.QUEEN:
            return 9
        return 0

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def material(color):
        s = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            s += val(pt) * len(board.pieces(pt, color))
        return s

    raw_adv = material(stm) - material(opp)
    stm_b = len(board.pieces(chess.BISHOP, stm))
    opp_b = len(board.pieces(chess.BISHOP, opp))
    stm_min = stm_b + len(board.pieces(chess.KNIGHT, stm))
    opp_min = opp_b + len(board.pieces(chess.KNIGHT, opp))

    eligible = raw_adv == 0 or (raw_adv == 1 and (opp_min > stm_min or (opp_b >= 2 and stm_b < 2)))
    if not eligible:
        return False

    own_k = board.king(stm)
    opp_k = board.king(opp)
    if own_k is None or opp_k is None:
        return False

    def own_king_ok():
        f = chess.square_file(own_k)
        rr = rel(own_k, stm)
        if rr <= 1 and (f <= 2 or f >= 5):
            return True
        return rr == 0 and (board.has_kingside_castling_rights(stm) or board.has_queenside_castling_rights(stm))

    if not own_king_ok():
        return False

    def home_back_pieces(color):
        home = 0 if color == chess.WHITE else 7
        c = 0
        for sq, p in board.piece_map().items():
            if p.color == color and p.piece_type not in (chess.PAWN, chess.KING) and chess.square_rank(sq) == home:
                c += 1
        return c

    def semiopen_rook(color):
        pawns = board.pieces(chess.PAWN, color)
        for r in board.pieces(chess.ROOK, color):
            f = chess.square_file(r)
            if f in (1, 2, 3, 4, 5, 6):
                blocked = False
                for psq in pawns:
                    if chess.square_file(psq) == f:
                        blocked = True
                        break
                if not blocked:
                    return True
        return False

    def deep_safe_minor():
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if rel(sq, stm) >= 5:
                    ea = len(board.attackers(opp, sq))
                    if ea == 0 or len(board.attackers(stm, sq)) >= ea:
                        return True
        return False

    def zone_attackers():
        kf = chess.square_file(opp_k)
        kr = chess.square_rank(opp_k)
        seen = set()
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df
                r = kr + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    for a in board.attackers(stm, chess.square(f, r)):
                        p = board.piece_at(a)
                        if p and p.color == stm and p.piece_type != chess.KING:
                            seen.add(a)
        return len(seen)

    def active_pieces():
        c = 0
        for sq, p in board.piece_map().items():
            if p.color != stm or p.piece_type in (chess.PAWN, chess.KING):
                continue
            rr = rel(sq, stm)
            if p.piece_type == chess.QUEEN and rr >= 1:
                c += 1
            elif p.piece_type in (chess.KNIGHT, chess.BISHOP) and rr >= 2:
                c += 1
            elif p.piece_type == chess.ROOK and (rr >= 1 or semiopen_rook(stm)):
                c += 1
        return c

    okf = chess.square_file(opp_k)
    okr = rel(opp_k, stm)
    central_king = 2 <= okf <= 5 and okr >= 5
    back = home_back_pieces(opp)
    rook_edge = len(board.pieces(chess.ROOK, stm)) > len(board.pieces(chess.ROOK, opp)) and opp_min > stm_min

    if central_king and back >= 2:
        if deep_safe_minor() or (zone_attackers() >= 2 and active_pieces() >= 3) or (semiopen_rook(stm) and active_pieces() >= 3):
            return True

    if rook_edge and semiopen_rook(stm) and (central_king or back >= 3 or deep_safe_minor()):
        return True

    if raw_adv == 1 and opp_b >= 2 and stm_b < 2 and len(board.pieces(chess.KNIGHT, opp)) == 0 and len(board.pieces(chess.KNIGHT, stm)) > 0:
        cps = []
        for sq in board.pieces(chess.PAWN, stm):
            f = chess.square_file(sq)
            rr = rel(sq, stm)
            if 2 <= f <= 5 and 3 <= rr <= 5:
                cps.append((f, rr, sq))
        for i in range(len(cps)):
            for j in range(i + 1, len(cps)):
                if abs(cps[i][0] - cps[j][0]) == 1 and abs(cps[i][1] - cps[j][1]) <= 1:
                    if len(board.attackers(stm, cps[i][2])) > 0 or len(board.attackers(stm, cps[j][2])) > 0:
                        return True

    return False

import chess

MOTIF_NAME = 'balanced file battery against an uncastled king'
MOTIF_DESCRIPTION = 'With material close, the side to move has a major-piece file battery, active bishops, or a protected spear aimed at an uncastled opponent king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

    def rr(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def ff(s):
        return chess.square_file(s)

    def sq_rel(f, rel, c):
        return chess.square(f, rel if c == chess.WHITE else 7 - rel)

    def material():
        a = 0
        for pt, v in vals.items():
            a += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        return a

    mat = material()
    if mat < -140 or mat > 140:
        return False

    sk = board.king(stm)
    ok = board.king(opp)
    if sk is None or ok is None:
        return False

    def has_castle(c):
        return board.has_kingside_castling_rights(c) or board.has_queenside_castling_rights(c)

    def shield(c):
        k = board.king(c)
        if k is None:
            return 0
        f = ff(k)
        base = chess.square_rank(k)
        step = 1 if c == chess.WHITE else -1
        n = 0
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf < 8:
                r1 = base + step
                r2 = base + 2 * step
                if 0 <= r1 < 8:
                    p = board.piece_at(chess.square(nf, r1))
                    if p and p.color == c and p.piece_type == chess.PAWN:
                        n += 2
                if 0 <= r2 < 8:
                    p = board.piece_at(chess.square(nf, r2))
                    if p and p.color == c and p.piece_type == chess.PAWN:
                        n += 1
        return n

    def flank_safe(c):
        k = board.king(c)
        if k is None:
            return False
        return (ff(k) <= 2 or ff(k) >= 5) and shield(c) >= 2

    def home_king(c):
        k = board.king(c)
        return k is not None and 2 <= ff(k) <= 5 and rr(k, c) <= 1

    def developed(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                if rr(s, c) >= 1:
                    n += 1
                if rr(s, c) >= 3:
                    n += 1
        for r in board.pieces(chess.ROOK, c):
            if rr(r, c) >= 1:
                n += 1
            blocked = False
            for p in board.pieces(chess.PAWN, c):
                if ff(p) == ff(r):
                    blocked = True
            if not blocked:
                n += 1
        return n

    own_ok = flank_safe(stm) or has_castle(stm) or developed(stm) >= developed(opp) + 2
    opp_home = home_king(opp)

    def major_file_battery():
        if not (own_ok and (opp_home or rr(ok, opp) <= 2)):
            return False
        kf = ff(ok)
        majors = list(board.pieces(chess.ROOK, stm)) + list(board.pieces(chess.QUEEN, stm))
        for f in range(8):
            if abs(f - kf) > 1:
                continue
            ms = [s for s in majors if ff(s) == f]
            if len(ms) < 2:
                continue
            own_pawn = False
            for p in board.pieces(chess.PAWN, stm):
                if ff(p) == f:
                    own_pawn = True
            if own_pawn:
                continue
            best = ms[0]
            for s in ms:
                if rr(s, stm) > rr(best, stm):
                    best = s
            if rr(best, stm) < 2:
                continue
            blockers = 0
            target = False
            start = rr(best, stm) + 1
            for rel in range(start, 8):
                q = board.piece_at(sq_rel(f, rel, stm))
                if q:
                    if q.color == stm:
                        blockers += 2
                    else:
                        blockers += 1
                        if q.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                            if chess.square_distance(sq_rel(f, rel, stm), ok) <= 2 or rel >= 5:
                                target = True
            if blockers <= 2 and (target or rr(ok, opp) <= 1):
                return True
        return False

    def active_bishops():
        bs = list(board.pieces(chess.BISHOP, stm))
        if len(bs) < 2 or not opp_home:
            return False
        if not (has_castle(stm) or flank_safe(stm) or developed(stm) >= developed(opp)):
            return False
        active = 0
        pressure = 0
        for b in bs:
            if rr(b, stm) >= 1:
                active += 1
            for t in board.attacks(b):
                if chess.square_distance(t, ok) <= 2:
                    pressure += 1
                q = board.piece_at(t)
                if q and q.color == opp:
                    if q.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                        if chess.square_distance(t, ok) <= 3 or rr(t, opp) <= 3:
                            pressure += 1
                    elif q.piece_type == chess.PAWN and 2 <= ff(t) <= 5 and rr(t, opp) <= 2:
                        pressure += 1
        return active >= 2 and pressure >= 3

    def rook_lift_hit():
        if not (flank_safe(stm) and (opp_home or shield(opp) <= 1)):
            return False
        for r in board.pieces(chess.ROOK, stm):
            if rr(r, stm) < 3:
                continue
            pawn_hit = False
            for a in board.attackers(opp, r):
                q = board.piece_at(a)
                if q and q.piece_type == chess.PAWN:
                    pawn_hit = True
            if pawn_hit:
                continue
            if len(board.attackers(opp, r)) > len(board.attackers(stm, r)):
                continue
            for t in board.attacks(r):
                q = board.piece_at(t)
                if q and q.color == opp and q.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                    if len(board.attackers(stm, t)) >= len(board.attackers(opp, t)):
                        return True
        return False

    def king_spear():
        if not opp_home:
            return False
        kf = ff(ok)
        heavy = False
        for h in list(board.pieces(chess.ROOK, stm)) + list(board.pieces(chess.QUEEN, stm)):
            if abs(ff(h) - kf) <= 1 and rr(h, stm) <= 2:
                heavy = True
        if not heavy:
            return False
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, stm):
                if rr(s, stm) >= 3 and chess.square_distance(s, ok) <= 4:
                    ring = False
                    for t in board.attacks(s):
                        if chess.square_distance(t, ok) <= 1:
                            ring = True
                    if ring and len(board.attackers(opp, s)) <= len(board.attackers(stm, s)) + 1:
                        return True
        for p in board.pieces(chess.PAWN, stm):
            if rr(p, stm) >= 3 and chess.square_distance(p, ok) <= 3:
                for t in board.attacks(p):
                    if chess.square_distance(t, ok) <= 1 and len(board.attackers(stm, p)) >= 1:
                        return True
        return False

    def file_xray_pin():
        if not opp_home:
            return False
        kf = ff(ok)
        for h in list(board.pieces(chess.ROOK, stm)) + list(board.pieces(chess.QUEEN, stm)):
            if ff(h) != kf:
                continue
            rh = chess.square_rank(h)
            rk = chess.square_rank(ok)
            step = 1 if rk > rh else -1
            blocks = []
            friendly_pawn = False
            for r in range(rh + step, rk, step):
                s = chess.square(kf, r)
                q = board.piece_at(s)
                if q:
                    blocks.append(s)
                    if q.color == stm and q.piece_type == chess.PAWN:
                        friendly_pawn = True
            if friendly_pawn or len(blocks) != 1:
                continue
            b = blocks[0]
            q = board.piece_at(b)
            if q and q.color == opp and q.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                if len(board.attackers(stm, h)) or flank_safe(stm) or has_castle(stm):
                    return True
        return False

    return major_file_battery() or active_bishops() or rook_lift_hit() or king_spear() or file_xray_pin()

import chess

MOTIF_NAME = 'material-neutral mobility and development bind'
MOTIF_DESCRIPTION = 'With no pawn-up material edge, the side to move has a clear mobility, space, development, or active-rook bind.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    vals = {
        chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
        chess.ROOK: 500, chess.QUEEN: 900
    }

    def rr(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def material(c):
        return sum(vals[p] * len(board.pieces(p, c)) for p in vals)

    mat = material(stm) - material(opp)
    if mat > 80 or mat < -220 or board.is_check():
        return False

    def shelter(c):
        k = board.king(c)
        if k is None:
            return 0
        f = chess.square_file(k)
        r = chess.square_rank(k)
        d = 1 if c == chess.WHITE else -1
        sc = 1 if f <= 2 or f >= 5 else -1
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf < 8:
                for step, val in ((1, 2), (2, 1)):
                    nr = r + d * step
                    if 0 <= nr < 8:
                        p = board.piece_at(chess.square(nf, nr))
                        if p and p.color == c and p.piece_type == chess.PAWN:
                            sc += val
        atk = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8 and board.attackers(not c, chess.square(nf, nr)):
                    atk += 1
        return sc - atk // 2

    centers = [chess.D4, chess.E4, chess.D5, chess.E5]

    def center(c):
        sc = 0
        for sq in centers:
            sc += len(board.attackers(c, sq))
            p = board.piece_at(sq)
            if p and p.color == c:
                sc += 2 if p.piece_type == chess.PAWN else 1
        return sc

    def space(c):
        sc = 0
        for sq in board.pieces(chess.PAWN, c):
            f = chess.square_file(sq)
            rel = rr(sq, c)
            if 2 <= f <= 5:
                if rel >= 3:
                    sc += 1
                if rel >= 4:
                    sc += 1
            elif rel >= 4:
                sc += 1
        return sc

    def rookact(c):
        e = not c
        sc = 0
        ownp = board.pieces(chess.PAWN, c)
        enp = board.pieces(chess.PAWN, e)
        for sq in board.pieces(chess.ROOK, c):
            f = chess.square_file(sq)
            of = any(chess.square_file(p) == f for p in ownp)
            ef = any(chess.square_file(p) == f for p in enp)
            if not of:
                sc += 1
            if not of and not ef:
                sc += 1
            rel = rr(sq, c)
            if rel >= 5:
                sc += 1
            if rel >= 6:
                sc += 2
            targets = 0
            for t in board.attacks(sq):
                p = board.piece_at(t)
                if p and p.color == e and p.piece_type != chess.KING:
                    targets += 1
            if targets >= 2:
                sc += 1
            if targets >= 3:
                sc += 1
        return sc

    def pressure(c, ksq):
        if ksq is None:
            return 0
        f = chess.square_file(ksq)
        r = chess.square_rank(ksq)
        sc = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    for a in board.attackers(c, chess.square(nf, nr)):
                        p = board.piece_at(a)
                        if p:
                            if p.piece_type == chess.QUEEN:
                                sc += 3
                            elif p.piece_type == chess.ROOK:
                                sc += 2
                            else:
                                sc += 1
        return sc

    def dev(c):
        home = 0 if c == chess.WHITE else 7
        sc = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, c):
                if chess.square_rank(sq) != home:
                    sc += 2
                if 2 <= chess.square_file(sq) <= 5 and rr(sq, c) >= 3:
                    sc += 1
        for sq in board.pieces(chess.QUEEN, c):
            if chess.square_rank(sq) != home:
                sc += 1
        for sq in board.pieces(chess.ROOK, c):
            if chess.square_rank(sq) != home:
                sc += 1
            if 2 <= chess.square_file(sq) <= 5:
                sc += 1
        k = board.king(c)
        if k is not None and not (chess.square_file(k) == 4 and chess.square_rank(k) == home):
            sc += 1
        return sc

    b2 = board.copy(stack=False)
    b2.turn = opp
    b2.ep_square = None
    medge = board.legal_moves.count() - b2.legal_moves.count()
    cedge = center(stm) - center(opp)
    sedge = space(stm) - space(opp)
    redge = rookact(stm) - rookact(opp)
    pedge = pressure(stm, board.king(opp)) - pressure(opp, board.king(stm))
    safe = shelter(stm) - shelter(opp)
    dedge = dev(stm) - dev(opp)

    ok = board.king(opp)
    central_king = ok is not None and 2 <= chess.square_file(ok) <= 5 and rr(ok, opp) <= 1

    if central_king and safe >= 0 and dedge >= 2 and (cedge >= 2 or medge >= 4 or sedge >= 2):
        return True
    if medge >= 8 and safe >= -2 and (cedge + sedge + redge >= 4 or pedge >= 4):
        return True
    if medge >= 4 and safe >= -1 and cedge >= 3 and sedge >= 2:
        return True
    if redge >= 3 and medge >= 0 and pedge >= 3 and safe >= -4:
        return True
    return False

import chess

MOTIF_NAME = 'balanced safe advanced knight post'
MOTIF_DESCRIPTION = 'The side to move is not relying on a large material edge and has the better safe central knight advanced into the opponent half.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm
    vals = ((chess.PAWN, 100), (chess.KNIGHT, 320), (chess.BISHOP, 330), (chess.ROOK, 500), (chess.QUEEN, 900))

    def material(c):
        s = 0
        for pt, v in vals:
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 45
        return s

    bal = material(stm) - material(opp)
    if bal < -90 or bal > 170:
        return False

    q_present = bool(board.pieces(chess.QUEEN, chess.WHITE)) or bool(board.pieces(chess.QUEEN, chess.BLACK))

    def rel_rank(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def king_zone(c):
        ks = list(board.pieces(chess.KING, c))
        if not ks:
            return set()
        k = ks[0]
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        z = set()
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    z.add(chess.square(f, r))
        return z

    def stable_knight_score(c):
        e = not c
        z = king_zone(e)
        best = 0
        for sq in board.pieces(chess.KNIGHT, c):
            if board.is_pinned(c, sq):
                continue
            f = chess.square_file(sq)
            rr = rel_rank(sq, c)
            if f < 2 or f > 5 or rr < 3:
                continue
            pawn_hit = False
            for a in board.attackers(e, sq):
                p = board.piece_at(a)
                if p and p.piece_type == chess.PAWN:
                    pawn_hit = True
                    break
            if pawn_hit:
                continue
            own_def = 0
            enemy_atk = 0
            for a in board.attackers(c, sq):
                p = board.piece_at(a)
                if p and p.piece_type != chess.KING:
                    own_def += 1
            for a in board.attackers(e, sq):
                p = board.piece_at(a)
                if p and p.piece_type != chess.KING:
                    enemy_atk += 1
            if enemy_atk > own_def:
                continue

            targets = 0
            zone_hits = 0
            for t in board.attacks(sq):
                if t in z:
                    zone_hits += 1
                p = board.piece_at(t)
                if p and p.color == e:
                    if p.piece_type == chess.PAWN:
                        targets += 1
                    elif p.piece_type in (chess.KNIGHT, chess.BISHOP):
                        targets += 2
                    elif p.piece_type == chess.ROOK:
                        targets += 3
                    elif p.piece_type == chess.QUEEN:
                        targets += 4

            score = rr + 1 + targets + min(3, zone_hits)
            if rr >= 4 and score >= 7:
                best = max(best, score)
            elif rr == 3 and not q_present and score >= 5:
                best = max(best, score)
            elif rr == 3 and q_present and score >= 8:
                best = max(best, score)
        return best

    us = stable_knight_score(stm)
    them = stable_knight_score(opp)
    return us >= 6 and us >= them + 2

import chess

MOTIF_NAME = 'balanced queen-zone storm or central pin'
MOTIF_DESCRIPTION = 'With material still roughly balanced, the side to move has queen-zone pressure, a pawn storm, or a pinning slider against a poorly sheltered opposing king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    ku = board.king(stm)
    kt = board.king(opp)
    if ku is None or kt is None or board.is_check():
        return False

    vals = ((chess.PAWN, 100), (chess.KNIGHT, 320), (chess.BISHOP, 330), (chess.ROOK, 500), (chess.QUEEN, 900))

    def mat(c):
        s = 0
        for pt, v in vals:
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 25
        return s

    m = mat(stm) - mat(opp)
    if m < -175 or m > 275:
        return False

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    uf = chess.square_file(ku)
    if rel(ku, stm) <= 1 and uf in (3, 4):
        return False

    def near_squares(k, dist):
        out = []
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        for f in range(max(0, kf - dist), min(7, kf + dist) + 1):
            for r in range(max(0, kr - dist), min(7, kr + dist) + 1):
                s = chess.square(f, r)
                if s != k and chess.square_distance(s, k) <= dist:
                    out.append(s)
        return out

    ring = near_squares(kt, 1)
    zone = near_squares(kt, 2)

    def shield(c, k):
        f = chess.square_file(k)
        r = chess.square_rank(k)
        step = 1 if c == chess.WHITE else -1
        nr = r + step
        if nr < 0 or nr > 7:
            return 0
        n = 0
        for df in (-1, 0, 1):
            nf = f + df
            if 0 <= nf <= 7:
                p = board.piece_at(chess.square(nf, nr))
                if p and p.color == c and p.piece_type == chess.PAWN:
                    n += 1
        return n

    def attack_units(c, squares):
        u = 0
        for s in squares:
            for a in board.attackers(c, s):
                p = board.piece_at(a)
                if p is None:
                    continue
                if p.piece_type == chess.QUEEN:
                    u += 3
                elif p.piece_type in (chess.ROOK, chess.BISHOP, chess.KNIGHT):
                    u += 2
                else:
                    u += 1
        return u

    sh = shield(opp, kt)
    kf = chess.square_file(kt)
    center = rel(kt, opp) <= 1 and 2 <= kf <= 5
    opp_units = attack_units(stm, ring)
    own_units = attack_units(opp, near_squares(ku, 1))
    if own_units >= 5 and own_units > opp_units + 2:
        return False

    storm = False
    for p in board.pieces(chess.PAWN, stm):
        if rel(p, stm) >= 3 and abs(chess.square_file(p) - kf) <= 1:
            storm = True
            break

    best_qhits = 0
    qpress = False
    for q in board.pieces(chess.QUEEN, stm):
        if board.attackers(opp, q) and not board.attackers(stm, q):
            continue
        att = board.attacks(q)
        hits = 0
        for s in zone:
            pc = board.piece_at(s)
            if s in att and (pc is None or pc.color == opp):
                hits += 1
        if hits > best_qhits:
            best_qhits = hits
        if hits >= 2 or (hits >= 1 and chess.square_distance(q, kt) <= 4):
            qpress = True

    if qpress:
        if storm and (best_qhits >= 2 or m >= 0):
            return True
        if sh <= 1 and (m >= 0 or opp_units >= 3):
            return True
        if center and sh <= 2 and best_qhits >= 2 and (m >= 0 or opp_units >= 3):
            return True

    def slider_pin(sq, pt):
        af = chess.square_file(sq)
        ar = chess.square_rank(sq)
        bf = chess.square_file(kt)
        br = chess.square_rank(kt)
        df = bf - af
        dr = br - ar
        diag = abs(df) == abs(dr) and df != 0
        ortho = (df == 0 or dr == 0) and (df != 0 or dr != 0)
        if pt == chess.BISHOP and not diag:
            return False
        if pt == chess.ROOK and not ortho:
            return False
        if pt == chess.QUEEN and not (diag or ortho):
            return False
        sf = 0 if df == 0 else (1 if df > 0 else -1)
        sr = 0 if dr == 0 else (1 if dr > 0 else -1)
        f = af + sf
        r = ar + sr
        blockers = []
        while f != bf or r != br:
            s = chess.square(f, r)
            pc = board.piece_at(s)
            if pc:
                blockers.append(pc.color)
            f += sf
            r += sr
        return len(blockers) == 1 and blockers[0] == opp

    line = False
    for pt in (chess.BISHOP, chess.ROOK, chess.QUEEN):
        for sq in board.pieces(pt, stm):
            if slider_pin(sq, pt):
                line = True
                break
        if line:
            break

    return bool(line and center and sh <= 1 and (m >= -100 or opp_units >= 2))

