MOTIF_NAME = 'piece quality targets or stranded central king'
MOTIF_DESCRIPTION = 'With material roughly balanced, the side to move has either active pieces for pawns with a loose target or a safe flank king against a stranded central enemy king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    vals = {
        chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
        chess.ROOK: 500, chess.QUEEN: 900
    }

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def passed_pawn(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        step = 1 if color == chess.WHITE else -1
        for df in (-1, 0, 1):
            ff = f + df
            if 0 <= ff <= 7:
                rr = r + step
                while 0 <= rr <= 7:
                    p = board.piece_at(chess.square(ff, rr))
                    if p and p.color != color and p.piece_type == chess.PAWN:
                        return False
                    rr += step
        return True

    mat = 0
    nonpawn = 0
    for pt, v in vals.items():
        d = len(board.pieces(pt, stm)) - len(board.pieces(pt, opp))
        mat += v * d
        if pt != chess.PAWN:
            nonpawn += v * d
    pawn_diff = len(board.pieces(chess.PAWN, stm)) - len(board.pieces(chess.PAWN, opp))

    dangerous = False
    for sq in board.pieces(chess.PAWN, opp):
        if rel(sq, opp) >= 4 and passed_pawn(sq, opp):
            dangerous = True
            break

    loose_target = False
    if -180 <= mat <= 150 and nonpawn >= 180 and pawn_diff <= -2 and not dangerous:
        for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
            for t in board.pieces(pt, opp):
                us = len(board.attackers(stm, t))
                if us:
                    pawn_def = False
                    for a in board.attackers(opp, t):
                        p = board.piece_at(a)
                        if p and p.piece_type == chess.PAWN:
                            pawn_def = True
                            break
                    if not pawn_def and us >= len(board.attackers(opp, t)):
                        loose_target = True
                        break
            if loose_target:
                return True

    mk = board.king(stm)
    ok = board.king(opp)
    if mk is None or ok is None:
        return False

    mf = chess.square_file(mk)
    of = chess.square_file(ok)
    er = rel(ok, stm)
    own_safe = rel(mk, stm) <= 1 and (mf <= 2 or mf >= 5)

    if own_safe and -120 <= mat <= 120 and 2 <= of <= 5:
        rooks = len(board.pieces(chess.ROOK, stm))
        queens = len(board.pieces(chess.QUEEN, stm))
        if 4 <= er <= 6 and (rooks >= 2 or queens >= 1):
            return True

        if er == 7 and not board.has_castling_rights(opp) and queens >= 1:
            kf = chess.square_file(ok)
            kr = chess.square_rank(ok)
            pressure = 0
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    ff = kf + df
                    rr = kr + dr
                    if 0 <= ff <= 7 and 0 <= rr <= 7:
                        pressure += len(board.attackers(stm, chess.square(ff, rr)))
            if pressure >= 3:
                return True
            for mv in board.legal_moves:
                if board.gives_check(mv):
                    return True

    return False

