import math

MOTIF_NAME = 'protected queen chase and deep spear'
MOTIF_DESCRIPTION = 'Without a large material edge, the side to move has a protected lesser-piece tempo on the enemy queen, a deep safe queen invasion, or an immediate favorable capture.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None:
        return False

    def rel(sq, c=stm):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def mat(c):
        s = 0.0
        for pt, v in vals.items():
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 0.25
        return s

    md = mat(stm) - mat(opp)
    if md > 1.7 or md < -2.6:
        return False

    def zone(k):
        f = chess.square_file(k)
        r = chess.square_rank(k)
        out = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    out.append(chess.square(nf, nr))
        return out

    kz_own = zone(mk)
    kz_enemy = zone(ek)
    own_danger = sum(len(board.attackers(opp, s)) for s in kz_own)
    enemy_pressure = sum(len(board.attackers(stm, s)) for s in kz_enemy)
    fairly_safe = (not board.is_check()) and own_danger <= 6
    moves = list(board.legal_moves)

    def pawn_attacked_by(c, sq):
        for a in board.attackers(c, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    def good_capture():
        if md < -2.2:
            return False
        for mv in moves:
            pc = board.piece_at(mv.from_square)
            cap = board.piece_at(mv.to_square)
            if not pc or pc.color != stm or not cap or cap.color != opp:
                continue
            if pc.piece_type == chess.KING or cap.piece_type == chess.KING:
                continue
            pv = vals.get(pc.piece_type, 0)
            cv = vals.get(cap.piece_type, 0)
            if cv - pv >= 2 and pv <= 5:
                return fairly_safe or cv >= 9 or board.gives_check(mv)
        return False

    def queen_chase():
        if md < -1.4 or (not fairly_safe and own_danger > enemy_pressure + 1):
            return False
        qs = list(board.pieces(chess.QUEEN, opp))
        if not qs:
            return False
        for qsq in qs:
            qf = chess.square_file(qsq)
            qedge = qf in (0, 7) or chess.square_rank(qsq) in (0, 7)
            qrel = rel(qsq)
            for mv in moves:
                pc = board.piece_at(mv.from_square)
                if not pc or pc.color != stm or pc.piece_type in (chess.KING, chess.QUEEN):
                    continue
                pv = vals.get(pc.piece_type, 0)
                if pv == 0 or pv > 5:
                    continue
                if mv.to_square == qsq:
                    return True
                if mv.promotion or qsq in board.attacks(mv.from_square):
                    continue
                board.push(mv)
                np = board.piece_at(mv.to_square)
                ok = False
                if np and np.color == stm and qsq in board.attacks(mv.to_square):
                    att = len(board.attackers(opp, mv.to_square))
                    deff = len(board.attackers(stm, mv.to_square))
                    gives = board.is_check()
                    if pc.piece_type == chess.ROOK:
                        ok = (qedge or qrel <= 3 or qrel >= 5) and deff > 0 and deff >= att
                    else:
                        active = rel(mv.to_square) >= 3 or chess.square_distance(mv.to_square, ek) <= 4 or gives
                        ok = active and (att == 0 or deff >= att or (pc.piece_type == chess.PAWN and deff + 1 >= att))
                board.pop()
                if ok:
                    return True
        return False

    def deep_queen():
        if md < -1.5 or (not fairly_safe and own_danger > enemy_pressure):
            return False
        for q in board.pieces(chess.QUEEN, stm):
            rq = rel(q)
            if rq < 5:
                continue
            if pawn_attacked_by(opp, q):
                continue
            if len(board.attackers(opp, q)) > len(board.attackers(stm, q)) + 1:
                continue
            qa = board.attacks(q)
            hits = sum(1 for s in kz_enemy if s in qa)
            targets = 0
            high = 0
            for s in qa:
                p = board.piece_at(s)
                if p and p.color == opp and p.piece_type != chess.KING:
                    targets += 1
                    if p.piece_type in (chess.ROOK, chess.QUEEN):
                        high += 1
            if chess.square_distance(q, ek) <= 3 and hits:
                return True
            if rq >= 6 and (hits or targets >= 2 or high):
                return True
        return False

    return queen_chase() or deep_queen() or good_capture()

