MOTIF_NAME = 'material-parity forcing gain or mobile bishop pair'
MOTIF_DESCRIPTION = 'With no existing material edge, the side to move has either an immediate material-winning tactic or an active bishop pair against a side without one.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {
        chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
        chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 20000
    }

    def mat(c):
        s = 0
        for pt, v in vals.items():
            if pt != chess.KING:
                s += v * len(board.pieces(pt, c))
        return s

    bal = mat(stm) - mat(opp)
    if bal > 90:
        return False

    bs = list(board.pieces(chess.BISHOP, stm))
    if bal >= -90 and len(bs) >= 2 and len(board.pieces(chess.BISHOP, opp)) < 2 and not board.is_check():
        mob = 0
        colors = set()
        for b in bs:
            colors.add((chess.square_file(b) + chess.square_rank(b)) & 1)
            for t in board.attacks(b):
                pc = board.piece_at(t)
                if not pc or pc.color != stm:
                    mob += 1
        pawns = len(board.pieces(chess.PAWN, True)) + len(board.pieces(chess.PAWN, False))
        central = 0
        for f in (3, 4):
            for r in range(8):
                pc = board.piece_at(chess.square(f, r))
                if pc and pc.piece_type == chess.PAWN:
                    central += 1
        if len(colors) == 2 and mob >= 11 and (pawns <= 14 or central <= 3):
            return True

    def safe_after(mv):
        board.push(mv)
        ok = True
        for a in board.attackers(opp, mv.to_square):
            if board.piece_at(a):
                ok = False
                break
        board.pop()
        return ok

    moves = list(board.legal_moves)

    for mv in moves:
        if not board.is_capture(mv):
            continue
        mover = board.piece_at(mv.from_square)
        cap = board.piece_at(mv.to_square)
        if not mover or not cap or cap.color != opp or cap.piece_type == chess.KING:
            continue
        cv = vals[cap.piece_type]
        mv_val = vals[mover.piece_type]
        gain = cv - mv_val
        if gain >= 160 and bal + gain >= -50:
            return True
        if cv >= 320 and bal + cv >= 0 and safe_after(mv):
            return True

    for mv in moves:
        if not board.gives_check(mv):
            continue
        mover = board.piece_at(mv.from_square)
        if not mover or mover.piece_type == chess.KING:
            continue
        board.push(mv)
        mp = board.piece_at(mv.to_square)
        if mp:
            mvv = vals[mp.piece_type]
            unsafe = False
            for a in board.attackers(opp, mv.to_square):
                p = board.piece_at(a)
                if p and p.piece_type != chess.KING and vals[p.piece_type] <= mvv:
                    unsafe = True
                    break
            if not unsafe:
                for t in board.attacks(mv.to_square):
                    pc = board.piece_at(t)
                    if pc and pc.color == opp and pc.piece_type in (chess.QUEEN, chess.ROOK):
                        if vals[pc.piece_type] >= mvv and bal + vals[pc.piece_type] >= 0:
                            board.pop()
                            return True
        board.pop()

    return False

