def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    mat = 0
    for p in board.piece_map().values():
        v = vals.get(p.piece_type, 0)
        mat += v if p.color == stm else -v

    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None:
        return False

    def rr(sq):
        r = chess.square_rank(sq)
        return r if stm == chess.WHITE else 7 - r

    def pawn_atk(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                n += 1
        return n

    queens = bool(board.pieces(chess.QUEEN, stm) or board.pieces(chess.QUEEN, opp))
    mf = chess.square_file(mk)
    king_safe = rr(mk) <= 2 if not queens else (rr(mk) <= 1 and (mf <= 2 or mf >= 5))

    if -1 <= mat <= 1 and king_safe:
        for tsq, pc in board.piece_map().items():
            if pc.color != opp or pc.piece_type not in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
                continue
            if rr(tsq) > 3 or pawn_atk(opp, tsq):
                continue
            ats = []
            for a in board.attackers(stm, tsq):
                ap = board.piece_at(a)
                if ap and ap.color == stm and ap.piece_type != chess.KING:
                    ats.append(a)
            if len(ats) < 2 or len(ats) < len(board.attackers(opp, tsq)) + 1:
                continue
            good = False
            slider = False
            for a in ats:
                ap = board.piece_at(a)
                if ap.piece_type == chess.PAWN or vals.get(ap.piece_type, 0) <= vals[pc.piece_type]:
                    good = True
                if ap.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                    slider = True
            if good and (slider or pc.piece_type == chess.ROOK or rr(tsq) <= 2):
                return True

    if queens or mat < -2 or mat > 1:
        return False

    rooks = list(board.pieces(chess.ROOK, stm))
    if not rooks or rr(mk) > 2:
        return False

    ef = chess.square_file(ek)
    enemy_back = rr(ek) >= 5
    bishop_pair = len(board.pieces(chess.BISHOP, stm)) >= 2

    def no_own_pawn_file(f):
        for p in board.pieces(chess.PAWN, stm):
            if chess.square_file(p) == f:
                return False
        return True

    def rook_ok(sq):
        da = len(board.attackers(stm, sq))
        oa = len(board.attackers(opp, sq))
        if pawn_atk(opp, sq) and da < oa:
            return False
        return oa <= da + 1

    if enemy_back and mat >= 0:
        for rsq in rooks:
            if not rook_ok(rsq):
                continue
            rf = chess.square_file(rsq)
            targets = 0
            valuable = 0
            near = 0
            for t in board.attacks(rsq):
                pc = board.piece_at(t)
                if pc and pc.color == opp and pc.piece_type != chess.KING:
                    targets += 1
                    if pc.piece_type != chess.PAWN:
                        valuable += 1
                    if chess.square_distance(t, ek) <= 2:
                        near += 1
            if rr(rsq) >= 3 and targets and (valuable or targets >= 2 or (len(rooks) >= 2 and abs(rf - ef) <= 3)):
                return True
            if abs(rf - ef) <= 1 and no_own_pawn_file(rf) and near:
