MOTIF_NAME = 'material-parity initiative targets'
MOTIF_DESCRIPTION = 'The side to move is not materially behind or clearly ahead, but has a concrete initiative such as loose-piece pressure, a strong knight, an advanced passer, or a seventh-rank invasion.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    val = {
        chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
        chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 10000
    }

    def material(c):
        return sum(val[pt] * len(board.pieces(pt, c)) for pt in
                   (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN))

    m = material(stm) - material(opp)
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        m += 35
    if len(board.pieces(chess.BISHOP, opp)) >= 2:
        m -= 35
    if m < 0 or m >= 100:
        return False

    def pressure(att, dfc):
        s = 0
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, dfc):
                attackers = []
                for a in board.attackers(att, sq):
                    p = board.piece_at(a)
                    if p and p.color == att:
                        attackers.append(val[p.piece_type])
                if not attackers:
                    continue
                defenders = []
                for d in board.attackers(dfc, sq):
                    p = board.piece_at(d)
                    if p and p.color == dfc and p.piece_type != chess.KING:
                        defenders.append(d)
                mn = min(attackers)
                v = val[pt]
                if not defenders:
                    s += min(v, 400)
                elif mn + 120 < v:
                    s += min(v - mn, 300)
        return s

    def strong_knight(c):
        o = not c
        for sq in board.pieces(chess.KNIGHT, c):
            r = chess.square_rank(sq)
            rel = r if c == chess.WHITE else 7 - r
            if rel < 4:
                continue
            if len(board.attackers(c, sq)) == 0:
                continue
            bad = False
            for a in board.attackers(o, sq):
                p = board.piece_at(a)
                if p and p.color == o and p.piece_type == chess.PAWN:
                    bad = True
            if bad:
                continue
            hits = 0
            major = False
            for t in board.attacks(sq):
                p = board.piece_at(t)
                if p and p.color == o and p.piece_type != chess.KING:
                    hits += 1
                    if p.piece_type in (chess.ROOK, chess.QUEEN):
                        major = True
            if major or hits >= 2:
                return True
        return False

    def advanced_passed(c):
        o = not c
        step = 1 if c == chess.WHITE else -1
        for sq in board.pieces(chess.PAWN, c):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            rel = r if c == chess.WHITE else 7 - r
            if rel < 4:
                continue
            ok = True
            for df in (-1, 0, 1):
                ff = f + df
                if 0 <= ff < 8:
                    rr = r + step
                    while 0 <= rr < 8:
                        p = board.piece_at(chess.square(ff, rr))
                        if p and p.color == o and p.piece_type == chess.PAWN:
                            ok = False
                            break
                        rr += step
                if not ok:
                    break
            if ok:
                front = r + step
                blocked = 0 <= front < 8 and board.piece_at(chess.square(f, front)) is not None
                if (rel >= 5 or not blocked) and (rel >= 5 or len(board.attackers(c, sq)) > 0):
                    return True
        return False

    def invasion(c):
        o = not c
        for pt in (chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, c):
                r = chess.square_rank(sq)
                rel = r if c == chess.WHITE else 7 - r
                if rel != 6:
                    continue
                if len(board.attackers(o, sq)) > 0 and len(board.attackers(c, sq)) == 0:
                    continue
                for t in board.attacks(sq):
                    p = board.piece_at(t)
                    if p and p.color == o and p.piece_type != chess.KING:
                        return True
        return False

    myp = pressure(stm, opp)
    theirp = pressure(opp, stm)
    if myp >= 300 and myp >= theirp + 150:
        return True
    if strong_knight(stm) and not strong_knight(opp):
        return True
    if advanced_passed(stm) and not advanced_passed(opp):
        return True
    if invasion(stm) and not invasion(opp):
        return True
    return False

