def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False

    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    bal = 0
    for pt, v in vals.items():
        bal += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if bal > 0 or bal < -1:
        return False

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def has_castle(color):
        return board.has_kingside_castling_rights(color) or board.has_queenside_castling_rights(color)

    def zone_hits(color, ksq):
        if ksq is None:
            return 0
        f = chess.square_file(ksq)
        r = chess.square_rank(ksq)
        h = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8 and board.attackers(color, chess.square(nf, nr)):
                    h += 1
        return h

    def flank_safe(color):
        k = board.king(color)
        if k is None:
            return False
        f = chess.square_file(k)
        return rel(k, color) <= 1 and (f <= 2 or f >= 5) and zone_hits(not color, k) <= 3

    def developed_minors(color):
        return sum(1 for pt in (chess.KNIGHT, chess.BISHOP) for s in board.pieces(pt, color) if rel(s, color) >= 1)

    def home_minors(color):
        return sum(1 for pt in (chess.KNIGHT, chess.BISHOP) for s in board.pieces(pt, color) if rel(s, color) == 0)

    def major_aim(color, target_file):
        c = 0
        for pt in (chess.ROOK, chess.QUEEN):
            for s in board.pieces(pt, color):
                if rel(s, color) >= 2 and abs(chess.square_file(s) - target_file) <= 1:
                    c += 1
        return c

    own_k = board.king(stm)
    enemy_k = board.king(opp)
    if own_k is None or enemy_k is None:
        return False
    own_calm = zone_hits(opp, own_k) <= 4

    can_castle_now = False
    for mv in board.legal_moves:
        if board.is_castling(mv):
            can_castle_now = True
            break

    ef = chess.square_file(enemy_k)
    er = rel(enemy_k, opp)
    central_lag = 2 <= ef <= 5 and er <= 2 and not has_castle(opp)

    if bal == 0 and own_calm and central_lag:
        ready = developed_minors(stm) + major_aim(stm, ef)
        if ready >= 2 and (can_castle_now or flank_safe(stm)):
            if er >= 1 or home_minors(opp) >= 1 or zone_hits(stm, enemy_k) >= 2:
                return True

    if bal == 0 and own_calm and can_castle_now and not has_castle(opp) and not flank_safe(opp):
        if developed_minors(stm) >= developed_minors(opp) + 1 and home_minors(opp) >= 2:
            return True

    def pawn_attackers(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                n += 1
        return n

    safe_knights = []
    for n in board.pieces(chess.KNIGHT, stm):
        if rel(n, stm) < 4:
            continue
        if pawn_attackers(opp, n):
            continue
        own = len(board.attackers(stm, n))
        enemy = len(board.attackers(opp, n))
        if own >= 1 and enemy <= own + 1:
            safe_knights.append(n)

    if len(safe_knights) >= 2 and own_calm:
        pressure = 0
        for n in safe_knights:
            best = 0
            for t in board.attacks(n):
                pc = board.piece_at(t)
                if pc and pc.color == opp:
                    if pc.piece_type in (chess.ROOK, chess.QUEEN):
                        best = max(best, 2)
                    elif pc.piece_type in (chess.KNIGHT, chess.BISHOP):
                        best = max(best, 1)
                if chess.square_distance(t, enemy_k) <= 1:
                    best = max(best, 1)
            pressure += best
        if pressure >= 2:
            return True

    return False

