    opp = not stm
    ok = board.king(opp)
    if ok is None:
        return False

    def val(pt):
        if pt == chess.PAWN:
            return 1
        if pt == chess.KNIGHT or pt == chess.BISHOP:
            return 3
        if pt == chess.ROOK:
            return 5
        if pt == chess.QUEEN:
            return 9
        return 0

    def mat(color, queens=True):
        s = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            if queens or pt != chess.QUEEN:
                s += val(pt) * len(board.pieces(pt, color))
        return s

    def rel_rank(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def front_square(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq) + (1 if color == chess.WHITE else -1)
        if 0 <= r < 8:
            return chess.square(f, r)
        return None

    def is_passed(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        enemy = not color
        for ep in board.pieces(chess.PAWN, enemy):
            ef = chess.square_file(ep)
            er = chess.square_rank(ep)
            if abs(ef - f) <= 1:
                if color == chess.WHITE and er > r:
                    return False
                if color == chess.BLACK and er < r:
                    return False
        return True

    def dangerous_passed_best(color):
        enemy = not color
        best = 0
        for sq in board.pieces(chess.PAWN, color):
            rr = rel_rank(sq, color)
            fs = front_square(sq, color)
            if rr >= 4 and fs is not None and board.piece_at(fs) is None and is_passed(sq, color):
                d = len(board.attackers(color, sq))
                a = len(board.attackers(enemy, sq))
                if d and d + (1 if rr >= 5 else 0) > a:
                    if rr > best:
                        best = rr
        return best

    md = mat(stm) - mat(opp)

    own_q = list(board.pieces(chess.QUEEN, stm))
    opp_q = len(board.pieces(chess.QUEEN, opp))
    if own_q and opp_q == 0 and md >= 0 and mat(stm, False) - mat(opp, False) <= -2:
        for q in own_q:
            mob = 0
            pressure = False
            for t in board.attacks(q):
                p = board.piece_at(t)
                if p is None or p.color == opp:
                    mob += 1
                if p is not None and p.color == opp and val(p.piece_type) >= 3:
                    pressure = True
                if chess.square_distance(t, ok) <= 1:
                    pressure = True
            if mob >= 8 and pressure:
                return True

    if md >= 0:
        own_best = dangerous_passed_best(stm)
        if own_best >= 4:
            opp_best = dangerous_passed_best(opp)
            if opp_best < 5 or own_best >= opp_best:
                return True

    if md >= -2:
        kf = chess.square_file(ok)
        kr = chess.square_rank(ok)
        zone = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f = kf + df
                r = kr + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    zone.append(chess.square(f, r))
        for sq in board.pieces(chess.PAWN, stm):
            if rel_rank(sq, stm) >= 5:
                near = chess.square_distance(sq, ok) <= 2
                for a in board.attacks(sq):
                    if chess.square_distance(a, ok) <= 1:
                        near = True
                if near:
                    hits = 0
                    for z in zone:
                        if len(board.attackers(stm, z)):
                            hits += 1
                    if hits >= 2:
                        return True

    return False

