    if -220 <= mat <= 220:
        for mv in board.legal_moves:
            pc = board.piece_at(mv.from_square)
            if not pc or pc.color != stm:
                continue
            cap = board.piece_at(mv.to_square)
            capv = vals.get(cap.piece_type, 0) if cap and cap.color == opp else 0
            if board.is_en_passant(mv):
                capv = 100
            gives = board.gives_check(mv)
            if capv >= 500:
                attv = vals.get(pc.piece_type, 0)
                pre_a = len(board.attackers(stm, mv.to_square))
                pre_d = len(board.attackers(opp, mv.to_square))
                b = board.copy(stack=False)
                b.push(mv)
                oa = len(b.attackers(opp, mv.to_square))
                od = len(b.attackers(stm, mv.to_square))
                safe = oa == 0 or od >= oa or capv >= attv + 350
                if safe and (pre_a >= pre_d or gives or (capv == 900 and attv <= 500)):
