MOTIF_NAME = 'long-range compensation without material edge'
MOTIF_DESCRIPTION = 'The side to move is not up material but has active long-range compensation from bishops, rook lifts, or queen pressure on a central king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False

    vals = {
        chess.PAWN: 1,
        chess.KNIGHT: 3,
        chess.BISHOP: 3,
        chess.ROOK: 5,
        chess.QUEEN: 9,
    }

    def mat(c):
        return sum(vals[p] * len(board.pieces(p, c)) for p in vals)

    bal = mat(stm) - mat(opp)
    if bal > 0 or bal < -2:
        return False

    ksq = board.king(opp)
    oksq = board.king(stm)
    if ksq is None or oksq is None:
        return False

    def rel_rank(sq):
        r = chess.square_rank(sq)
        return r if stm == chess.WHITE else 7 - r

    def home_central(c, sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        h = 0 if c == chess.WHITE else 7
        return 2 <= f <= 5 and abs(r - h) <= 2

    def zone(sq):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        out = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    out.append(chess.square(nf, nr))
        return out

    def bishop_pair_activity():
        if bal < -1:
            return False
        bishops = list(board.pieces(chess.BISHOP, stm))
        if len(bishops) < 2 or len(board.pieces(chess.BISHOP, opp)) >= 2:
            return False
        centers = {
            chess.D4, chess.E4, chess.D5, chess.E5,
            chess.C4, chess.F4, chess.C5, chess.F5
        }
        target = 0
        mob = 0
        cen = 0
        dev = 0
        seen = set()
        for b in bishops:
            if rel_rank(b) >= 2:
                dev += 1
            for sq in board.attacks(b):
                if sq in centers:
                    cen += 1
                p = board.piece_at(sq)
                if p is None:
                    mob += 1
                elif p.color == opp and sq not in seen:
                    seen.add(sq)
                    if p.piece_type == chess.PAWN:
                        target += 1
                    elif p.piece_type in (chess.KNIGHT, chess.BISHOP):
                        target += 2
                    elif p.piece_type == chess.ROOK:
                        target += 3
                    elif p.piece_type == chess.QUEEN:
                        target += 4
        return target >= 4 or (dev >= 2 and mob >= 8 and target >= 2) or (mob >= 11 and cen >= 2 and dev >= 1)

    def central_queen_pressure():
        if not board.pieces(chess.QUEEN, stm):
            return False
        if not home_central(opp, ksq) or home_central(stm, oksq):
            return False
        z = set(zone(ksq))
        contributors = set()
        queen_in = False
        for sq in z:
            for a in board.attackers(stm, sq):
                p = board.piece_at(a)
                if p and p.color == stm and p.piece_type not in (chess.PAWN, chess.KING):
                    contributors.add(a)
                    if p.piece_type == chess.QUEEN:
                        queen_in = True
        for sq, p in board.piece_map().items():
            if p.color == opp and p.piece_type != chess.KING and chess.square_distance(sq, ksq) <= 2:
                for a in board.attackers(stm, sq):
                    ap = board.piece_at(a)
                    if ap and ap.color == stm and ap.piece_type not in (chess.PAWN, chess.KING):
                        contributors.add(a)
                        if ap.piece_type == chess.QUEEN:
                            queen_in = True
        return queen_in and len(contributors) >= 2

    def rook_lift():
        rooks = list(board.pieces(chess.ROOK, stm))
        adv = []
        total_targets = 0
        safe_any = False
        connected_any = False
        hits_king_zone = False
        z = set(zone(ksq))
        for r in rooks:
            rr = rel_rank(r)
            if rr not in (4, 5):
                continue
            adv.append(r)
            defenders = 0
            for a in board.attackers(stm, r):
                p = board.piece_at(a)
                if p and p.piece_type != chess.KING:
                    defenders += 1
                    if p.piece_type in (chess.ROOK, chess.QUEEN):
                        connected_any = True
            attackers = 0
            for a in board.attackers(opp, r):
                p = board.piece_at(a)
                if p and p.piece_type != chess.KING:
                    attackers += 1
            if attackers == 0 or defenders >= attackers:
                safe_any = True
            for sq in board.attacks(r):
                if sq in z:
                    hits_king_zone = True
                p = board.piece_at(sq)
                if p and p.color == opp and p.piece_type != chess.KING:
                    total_targets += 1 if p.piece_type == chess.PAWN else 2
        if len(adv) >= 2 and safe_any and total_targets >= 2:
            return True
        if adv and safe_any and connected_any and (total_targets >= 2 or hits_king_zone):
            return True
        if any(rel_rank(r) == 5 for r in adv) and safe_any and total_targets >= 3:
            return True
        return False

    return bishop_pair_activity() or central_queen_pressure() or rook_lift()

import chess

MOTIF_NAME = 'loose-piece gain or central pawn bind'
MOTIF_DESCRIPTION = 'The side to move is not materially lost and has a concrete target through a profitable capture, a trapped corner knight, or a central pawn clamp against an uncastled king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = (0, 1, 3, 3, 5, 9, 100)

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def material():
        s = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            s += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        return s

    mat = material()

    def profitable_capture():
        if mat < -2 or mat > 3:
            return False
        for mv in list(board.legal_moves):
            if not board.is_capture(mv):
                continue
            p = board.piece_at(mv.from_square)
            if not p or p.color != stm or p.piece_type == chess.KING:
                continue
            if board.is_en_passant(mv):
                victim_val = 1
            else:
                v = board.piece_at(mv.to_square)
                if not v or v.color != opp or v.piece_type == chess.KING:
                    continue
                victim_val = vals[v.piece_type]
            if victim_val <= 1 and not mv.promotion:
                continue
            mover_val = vals[p.piece_type]
            after_val = vals[mv.promotion] if mv.promotion else mover_val
            promo_gain = max(0, after_val - mover_val)
            raw_gain = victim_val + promo_gain
            if raw_gain < 3 and not (victim_val >= 5 and mover_val <= 3):
                continue
            board.push(mv)
            defenders = 0
            for a in board.attackers(stm, mv.to_square):
                ap = board.piece_at(a)
                if ap and ap.piece_type != chess.KING:
                    defenders += 1
            attackers = 0
            king_attacks = False
            for a in board.attackers(opp, mv.to_square):
                ap = board.piece_at(a)
                if ap:
                    if ap.piece_type == chess.KING:
                        king_attacks = True
                    else:
                        attackers += 1
            if king_attacks and defenders == 0:
                attackers += 1
            board.pop()
            if raw_gain - after_val >= 2:
                return True
            if attackers == 0 and (victim_val >= 5 or (raw_gain >= 3 and mover_val <= raw_gain)):
                return True
            if victim_val >= 5 and mover_val <= 3 and defenders >= attackers:
                return True
        return False

    def trapped_corner_knight():
        if mat < -2 or mat > 2:
            return False
        k = board.king(stm)
        for sq in board.pieces(chess.KNIGHT, opp):
            if sq not in (chess.A1, chess.H1, chess.A8, chess.H8):
                continue
            escapes = 0
            for t in board.attacks(sq):
                pc = board.piece_at(t)
                if pc and pc.color == opp:
                    continue
                stmhits = len(board.attackers(stm, t))
                opphits = len(board.attackers(opp, t))
                if stmhits == 0 or opphits > stmhits + 1:
                    escapes += 1
            if escapes == 0 or (escapes <= 1 and k is not None and chess.square_distance(k, sq) <= 3):
                return True
        return False

    def central_clamp():
        if mat < -2 or mat > 0:
            return False
        if len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK)) == 0:
            return False
        ek = board.king(opp)
        ok = board.king(stm)
        if ek is None or ok is None:
            return False
        if rel(ek, opp) > 1 or chess.square_file(ek) not in (3, 4):
            return False
        if rel(ok, stm) <= 1 and chess.square_file(ok) in (3, 4):
            return False
        cps = []
        defended = 0
        centerfiles = 0
        for sq in board.pieces(chess.PAWN, stm):
            f = chess.square_file(sq)
            rr = rel(sq, stm)
            if f in (2, 3, 4, 5) and 3 <= rr <= 5:
                cps.append(sq)
                if f in (3, 4):
                    centerfiles += 1
                if len(board.attackers(stm, sq)) > 0:
                    defended += 1
        if len(cps) < 2 or centerfiles == 0:
            return False
        front = 0
        for sq in board.pieces(chess.PAWN, opp):
            if chess.square_file(sq) in (3, 4) and rel(sq, opp) <= 2:
                front += 1
        if len(cps) >= 3 and defended >= 1 and front <= 1:
            return True
        units = 0
        zone = set()
        ef = chess.square_file(ek)
        er = chess.square_rank(ek)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = ef + df, er + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    zone.add(chess.square(nf, nr))
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, stm):
                for t in board.attacks(sq):
                    if t in zone:
                        units += 1
                        break
        return len(cps) >= 2 and centerfiles >= 2 and defended >= 2 and front == 0 and units >= 1

    return profitable_capture() or trapped_corner_knight() or central_clamp()

import chess

MOTIF_NAME = 'overextended pawn cleanup and backed spear'
MOTIF_DESCRIPTION = 'Without a material surplus, the side to move has a safe cleanup of an overextended pawn or a heavily backed pawn/rook squeeze.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = (0, 100, 320, 330, 500, 900, 0)

    def val(pt):
        return vals[pt]

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def fsq(sq):
        return chess.square_file(sq)

    def from_rel(f, rr, color):
        return chess.square(f, rr if color == chess.WHITE else 7 - rr)

    def material():
        s = 0
        for _, p in board.piece_map().items():
            x = val(p.piece_type)
            s += x if p.color == stm else -x
        return s

    mat = material()

    def aw(pt):
        if pt == chess.QUEEN:
            return 4
        if pt == chess.ROOK:
            return 3
        if pt in (chess.BISHOP, chess.KNIGHT):
            return 2
        if pt == chess.PAWN:
            return 1
        return 0

    def zone_squares(k, dist):
        out = []
        f0 = fsq(k)
        r0 = chess.square_rank(k)
        for df in range(-dist, dist + 1):
            for dr in range(-dist, dist + 1):
                nf = f0 + df
                nr = r0 + dr
                if 0 <= nf < 8 and 0 <= nr < 8 and max(abs(df), abs(dr)) <= dist:
                    out.append(chess.square(nf, nr))
        return out

    def zone_pressure(att, defe):
        k = board.king(defe)
        if k is None:
            return 0
        s = 0
        for z in zone_squares(k, 2):
            for a in board.attackers(att, z):
                p = board.piece_at(a)
                if p and p.color == att and p.piece_type != chess.KING:
                    s += aw(p.piece_type)
        return s

    def king_penalty(color):
        k = board.king(color)
        if k is None:
            return 30
        enemy = not color
        f = fsq(k)
        rr = rel(k, color)
        pen = 0
        if board.attackers(enemy, k):
            pen += 2
        if rr >= 2:
            pen += 4 + rr
        elif f in (3, 4):
            pen += 2
        step = 1 if color == chess.WHITE else -1
        kr = chess.square_rank(k)
        if f <= 2 or f >= 5:
            for nf in range(max(0, f - 1), min(7, f + 1) + 1):
                has = False
                for d in (1, 2):
                    nr = kr + step * d
                    if 0 <= nr < 8:
                        p = board.piece_at(chess.square(nf, nr))
                        if p and p.color == color and p.piece_type == chess.PAWN:
                            has = True
                            break
                if not has:
                    pen += 1
        for ep in board.pieces(chess.PAWN, enemy):
            if abs(fsq(ep) - f) <= 1:
                d = rel(ep, color) - rr
                if 1 <= d <= 4:
                    pen += 1
                    if d <= 2:
                        pen += 1
        atk = 0
        dfn = 0
        for z in zone_squares(k, 1):
            for a in board.attackers(enemy, z):
                p = board.piece_at(a)
                if p and p.color == enemy and p.piece_type != chess.KING:
                    atk += aw(p.piece_type)
            for a in board.attackers(color, z):
                p = board.piece_at(a)
                if p and p.color == color and p.piece_type != chess.KING:
                    dfn += aw(p.piece_type)
        pen += max(0, atk - dfn // 2) // 4
        return pen

    own_pen = king_penalty(stm)
    opp_pen = king_penalty(opp)

    def defenders(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.color == color and p.piece_type != chess.KING:
                n += 1
        return n

    def pawn_attackers(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.color == color and p.piece_type == chess.PAWN:
                n += 1
        return n

    def safe_after(m):
        nb = board.copy(stack=False)
        nb.push(m)
        p = nb.piece_at(m.to_square)
        if not p or p.color != stm or p.piece_type == chess.KING:
            return False
        enemy_at = []
        for a in nb.attackers(opp, m.to_square):
            ap = nb.piece_at(a)
            if ap and ap.color == opp and ap.piece_type != chess.KING:
                enemy_at.append(ap)
        if not enemy_at:
            return True
        if p.piece_type == chess.QUEEN:
            return False
        if p.piece_type != chess.PAWN:
            for ap in enemy_at:
                if ap.piece_type == chess.PAWN:
                    return False
        own_def = 0
        for a in nb.attackers(stm, m.to_square):
            ap = nb.piece_at(a)
            if ap and ap.color == stm and ap.piece_type != chess.KING:
                own_def += 1
        return own_def >= len(enemy_at)

    def safe_piece_gain():
        if mat > 80 or mat < -500 or own_pen > opp_pen + 5:
            return False
        for m in board.legal_moves:
            if not board.is_capture(m):
                continue
            pc = board.piece_at(m.from_square)
            tg = board.piece_at(m.to_square)
            if not pc or not tg or pc.color != stm or tg.color != opp:
                continue
            if tg.piece_type in (chess.PAWN, chess.KING) or pc.piece_type == chess.QUEEN:
                continue
            if val(tg.piece_type) - val(pc.piece_type) >= 150 and safe_after(m):
                return True
        return False

    def overextended_pawn_pickup():
        if mat > 100 or mat < -380 or own_pen > opp_pen + 5:
            return False
        for m in board.legal_moves:
            if not board.is_capture(m):
                continue
            pc = board.piece_at(m.from_square)
            tg = board.piece_at(m.to_square)
            if not pc or not tg or pc.color != stm or tg.color != opp:
                continue
            if tg.piece_type != chess.PAWN or pc.piece_type not in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                continue
            rr = rel(m.to_square, stm)
            f = fsq(m.to_square)
            if rel(m.to_square, opp) < 3:
                continue
            if f not in (2, 3, 4, 5) and rr > 2:
                continue
            hook = rr <= 2
            if not hook:
                for z in board.attacks(m.to_square):
                    zp = board.piece_at(z)
                    if zp and zp.color == stm and zp.piece_type != chess.KING:
                        hook = True
                        break
            if not hook:
                continue
            if pc.piece_type != chess.PAWN and pawn_attackers(opp, m.to_square):
                continue
            if safe_after(m):
                return True
        return False

    def major_backers(psq):
        pf = fsq(psq)
        pr = rel(psq, stm)
        n = 0
        for q in board.pieces(chess.QUEEN, stm):
            if abs(fsq(q) - pf) <= 1 and rel(q, stm) < pr:
                n += 2
        for r in board.pieces(chess.ROOK, stm):
            if abs(fsq(r) - pf) <= 1 and rel(r, stm) < pr:
                n += 1
        for b in board.pieces(chess.BISHOP, stm):
            if abs(fsq(b) - pf) <= 2 and rel(b, stm) < pr:
                n += 1
        return n

    def backed_spear_or_phalanx():
        if mat > 120 or mat < -360 or own_pen > opp_pen + 3 or own_pen > 16:
            return False
        ek = board.king(opp)
        if ek is None:
            return False
        ef = fsq(ek)
        enemy_home = rel(ek, opp) <= 1
        pawns = list(board.pieces(chess.PAWN, stm))

        for p in pawns:
            pr = rel(p, stm)
            if pr >= 4 and abs(fsq(p) - ef) <= 1 and defenders(stm, p) >= 1:
                if pawn_attackers(opp, p) <= defenders(stm, p) and major_backers(p) >= 2 and enemy_home:
                    return True

        zp = zone_pressure(stm, opp)
        oz = zone_pressure(opp, stm)
        if zp < oz + 1 and opp_pen < own_pen + 2:
            return False
        for i in range(len(pawns)):
            p1 = pawns[i]
            f1 = fsq(p1)
            r1 = rel(p1, stm)
            if f1 not in (2, 3, 4, 5) or r1 < 3:
                continue
            for j in range(i + 1, len(pawns)):
                p2 = pawns[j]
                f2 = fsq(p2)
                r2 = rel(p2, stm)
                if f2 not in (2, 3, 4, 5) or abs(f1 - f2) != 1:
                    continue
                if r2 < 3 or max(r1, r2) < 4:
                    continue
                d = defenders(stm, p1) + defenders(stm, p2)
                if d < 2 or pawn_attackers(opp, p1) + pawn_attackers(opp, p2) > d:
                    continue
                if major_backers(p1) + major_backers(p2) >= 3:
                    return True
        return False

    def twin_rook_center_squeeze():
        if mat > 180 or mat < -240 or own_pen > opp_pen + 4:
            return False
        if board.pieces(chess.QUEEN, stm) or board.pieces(chess.QUEEN, opp):
            return False
        rooks = list(board.pieces(chess.ROOK, stm))
        if len(rooks) < 2:
            return False
        ek = board.king(opp)
        if ek is None or rel(ek, opp) > 1:
            return False
        for p in board.pieces(chess.PAWN, stm):
            f = fsq(p)
            pr = rel(p, stm)
            if f not in (2, 3, 4, 5) or pr < 4 or abs(fsq(ek) - f) > 3:
                continue
            if defenders(stm, p) == 0 or pawn_attackers(opp, p) > defenders(stm, p):
                continue
            blocked = False
            for rr in range(pr + 1, 8):
                q = board.piece_at(from_rel(f, rr, stm))
                if q and q.piece_type == chess.PAWN:
                    blocked = True
                    break
            if blocked:
                continue
            score = 0
            for r in rooks:
                if rel(r, stm) <= 3 and abs(fsq(r) - f) <= 2:
                    score += 1
                if rel(r, stm) >= 5:
                    score += 1
            if score >= 2:
                return True
        return False

    return safe_piece_gain() or overextended_pawn_pickup() or backed_spear_or_phalanx() or twin_rook_center_squeeze()

import chess

MOTIF_NAME = 'balanced space phalanx and king-defender hit'
MOTIF_DESCRIPTION = 'With material not already decisive, the side to move has a defended space-development clamp or a safe minor/diagonal hit on a key defender near the enemy king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm
    vals = (0, 1, 3, 3, 5, 9)

    def mat(c):
        return sum(vals[pt] * len(board.pieces(pt, c)) for pt in range(1, 6))

    m = mat(stm) - mat(opp)
    if m < -2 or m > 1:
        return False

    sk = board.king(stm)
    ek = board.king(opp)
    if sk is None or ek is None:
        return False

    def rel(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def zone(k):
        f, r = chess.square_file(k), chess.square_rank(k)
        out = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    out.append(chess.square(nf, nr))
        return out

    def king_hits(c):
        k = board.king(c)
        if k is None:
            return 9
        a = not c
        return sum(1 for s in zone(k) if len(board.attackers(a, s)))

    def safe_ready(c):
        k = board.king(c)
        if k is None:
            return False
        f = chess.square_file(k)
        h = king_hits(c)
        if (f <= 2 or f >= 5) and rel(k, c) <= 1 and h <= 4:
            return True
        if (board.has_kingside_castling_rights(c) or board.has_queenside_castling_rights(c)) and h <= 2:
            return True
        return False

    def central_king(c):
        k = board.king(c)
        if k is None:
            return False
        return 2 <= chess.square_file(k) <= 5 and rel(k, c) <= 1

    def developed_minors(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                r, f = rel(s, c), chess.square_file(s)
                if r >= 2 or (pt == chess.BISHOP and r == 1 and f in (1, 6)):
                    n += 1
        return n

    def passive_minors(c):
        n = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                r, f = rel(s, c), chess.square_file(s)
                mob = 0
                for t in board.attacks(s):
                    p = board.piece_at(t)
                    if p is None or p.color != c:
                        mob += 1
                if r == 0 or (r == 1 and not (pt == chess.BISHOP and f in (1, 6)) and mob <= 4):
                    n += 1
        return n

    def defended(s, c):
        return len(board.attackers(c, s)) > 0

    def nonking_attackers(c, s):
        n = 0
        for a in board.attackers(c, s):
            p = board.piece_at(a)
            if p and p.piece_type != chess.KING:
                n += 1
        return n

    def pawn_attacked(c, s):
        for a in board.attackers(c, s):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    def space_clamp():
        if not (-1 <= m <= 1) or not safe_ready(stm):
            return False
        own = [p for p in board.pieces(chess.PAWN, stm) if 2 <= chess.square_file(p) <= 5 and rel(p, stm) >= 3]
        enemy = [p for p in board.pieces(chess.PAWN, opp) if 2 <= chess.square_file(p) <= 5 and rel(p, opp) >= 3]
        if len(own) < 2 or len(own) < len(enemy) + 2:
            return False
        if developed_minors(stm) < 3 or sum(1 for p in own if defended(p, stm)) < 2:
            return False
        if not (passive_minors(opp) >= 2 or central_king(opp) or developed_minors(stm) >= developed_minors(opp) + 2):
            return False
        for i, p in enumerate(own):
            for q in own[i + 1:]:
                if chess.square_file(p) != chess.square_file(q) and abs(chess.square_file(p) - chess.square_file(q)) <= 2:
                    if defended(p, stm) and defended(q, stm):
                        return True
        return False

    def knight_hook():
        if not (safe_ready(stm) or central_king(opp)):
            return False
        for n in board.pieces(chess.KNIGHT, stm):
            if rel(n, stm) < 4 or pawn_attacked(opp, n):
                continue
            own = nonking_attackers(stm, n)
            enemy = nonking_attackers(opp, n)
            if enemy > own + 1:
                continue
            for t in board.attacks(n):
                p = board.piece_at(t)
                if not p or p.color != opp or p.piece_type not in (chess.BISHOP, chess.ROOK, chess.QUEEN):
                    continue
                near = chess.square_distance(t, ek) <= 2 or rel(t, opp) <= 1
                loose = nonking_attackers(stm, t) > nonking_attackers(opp, t)
                if p.piece_type == chess.BISHOP and near:
                    return True
                if p.piece_type in (chess.ROOK, chess.QUEEN) and (near or loose):
                    return True
        return False

    def bishop_bites_defender():
        if m < -1 or not safe_ready(stm):
            return False
        if not ((chess.square_file(ek) <= 2 or chess.square_file(ek) >= 5) and rel(ek, opp) <= 1):
            return False
        kz = set(zone(ek))
        for b in board.pieces(chess.BISHOP, stm):
            if rel(b, stm) < 2:
                continue
            own = nonking_attackers(stm, b)
            enemy = nonking_attackers(opp, b)
            if pawn_attacked(opp, b) and own <= enemy:
                continue
            if enemy > own + 2:
                continue
            for t in board.attacks(b):
                if t not in kz:
                    continue
                p = board.piece_at(t)
                if p and p.color == opp and p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                    if nonking_attackers(stm, t) + 1 >= nonking_attackers(opp, t) or p.piece_type in (chess.KNIGHT, chess.BISHOP):
                        return True
        return False

    return space_clamp() or knight_hook() or bishop_bites_defender()

import chess

MOTIF_NAME = 'parity x-ray pawn target and passer pickup'
MOTIF_DESCRIPTION = 'With no material surplus and a safe king, the side to move can safely remove an overextended enemy pawn or x-ray a deep weak pawn to a major piece or king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    mat = 0
    for pc in board.piece_map().values():
        v = vals.get(pc.piece_type, 0)
        mat += v if pc.color == stm else -v
    if mat < -1 or mat > 0:
        return False

    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None:
        return False

    def rr(sq):
        r = chess.square_rank(sq)
        return r if stm == chess.WHITE else 7 - r

    if board.is_check():
        return False
    kf = chess.square_file(mk)
    if kf in (3, 4):
        return False
    if rr(mk) > 1 and kf not in (0, 1, 6, 7):
        return False

    def pawn_atkers(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                n += 1
        return n

    for mv in board.legal_moves:
        if not board.is_capture(mv):
            continue
        p = board.piece_at(mv.from_square)
        cap = board.piece_at(mv.to_square)
        if not p or not cap:
            continue
        if p.color == stm and p.piece_type == chess.PAWN and cap.color == opp and cap.piece_type == chess.PAWN:
            if rr(mv.to_square) <= 2:
                a = len(board.attackers(stm, mv.to_square))
                d = len(board.attackers(opp, mv.to_square))
                if d <= a and pawn_atkers(opp, mv.to_square) == 0:
                    return True

    if mat != 0:
        return False

    orth = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    diag = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

    for sq, pc in board.piece_map().items():
        if pc.color != stm or pc.piece_type not in (chess.ROOK, chess.BISHOP, chess.QUEEN):
            continue
        dirs = []
        if pc.piece_type in (chess.ROOK, chess.QUEEN):
            dirs += orth
        if pc.piece_type in (chess.BISHOP, chess.QUEEN):
            dirs += diag
        sf = chess.square_file(sq)
        sr = chess.square_rank(sq)
        for df, dr in dirs:
            f = sf + df
            r = sr + dr
            while 0 <= f < 8 and 0 <= r < 8:
                t = chess.square(f, r)
                tp = board.piece_at(t)
                if not tp:
                    f += df
                    r += dr
                    continue
                if tp.color == stm or tp.piece_type != chess.PAWN:
                    break
                if rr(t) < 5 and chess.square_distance(t, ek) > 2:
                    break

                bf = f + df
                br = r + dr
                good_back = False
                while 0 <= bf < 8 and 0 <= br < 8:
                    bq = chess.square(bf, br)
                    bp = board.piece_at(bq)
                    if bp:
                        if bp.color == opp and bp.piece_type in (chess.ROOK, chess.QUEEN, chess.KING):
                            good_back = True
                        break
                    bf += df
                    br += dr

                if good_back:
                    a = len(board.attackers(stm, t))
                    d = len(board.attackers(opp, t))
                    if pawn_atkers(opp, t) == 0 and (a >= d or (pc.piece_type in (chess.ROOK, chess.QUEEN) and a + 1 >= d)):
                        if pawn_atkers(opp, sq) == 0 or len(board.attackers(stm, sq)) >= len(board.attackers(opp, sq)):
                            return True
                break
    return False

import chess

MOTIF_NAME = 'rook-backed pawn center and knight-pair shelter edge'
MOTIF_DESCRIPTION = 'With material close, the side to move has the safer king plus either a rook-backed connected center, a hard knight outpost, or knight-pair pressure against a knightless weak shelter.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 325, chess.ROOK: 500, chess.QUEEN: 900}

    def rel(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def material():
        sc = 0
        for pt, v in vals.items():
            sc += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        if len(board.pieces(chess.BISHOP, stm)) >= 2:
            sc += 35
        if len(board.pieces(chess.BISHOP, opp)) >= 2:
            sc -= 35
        return sc

    ms = material()

    def shelter(c):
        k = board.king(c)
        if k is None:
            return 0
        f = chess.square_file(k)
        cnt = 0
        for p in board.pieces(chess.PAWN, c):
            if abs(chess.square_file(p) - f) <= 1 and 1 <= rel(p, c) <= 2:
                cnt += 1
        return cnt

    own_sh = shelter(stm)
    opp_sh = shelter(opp)

    def flank_safe(c):
        k = board.king(c)
        if k is None:
            return False
        f = chess.square_file(k)
        r = rel(k, c)
        if r > 2 or 3 <= f <= 4 or shelter(c) < 1:
            return False
        for q in board.pieces(chess.QUEEN, not c):
            if chess.square_distance(q, k) <= 2:
                return False
        danger = 0
        kr = chess.square_rank(k)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf = f + df
                nr = kr + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    danger += len(board.attackers(not c, chess.square(nf, nr)))
        return danger <= 8

    def opp_vulnerable(limit):
        k = board.king(opp)
        if k is None:
            return False
        f = chess.square_file(k)
        r = rel(k, opp)
        if 3 <= f <= 4 and r <= 2:
            return True
        if r >= 2:
            return True
        return opp_sh <= limit

    def king_balance(limit):
        if not flank_safe(stm) or own_sh < 2 or not opp_vulnerable(limit):
            return False
        k = board.king(opp)
        f = chess.square_file(k)
        r = rel(k, opp)
        if not ((3 <= f <= 4 and r <= 2) or r >= 2) and own_sh <= opp_sh:
            return False
        return True

    def clear_major_behind(p):
        f = chess.square_file(p)
        pr = rel(p, stm)
        pieces = list(board.pieces(chess.ROOK, stm)) + list(board.pieces(chess.QUEEN, stm))
        for s in pieces:
            if chess.square_file(s) != f:
                continue
            sr = rel(s, stm)
            if sr >= pr:
                continue
            clear = True
            for x in range(sr + 1, pr):
                ar = x if stm == chess.WHITE else 7 - x
                if board.piece_at(chess.square(f, ar)) is not None:
                    clear = False
                    break
            if clear:
                return True
        return False

    def can_push(p):
        r = chess.square_rank(p) + (1 if stm == chess.WHITE else -1)
        if r < 0 or r > 7:
            return False
        return board.piece_at(chess.square(chess.square_file(p), r)) is None

    def central_mass():
        if ms < -100 or ms > 150 or not king_balance(2):
            return False
        pawns = list(board.pieces(chess.PAWN, stm))
        for i in range(len(pawns)):
            a = pawns[i]
            fa = chess.square_file(a)
            ra = rel(a, stm)
            if not (2 <= fa <= 5 and ra >= 3):
                continue
            for b in pawns[i + 1:]:
                fb = chess.square_file(b)
                rb = rel(b, stm)
                if abs(fa - fb) != 1 or not (2 <= fb <= 5) or rb < 3:
                    continue
                if fa not in (3, 4) and fb not in (3, 4):
                    continue
                if abs(ra - rb) > 1:
                    continue
                if not (clear_major_behind(a) or clear_major_behind(b)):
                    continue
                sup = len(board.attackers(stm, a)) + len(board.attackers(stm, b))
                if sup < 2:
                    continue
                if len(board.attackers(opp, a)) + len(board.attackers(opp, b)) > sup + 1:
                    continue
                if can_push(a) or can_push(b) or max(ra, rb) >= 5:
                    return True
        return False

    def knight_pair_shelter():
        if ms < -140 or ms > 165 or not king_balance(1):
            return False
        if len(board.pieces(chess.KNIGHT, stm)) < 2 or len(board.pieces(chess.KNIGHT, opp)) != 0:
            return False
        if len(board.pieces(chess.QUEEN, stm)) == 0:
            return False
        targets = 0
        for p in board.pieces(chess.PAWN, opp):
            if rel(p, stm) >= 4 and len(board.attackers(stm, p)) > 0:
                targets += 1
        if targets >= 2:
            return True
        ok = board.king(opp)
        for n in board.pieces(chess.KNIGHT, stm):
            if rel(n, stm) >= 3 and chess.square_distance(n, ok) <= 4:
                return True
        return False

    def outpost_hit():
        if ms < -90 or ms > 145 or not king_balance(2):
            return False
        ok = board.king(opp)
        for n in board.pieces(chess.KNIGHT, stm):
            f = chess.square_file(n)
            if not (2 <= f <= 5 and rel(n, stm) >= 4):
                continue
            defs = board.attackers(stm, n)
            if len(defs) == 0:
                continue
            special_def = len(defs) >= 2
            for d in defs:
                pc = board.piece_at(d)
                if pc and pc.piece_type in (chess.PAWN, chess.QUEEN):
                    special_def = True
            if not special_def:
                continue
            chased = False
            for p in board.pieces(chess.PAWN, opp):
                if n in board.attacks(p):
                    chased = True
                    break
            if chased:
                continue
            hit = 0
            for t in board.attacks(n):
                pc = board.piece_at(t)
                if pc and pc.color == opp:
                    if pc.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                        hit += 2
                    elif pc.piece_type == chess.PAWN and rel(t, stm) >= 5:
                        hit += 1
                if ok is not None and chess.square_distance(t, ok) <= 1:
                    hit += 1
            if hit >= 2:
                return True
        return False

    return central_mass() or knight_pair_shelter() or outpost_hit()

import chess

MOTIF_NAME = 'exchange clamp and backed outpost pressure'
MOTIF_DESCRIPTION = 'With material not already decisive, the side to move has a safe exchange clamp, pawn-backed outpost, or coordinated queen pressure against restricted enemy pieces.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    V = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def rsq(f, r, c):
        if 0 <= f < 8 and 0 <= r < 8:
            return chess.square(f, r if c == chess.WHITE else 7 - r)
        return None

    def material(c):
        return sum(V[pt] * len(board.pieces(pt, c)) for pt in V)

    bal = material(stm) - material(opp)

    def zone(k, rad):
        kf, kr = chess.square_file(k), chess.square_rank(k)
        z = set()
        for f in range(max(0, kf - rad), min(8, kf + rad + 1)):
            for r in range(max(0, kr - rad), min(8, kr + rad + 1)):
                s = chess.square(f, r)
                if chess.square_distance(k, s) <= rad:
                    z.add(s)
        return z

    def pressure_on(c):
        k = board.king(c)
        if k is None:
            return 9
        a = set()
        for s in zone(k, 1):
            a |= set(board.attackers(not c, s))
        return len(a)

    def shield(c):
        k = board.king(c)
        if k is None:
            return 0
        kf = chess.square_file(k)
        return sum(1 for p in board.pieces(chess.PAWN, c)
                   if abs(chess.square_file(p) - kf) <= 1 and 1 <= rel(p, c) <= 2)

    def safe_enough():
        k = board.king(stm)
        if k is None:
            return False
        p = pressure_on(stm)
        if p > 6:
            return False
        queens = len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK))
        if queens:
            if chess.square_file(k) in (0, 1, 6, 7):
                return shield(stm) >= 2 or p <= 3
            return p <= 4 or shield(stm) >= 1
        return True

    def attacked_by_pawn(c, sq):
        for a in board.attackers(c, sq):
            pc = board.piece_at(a)
            if pc and pc.piece_type == chess.PAWN:
                return True
        return False

    def nonking_back(c):
        n = 0
        for pt in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
            for s in board.pieces(pt, c):
                if rel(s, c) <= 1:
                    n += 1
        return n

    def rook_mob(r, c):
        n = 0
        for t in board.attacks(r):
            pc = board.piece_at(t)
            if pc is None or pc.color != c:
                n += 1
        return n

    def no_own_pawn_ahead(r, c):
        f, rr = chess.square_file(r), rel(r, c)
        return not any(chess.square_file(p) == f and rel(p, c) > rr for p in board.pieces(chess.PAWN, c))

    def exchange_rook_clamp():
        if not (-1 <= bal <= 1.5) or not safe_enough():
            return False
        rooks = list(board.pieces(chess.ROOK, stm))
        if len(rooks) < 2 or len(board.pieces(chess.ROOK, opp)) > 1:
            return False
        ob, sb = nonking_back(opp), nonking_back(stm)
        congested = ob >= 4 and ob >= sb + 1
        far = False
        for p in board.pieces(chess.PAWN, stm):
            f, r = chess.square_file(p), rel(p, stm)
            if r >= 5 and (f <= 1 or f >= 6):
                if len(board.attackers(opp, p)) <= len(board.attackers(stm, p)) + 1:
                    far = True
                    break
        if far and congested:
            return True
        active = any((rel(r, stm) >= 1 or no_own_pawn_ahead(r, stm)) and rook_mob(r, stm) >= 6 for r in rooks)
        own_min = len(board.pieces(chess.KNIGHT, stm)) + len(board.pieces(chess.BISHOP, stm))
        opp_min = len(board.pieces(chess.KNIGHT, opp)) + len(board.pieces(chess.BISHOP, opp))
        return active and ob >= 3 and opp_min > own_min

    def pawn_outpost_for(c, n):
        oc = not c
        f, r = chess.square_file(n), rel(n, c)
        if f < 2 or f > 5 or r < 4 or r > 5:
            return False
        if not any(board.piece_at(a) and board.piece_at(a).piece_type == chess.PAWN for a in board.attackers(c, n)):
            return False
        if attacked_by_pawn(oc, n):
            return False
        if len(board.attackers(c, n)) < len(board.attackers(oc, n)):
            return False
        for p in board.pieces(chess.PAWN, oc):
            if abs(chess.square_file(p) - f) == 1 and rel(p, c) > r:
                return False
        return True

    def pawn_backed_outpost():
        if not (-2 <= bal <= 1.5) or pressure_on(stm) > 6:
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        opp_posts = sum(1 for n in board.pieces(chess.KNIGHT, opp) if pawn_outpost_for(opp, n))
        for n in board.pieces(chess.KNIGHT, stm):
            if not pawn_outpost_for(stm, n):
                continue
            major = any(chess.square_distance(m, n) <= 3 and rel(m, stm) >= 1
                        for pt in (chess.QUEEN, chess.ROOK) for m in board.pieces(pt, stm))
            target = 0
            key = 0
            for t in board.attacks(n):
                pc = board.piece_at(t)
                useful = pc is None or pc.color == opp
                if pc and pc.color == opp and pc.piece_type != chess.KING:
                    target += 1
                if useful and (rel(t, stm) >= 5 or chess.square_distance(t, ok) <= 2):
                    key += 1
            if opp_posts == 0 and major and target + key >= 3:
                return True
        return False

    def major_backed_wedge():
        if not (-2 <= bal <= 2) or pressure_on(stm) > 6:
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        kf = chess.square_file(ok)
        for p in board.pieces(chess.PAWN, stm):
            f, r = chess.square_file(p), rel(p, stm)
            if r < 5 or not (2 <= f <= 5 or abs(f - kf) <= 1):
                continue
            if attacked_by_pawn(opp, p):
                continue
            if len(board.attackers(stm, p)) + 1 < len(board.attackers(opp, p)):
                continue
            backed = False
            for rr in range(r - 1, -1, -1):
                s = rsq(f, rr, stm)
                pc = board.piece_at(s)
                if pc:
                    backed = pc.color == stm and pc.piece_type in (chess.QUEEN, chess.ROOK)
                    break
            if backed and (chess.square_distance(p, ok) <= 3 or abs(f - kf) <= 1 or rel(ok, opp) >= 1):
                return True
        return False

    def edge_rook_net():
        if not (-3 <= bal <= 2) or not safe_enough():
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        kf = chess.square_file(ok)
        if kf not in (0, 1, 6, 7):
            return False
        z = zone(ok, 2)
        for q in board.pieces(chess.QUEEN, stm):
            if rel(q, stm) < 2 or abs(chess.square_file(q) - kf) > 2:
                continue
            qa = board.attacks(q)
            qpawn = any(t in z and board.piece_at(t) and board.piece_at(t).color == opp
                        and board.piece_at(t).piece_type == chess.PAWN for t in qa)
            if not qpawn or len(board.attackers(opp, q)) > len(board.attackers(stm, q)) + 1:
                continue
            minor_ok = False
            for pt in (chess.KNIGHT, chess.BISHOP):
                for m in board.pieces(pt, stm):
                    if rel(m, stm) < 3 or abs(chess.square_file(m) - kf) > 2:
                        continue
                    if len(board.attackers(opp, m)) > len(board.attackers(stm, m)) + 1:
                        continue
                    for t in board.attacks(m):
                        pc = board.piece_at(t)
                        if t in z and pc and pc.color == opp and pc.piece_type != chess.KING:
                            minor_ok = True
                            break
                    if minor_ok:
                        break
                if minor_ok:
                    break
            if not minor_ok:
                continue
            for r in board.pieces(chess.ROOK, stm):
                if rel(r, stm) < 1 or abs(chess.square_file(r) - kf) > 3:
                    continue
                for t in board.attacks(r):
                    pc = board.piece_at(t)
                    if pc and pc.color == opp and pc.piece_type != chess.KING and chess.square_distance(t, ok) <= 3:
                        return True
        return False

    def deep_queen_drag():
        if not (-2 <= bal <= 2) or pressure_on(stm) > 6:
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        kf = chess.square_file(ok)
        if not (2 <= kf <= 5 or rel(ok, opp) >= 1 or shield(opp) <= 1):
            return False
        z = zone(ok, 2)
        for q in board.pieces(chess.QUEEN, stm):
            if rel(q, stm) < 5 or chess.square_distance(q, ok) > 3:
                continue
            if not board.attackers(stm, q) or len(board.attackers(opp, q)) > len(board.attackers(stm, q)) + 1:
                continue
            if sum(1 for s in z if s in board.attacks(q)) < 1:
                continue
            support = False
            for s in z:
                for a in board.attackers(stm, s):
                    if a == q:
                        continue
                    pc = board.piece_at(a)
                    if pc and pc.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
                        if len(board.attackers(opp, a)) <= len(board.attackers(stm, a)) + 1:
                            support = True
                            break
                if support:
                    break
            if support:
                return True
        return False

    def checking_fork_gain():
        if not (-3 <= bal <= 1.5) or pressure_on(stm) > 7:
            return False
        for mv in board.legal_moves:
            pc = board.piece_at(mv.from_square)
            if pc is None or pc.color != stm or pc.piece_type == chess.KING:
                continue
            if pc.piece_type == chess.QUEEN and not board.is_capture(mv):
                continue
            if not board.gives_check(mv):
                continue
            b = board.copy(stack=False)
            b.push(mv)
            moved = b.piece_at(mv.to_square)
            if moved is None:
                continue
            gain = 0
            cap = board.piece_at(mv.to_square)
            if cap and cap.color == opp:
                gain = max(gain, V[cap.piece_type])
            if board.is_en_passant(mv):
                gain = max(gain, 1)
            for t in b.attacks(mv.to_square):
                tp = b.piece_at(t)
                if tp and tp.color == opp and tp.piece_type in (chess.QUEEN, chess.ROOK):
                    gain = max(gain, V[tp.piece_type])
            if gain >= V.get(pc.piece_type, 0) + 2 or (pc.piece_type == chess.KNIGHT and gain >= 5):
                if len(b.attackers(opp, mv.to_square)) <= len(b.attackers(stm, mv.to_square)) + 1:
                    return True
        return False

    return (exchange_rook_clamp() or pawn_backed_outpost() or major_backed_wedge()
            or edge_rook_net() or deep_queen_drag() or checking_fork_gain())

import chess

MOTIF_NAME = 'tempo net on queen or invader'
MOTIF_DESCRIPTION = 'With material close, the side to move has a safe developing queen tempo, a queen sortie into a weakened shelter, or a pawn net around an overadvanced minor.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False

    V = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0}
    mat = 0
    for p in board.piece_map().values():
        if p.color == stm:
            mat += V[p.piece_type]
        else:
            mat -= V[p.piece_type]
    if mat < -180 or mat > 180:
        return False

    def rr(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def alen(b, c, sq):
        return len(b.attackers(c, sq))

    def pawn_att(b, c, sq):
        for a in b.attackers(c, sq):
            p = b.piece_at(a)
            if p and p.color == c and p.piece_type == chess.PAWN:
                return True
        return False

    def safe_lesser(b, sq, pt):
        ao = alen(b, opp, sq)
        ds = alen(b, stm, sq)
        if pt != chess.PAWN and ao and ds == 0:
            return False
        if pt != chess.PAWN and pawn_att(b, opp, sq):
            return False
        return ao <= ds + (2 if pt == chess.PAWN else 1)

    def safe_queen(b, sq):
        if pawn_att(b, opp, sq):
            return False
        return alen(b, opp, sq) <= alen(b, stm, sq)

    def queen_exposed(qsq):
        qf = chess.square_file(qsq)
        qr = rr(qsq, opp)
        if qr >= 3:
            return True
        if qr >= 2 and (qf <= 1 or qf >= 6 or alen(board, opp, qsq) <= 1):
            return True
        return False

    qsq = -1
    for s in board.pieces(chess.QUEEN, opp):
        qsq = s
        break

    if qsq != -1 and queen_exposed(qsq):
        for m in board.legal_moves:
            if board.is_capture(m) or m.promotion:
                continue
            pc = board.piece_at(m.from_square)
            if not pc or pc.color != stm:
                continue
            pt = pc.piece_type
            if pt not in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                continue
            good = False
            if pt in (chess.KNIGHT, chess.BISHOP):
                if rr(m.from_square, stm) <= 1 and rr(m.to_square, stm) >= 2:
                    good = True
                elif rr(m.to_square, stm) >= 2 and chess.square_distance(m.to_square, qsq) <= 3 and alen(board, opp, qsq) <= 1:
                    good = True
            elif rr(m.to_square, stm) >= 3:
                good = True
            if not good:
                continue
            nb = board.copy(stack=False)
            nb.push(m)
            mp = nb.piece_at(m.to_square)
            qp = nb.piece_at(qsq)
            if mp and qp and mp.color == stm and qp.color == opp and qp.piece_type == chess.QUEEN:
                if qsq in nb.attacks(m.to_square) and safe_lesser(nb, m.to_square, pt):
                    return True

    def target_escapes(b, tsq):
        tp = b.piece_at(tsq)
        if not tp:
            return 9
        n = 0
        for dsq in b.attacks(tsq):
            occ = b.piece_at(dsq)
            if occ and occ.color == opp:
                continue
