import chess

MOTIF_NAME = 'material-balanced exposed king pressure'
MOTIF_DESCRIPTION = 'Without a material surplus, the side to move has concentrated piece pressure against an exposed or overburdened opponent king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    if board.is_check():
        return False
    stm = board.turn
    opp = not stm
    vals = [0, 1, 3, 3, 5, 9, 0]

    def mat(c):
        s = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            s += vals[pt] * len(board.pieces(pt, c))
        return s

    m = mat(stm) - mat(opp)
    if m >= 1 or m < -3:
        return False

    ok = board.king(opp)
    sk = board.king(stm)
    if ok is None or sk is None:
        return False

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    if rel(ok, opp) > 1:
        return False

    def shelter(c, k):
        kf = chess.square_file(k)
        kr = chess.square_rank(k)
        d = 1 if c == chess.WHITE else -1
        s = 0
        for df in (-1, 0, 1):
            f = kf + df
            if 0 <= f < 8:
                for step, v in ((1, 2), (2, 1)):
                    r = kr + d * step
                    if 0 <= r < 8:
                        p = board.piece_at(chess.square(f, r))
                        if p and p.color == c and p.piece_type == chess.PAWN:
                            s += v
        return s

    def open_near(c, k):
        kf = chess.square_file(k)
        n = 0
        for f in range(max(0, kf - 1), min(7, kf + 1) + 1):
            has_pawn = False
            for r in range(8):
                p = board.piece_at(chess.square(f, r))
                if p and p.color == c and p.piece_type == chess.PAWN:
                    has_pawn = True
                    break
            if not has_pawn:
                n += 1
        return n

    kf = chess.square_file(ok)
    kr = chess.square_rank(ok)
    d = 1 if opp == chess.WHITE else -1
    close = set()
    zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            f = kf + df
            r = kr + dr
            if 0 <= f < 8 and 0 <= r < 8:
                sq = chess.square(f, r)
                close.add(sq)
                zone.add(sq)
    for df in (-2, -1, 0, 1, 2):
        f = kf + df
        if 0 <= f < 8:
            for step in (1, 2, 3):
                r = kr + d * step
                if 0 <= r < 8:
                    zone.add(chess.square(f, r))

    weights = [0, 1, 3, 3, 4, 5, 0]
    score = 0
    close_score = 0
    pieces = 0
    close_pieces = 0
    has_q = False

    for sq, pc in board.piece_map().items():
        if pc.color != stm or pc.piece_type == chess.KING:
            continue
        if pc.piece_type == chess.QUEEN:
            has_q = True
        att = board.attacks(sq)
        hits = 0
        chits = 0
        for z in zone:
            if z in att:
                hits += 1
        if hits:
            score += weights[pc.piece_type] + min(hits - 1, 2)
            if pc.piece_type != chess.PAWN:
                pieces += 1
        for z in close:
            if z in att:
                chits += 1
        if chits:
            close_score += weights[pc.piece_type] + min(chits - 1, 1)
            if pc.piece_type != chess.PAWN:
                close_pieces += 1

    opp_sh = shelter(opp, ok)
    own_sh = shelter(stm, sk)
    openf = open_near(opp, ok)
    weak = opp_sh <= 2 or openf >= 2

    checks = 0
    if (score >= 10 and pieces >= 2) or (score >= 15 and pieces >= 4):
        for mv in board.legal_moves:
            if board.gives_check(mv):
                checks += 1
                if checks >= 3:
                    break

    if weak and close_pieces >= 2 and pieces >= 3 and score >= 12 and close_score >= 8:
        if checks >= 1 or close_pieces >= 3:
            return True

    if weak and has_q and m >= -1 and rel(sk, stm) <= 1 and own_sh >= 4:
        if pieces >= 3 and score >= 12 and (close_score >= 4 or openf >= 2):
            if checks >= 1 or close_pieces >= 1:
                return True

    if m >= -1 and rel(sk, stm) <= 1 and own_sh >= 4:
        if pieces >= 4 and score >= 17 and close_pieces >= 1 and checks >= 1:
            return True

    return False

import chess

MOTIF_NAME = 'deep spear pins and checking reserves'
MOTIF_DESCRIPTION = 'At near material balance, the side to move has a deep queen spear, a strong slider pin, multiple safe checks, or bishop pressure against knight-only defenders.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    if board.is_check():
        return False

    vals = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def material():
        s = 0
        for pt, v in vals.items():
            s += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
        return s

    mat = material()

    def weak_shelter(color):
        k = board.king(color)
        if k is None:
            return True
        f = chess.square_file(k)
        r = chess.square_rank(k)
        step = 1 if color == chess.WHITE else -1
        score = 0
        for d, pts in ((1, 2), (2, 1)):
            rr = r + step * d
            if 0 <= rr < 8:
                for ff in (f - 1, f, f + 1):
                    if 0 <= ff < 8:
                        p = board.piece_at(chess.square(ff, rr))
                        if p and p.color == color and p.piece_type == chess.PAWN:
                            score += pts
        central_home = f in (3, 4) and ((color == chess.WHITE and r <= 1) or (color == chess.BLACK and r >= 6))
        advanced = (color == chess.WHITE and r >= 2) or (color == chess.BLACK and r <= 5)
        return score <= 2 or (central_home and score <= 3) or (advanced and score <= 3)

    own_weak = weak_shelter(stm)
    opp_weak = weak_shelter(opp)

    def king_ring(k):
        out = []
        f = chess.square_file(k)
        r = chess.square_rank(k)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df or dr:
                    ff = f + df
                    rr = r + dr
                    if 0 <= ff < 8 and 0 <= rr < 8:
                        out.append(chess.square(ff, rr))
        return out

    def deep_queen_spear():
        if mat < -2 or mat > 1 or not opp_weak:
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        ring = king_ring(ok)
        for q in board.pieces(chess.QUEEN, stm):
            if rel(q, stm) < 5:
                continue
            qa = board.attacks(q)
            if chess.square_distance(q, ok) > 3 and not any(s in qa for s in ring):
                continue
            oat = list(board.attackers(opp, q))
            cheap = False
            for a in oat:
                p = board.piece_at(a)
                if p and vals.get(p.piece_type, 0) < 9:
                    cheap = True
                    break
            if cheap and len(board.attackers(stm, q)) < len(oat):
                continue
            score = 0
            big = 0
            for s in qa:
                p = board.piece_at(s)
                if p and p.color == opp and p.piece_type != chess.KING:
                    v = vals.get(p.piece_type, 0)
                    if v >= 3:
                        score += v
                        big += 1
                    elif chess.square_distance(s, ok) <= 2:
                        score += 1
            ring_hits = sum(1 for s in ring if s in qa)
            if score >= 5 or big >= 2 or ring_hits >= 4:
                return True
        return False

    def slider_pin():
        if mat < -1 or mat > 1 or own_weak:
            return False
        rd = ((1, 0), (-1, 0), (0, 1), (0, -1))
        bd = ((1, 1), (1, -1), (-1, 1), (-1, -1))
        for pt in (chess.ROOK, chess.BISHOP, chess.QUEEN):
            dirs = rd if pt == chess.ROOK else bd if pt == chess.BISHOP else rd + bd
            for s in board.pieces(pt, stm):
                sf = chess.square_file(s)
                sr = chess.square_rank(s)
                for df, dr in dirs:
                    ff = sf + df
                    rr = sr + dr
                    front = None
                    while 0 <= ff < 8 and 0 <= rr < 8:
                        ns = chess.square(ff, rr)
                        pc = board.piece_at(ns)
                        if pc:
                            if front is None:
                                if pc.color == opp and pc.piece_type not in (chess.KING, chess.PAWN):
                                    front = ns
                                else:
                                    break
                            else:
                                if pc.color == opp and pc.piece_type in (chess.KING, chess.QUEEN):
                                    tpc = board.piece_at(front)
                                    tv = vals.get(tpc.piece_type, 0)
                                    att = board.attackers(stm, front)
                                    deff = board.attackers(opp, front)
                                    minatt = 99
                                    for a in att:
                                        ap = board.piece_at(a)
                                        if ap:
                                            minatt = min(minatt, vals.get(ap.piece_type, 9))
                                    if pc.piece_type == chess.KING:
                                        kf = chess.square_file(ns)
                                        if opp_weak and (2 <= kf <= 5 or rel(front, stm) >= 5) and len(att) + 1 >= len(deff):
                                            return True
                                    elif tv >= 3 and minatt <= tv and len(att) >= len(deff):
                                        return True
                                break
                        ff += df
                        rr += dr
        return False

    def checking_reserve():
        if mat < -1 or mat > 1 or own_weak or not opp_weak:
            return False
        checks = 0
        types = set()
        for mv in tuple(board.legal_moves):
            p = board.piece_at(mv.from_square)
            if not p or p.color != stm or p.piece_type == chess.KING:
                continue
            cap = board.piece_at(mv.to_square)
            capv = vals.get(cap.piece_type, 0) if cap else 0
            pv = vals.get(p.piece_type, 0)
            board.push(mv)
            if board.is_check():
                a = len(board.attackers(stm, mv.to_square))
                d = len(board.attackers(opp, mv.to_square))
                if p.piece_type in (chess.PAWN, chess.KNIGHT) or capv + 1 >= pv or a >= d:
                    checks += 1
                    types.add(p.piece_type)
            board.pop()
            if checks >= 3 or (checks >= 2 and len(types) >= 2 and any(t in types for t in (chess.PAWN, chess.KNIGHT, chess.BISHOP))):
                return True
        return False

    def bishop_vs_knights():
        if mat < -1 or mat > 1 or own_weak:
            return False
        if board.pieces(chess.QUEEN, stm) or board.pieces(chess.QUEEN, opp):
            return False
        if len(board.pieces(chess.BISHOP, stm)) < 1 or len(board.pieces(chess.BISHOP, opp)) > 0:
            return False
        if len(board.pieces(chess.KNIGHT, opp)) < 1 or len(board.pieces(chess.ROOK, stm)) < 2:
            return False
        if len(board.pieces(chess.PAWN, stm)) + len(board.pieces(chess.PAWN, opp)) > 13:
            return False
        for n in board.pieces(chess.KNIGHT, opp):
            if rel(n, opp) < 3:
                continue
            at = board.attackers(stm, n)
            good = False
            for a in at:
                ap = board.piece_at(a)
                if ap and ap.color == stm and ap.piece_type in (chess.BISHOP, chess.ROOK, chess.PAWN):
                    good = True
                    break
            if not good:
                continue
            de = board.attackers(opp, n)
            pawn_def = False
            for d in de:
                dp = board.piece_at(d)
                if dp and dp.piece_type == chess.PAWN:
                    pawn_def = True
                    break
            if len(at) >= len(de) or (len(at) + 1 >= len(de) and not pawn_def):
                return True
        return False

    return deep_queen_spear() or slider_pin() or checking_reserve() or bishop_vs_knights()

