    ek = board.king(opp)
    mk = board.king(stm)
    if ek is None or mk is None:
        return False

    vals = (0, 100, 320, 330, 500, 900, 0)

    def rr(sq):
        r = chess.square_rank(sq)
        return r if stm == chess.WHITE else 7 - r

    mat = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        mat += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if mat > 260 or mat < -430:
        return False

    mf = chess.square_file(mk)
    mr = chess.square_rank(mk)
    step_own = 1 if stm == chess.WHITE else -1
    shield = 0
    for df in (-1, 0, 1):
        for d in (1, 2):
            f = mf + df
            r = mr + step_own * d
            if 0 <= f < 8 and 0 <= r < 8:
                p = board.piece_at(chess.square(f, r))
                if p and p.color == stm and p.piece_type == chess.PAWN:
                    shield += 1
    mrr = rr(mk)
    safe = (mrr <= 1 and (mf <= 2 or mf >= 5) and shield >= 2) or (mrr <= 2 and (mf <= 2 or mf >= 5) and shield >= 3)
    if not safe:
        return False

    ef = chess.square_file(ek)
    er = chess.square_rank(ek)
    err = rr(ek)
    if err < 5 or 3 <= ef <= 4:
        return False

    front = -1 if stm == chess.WHITE else 1
    zone = set()
    for df in range(-2, 3):
        for dr in range(-2, 3):
            f = ef + df
            r = er + dr
            if 0 <= f < 8 and 0 <= r < 8:
                zone.add(chess.square(f, r))
    for df in range(-2, 3):
        for d in (1, 2, 3):
            f = ef + df
            r = er + front * d
            if 0 <= f < 8 and 0 <= r < 8:
                zone.add(chess.square(f, r))
    zone.discard(ek)

    def near_file(f):
        return abs(f - ef) <= (2 if ef in (0, 7) else 1)

    shelter = 0
    hook_attacked = False
    queen_hook = False
    for t in zone:
        p = board.piece_at(t)
        if p and p.color == opp and p.piece_type == chess.PAWN and near_file(chess.square_file(t)):
            d = err - rr(t)
            if 0 <= d <= 2:
                shelter += 1
            if 0 <= d <= 3 and len(board.attackers(stm, t)):
                hook_attacked = True
                for a in board.attackers(stm, t):
                    ap = board.piece_at(a)
                    if ap and ap.color == stm and ap.piece_type == chess.QUEEN:
                        queen_hook = True

    attack = 0.0
    pieces = 0
    qhits = 0
    minor_pieces = 0
    bishop_pieces = 0
    for pt, base in ((chess.QUEEN, 2.1), (chess.ROOK, 1.45), (chess.BISHOP, 1.25), (chess.KNIGHT, 1.25)):
        for sq in board.pieces(pt, stm):
            hits = []
            for t in board.attacks(sq):
                if t in zone:
                    hits.append(t)
            if hits:
                pieces += 1
                w = base + min(0.35, 0.15 * (len(hits) - 1))
                if any(chess.square_distance(t, ek) <= 1 for t in hits):
                    w += 0.2
                if any((board.piece_at(t) and board.piece_at(t).color == opp) for t in hits):
                    w += 0.25
                attack += w
                if pt == chess.QUEEN:
                    qhits += len(hits)
                if pt in (chess.BISHOP, chess.KNIGHT):
                    minor_pieces += 1
                if pt == chess.BISHOP:
                    bishop_pieces += 1

    defence = 0.0
    for pt, base in ((chess.QUEEN, 1.35), (chess.ROOK, 1.15), (chess.BISHOP, 0.95), (chess.KNIGHT, 0.95)):
        for sq in board.pieces(pt, opp):
            for t in board.attacks(sq):
                if t in zone:
                    defence += base
                    break

    central_space = False
    for sq in board.pieces(chess.PAWN, stm):
        f = chess.square_file(sq)
        if 2 <= f <= 5 and rr(sq) >= 3:
            central_space = True
            break

    own_b = len(board.pieces(chess.BISHOP, stm))
    own_n = len(board.pieces(chess.KNIGHT, stm))
    opp_b = len(board.pieces(chess.BISHOP, opp))
    opp_n = len(board.pieces(chess.KNIGHT, opp))

    if err <= 6 and qhits and minor_pieces and shelter <= 2 and mat >= -160 and (central_space or hook_attacked) and attack >= 3.1 and attack + 0.7 >= defence:
        return True
    if (err <= 6 or shelter <= 1) and qhits and pieces >= 3 and mat >= -260 and (shelter <= 2 or hook_attacked) and attack >= 4.0 and attack + 0.5 >= defence:
        return True
    if queen_hook and mat >= -160 and central_space and own_b >= 1 and own_n == 0 and opp_b == 0 and opp_n <= 1:
        return True
    if err <= 6 and queen_hook and mat >= -380 and own_b >= 2 and bishop_pieces >= 1 and pieces >= 2 and shelter <= 2 and attack + 0.8 >= defence:
        return True

    if mat >= -300 and err <= 6:
        for sq in board.pieces(chess.ROOK, stm):
            if rr(sq) >= 6:
                attacked = len(board.attackers(opp, sq))
                defended = len(board.attackers(stm, sq))
                if attacked and defended < attacked:
                    continue
                for t in board.attacks(sq):
                    p = board.piece_at(t)
                    if p and p.color == opp and p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                        if t in zone and chess.square_distance(t, ek) <= 2:
                            return True
    return False

