                if p.piece_type != chess.PAWN:
                    hit_piece = True
                elif chess.square_distance(t, ok) <= 2:
                    shield_hit = True
        if blocked_high or hit_piece or shield_hit:
            return True
        if rel >= 6 and passed_pawn(sq):
            return True
        if passed_pawn(sq) and chess.square_distance(sq, ok) <= 3:
            return True

    deep = []
    for pt in (chess.KNIGHT, chess.BISHOP):
        for sq in board.pieces(pt, stm):
            if rr(sq) >= 5:
                deep.append(sq)

    for sq in deep:
        rel = rr(sq)
        defs = len(board.attackers(stm, sq))
        pawn_at = 0
        for a in board.attackers(opp, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                pawn_at += 1
        major_hit = False
        pawn_hits = 0
        zone_hits = 0
        for t in board.attacks(sq):
            if chess.square_distance(t, ok) <= 1:
                zone_hits += 1
            p = board.piece_at(t)
            if p and p.color == opp:
                if p.piece_type in (chess.ROOK, chess.QUEEN):
                    major_hit = True
                elif p.piece_type == chess.PAWN:
                    pawn_hits += 1
        if rel >= 6 and (major_hit or pawn_hits or zone_hits) and (defs or len(deep) >= 2 or pawn_at == 0):
            return True
        if rel >= 5 and defs and pawn_at == 0 and (major_hit or pawn_hits >= 2 or zone_hits >= 2):
            return True

    return False

import chess

MOTIF_NAME = 'queenless small-edge endgame conversion'
MOTIF_DESCRIPTION = 'With queens off and material only slightly favorable, the side to move has a clean simplified edge, a central knight, connected advanced pawns, or a safe major-piece pickup.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = (0, 100, 320, 330, 500, 900, 0)

    def rr(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def mat(b, color):
        s = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            s += vals[pt] * (len(b.pieces(pt, color)) - len(b.pieces(pt, not color)))
        return s

    def enemy_pawn_attacks(sq):
        for a in board.attackers(opp, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                return True
        return False

    def loose_piece():
        for sq, p in board.piece_map().items():
            if p.color == stm and p.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
                if len(board.attackers(opp, sq)) and len(board.attackers(stm, sq)) == 0:
                    return True
        return False

    def central_knight():
        if len(board.pieces(chess.KNIGHT, stm)) <= len(board.pieces(chess.KNIGHT, opp)):
            return False
        for n in board.pieces(chess.KNIGHT, stm):
            f = chess.square_file(n)
            if 2 <= f <= 5 and 3 <= rr(n, stm) <= 5:
                if len(board.attackers(stm, n)) and len(board.attackers(stm, n)) >= len(board.attackers(opp, n)):
                    if not enemy_pawn_attacks(n):
                        return True
        return False

    def passed_pawn(sq, color):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        for ep in board.pieces(chess.PAWN, not color):
            ef = chess.square_file(ep)
            er = chess.square_rank(ep)
            if abs(ef - f) <= 1 and ((color == chess.WHITE and er > r) or (color == chess.BLACK and er < r)):
                return False
        return True

    def protected_passer():
        for p in board.pieces(chess.PAWN, stm):
            if rr(p, stm) >= 4 and passed_pawn(p, stm) and len(board.attackers(stm, p)):
                return True
        return False

    def connected_advanced():
        ps = list(board.pieces(chess.PAWN, stm))
        for i in range(len(ps)):
            a = ps[i]
            if rr(a, stm) < 3:
                continue
            for b in ps[i + 1:]:
                if rr(b, stm) >= 3 and abs(chess.square_file(a) - chess.square_file(b)) == 1:
                    if b in board.attacks(a) or a in board.attacks(b) or abs(chess.square_rank(a) - chess.square_rank(b)) <= 1:
                        return True
        return False

    base_mat = mat(board, stm)

    for m in board.legal_moves:
        pc = board.piece_at(m.from_square)
        target = board.piece_at(m.to_square)
        if pc and target and target.color == opp and target.piece_type in (chess.ROOK, chess.QUEEN):
            good_king_take = pc.piece_type == chess.KING and rr(m.to_square, stm) <= 1
            good_gain = vals[target.piece_type] - vals[pc.piece_type] >= 180
            if good_king_take or good_gain:
                nb = board.copy(stack=False)
                nb.push(m)
                if mat(nb, stm) >= -120:
                    if pc.piece_type == chess.KING:
                        return True
                    if len(nb.attackers(opp, m.to_square)) == 0 or len(nb.attackers(stm, m.to_square)) >= len(nb.attackers(opp, m.to_square)):
                        return True

    if board.pieces(chess.QUEEN, stm) or board.pieces(chess.QUEEN, opp) or board.is_check():
        return False

    nonpawn = 0
    for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
        nonpawn += len(board.pieces(pt, stm)) + len(board.pieces(pt, opp))

    clean = not loose_piece()
    own_rooks = len(board.pieces(chess.ROOK, stm))
    opp_rooks = len(board.pieces(chess.ROOK, opp))

    if clean and 60 <= base_mat <= 160:
        if nonpawn <= 5:
            return True
        if nonpawn <= 8 and (central_knight() or protected_passer()):
            return True

    if clean and -10 <= base_mat <= 130:
        if own_rooks >= 2 and opp_rooks <= 1 and connected_advanced():
            return True

    return False

