import math

MOTIF_NAME = 'minor swarm imbalance and clean major tactic'
MOTIF_DESCRIPTION = 'Without a material surplus, the side to move has a favorable minor-piece swarm, a queenless chase of a central king, or a concrete safe major-piece tactic.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None or board.is_check():
        return False

    vals = {chess.PAWN: 1.0, chess.KNIGHT: 3.0, chess.BISHOP: 3.1, chess.ROOK: 5.0, chess.QUEEN: 9.0}

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def cnt(pt, c):
        return len(board.pieces(pt, c))

    mat = 0.0
    for pt, v in vals.items():
        mat += v * (cnt(pt, stm) - cnt(pt, opp))
    if cnt(chess.BISHOP, stm) >= 2:
        mat += 0.35
    if cnt(chess.BISHOP, opp) >= 2:
        mat -= 0.35

    def zone_attackers(c, ksq):
        f = chess.square_file(ksq)
        r = chess.square_rank(ksq)
        out = set()
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    out.update(board.attackers(c, chess.square(nf, nr)))
        return len(out)

    no_queens = cnt(chess.QUEEN, stm) + cnt(chess.QUEEN, opp) == 0
    own_danger = zone_attackers(opp, mk)
    own_safe = own_danger <= 3 or (no_queens and own_danger <= 4 and rel(mk, stm) <= 3)

    def pawn_attacks(c, sq):
        for a in board.attackers(c, sq):
            p = board.piece_at(a)
            if p and p.color == c and p.piece_type == chess.PAWN:
                return True
        return False

    def minor_swarm():
        own_min = cnt(chess.KNIGHT, stm) + cnt(chess.BISHOP, stm)
        opp_min = cnt(chess.KNIGHT, opp) + cnt(chess.BISHOP, opp)
        if own_min < opp_min + 2 or cnt(chess.ROOK, opp) <= cnt(chess.ROOK, stm):
            return False
        if not (-1.25 <= mat <= 0.8) or cnt(chess.PAWN, stm) + cnt(chess.PAWN, opp) < 10 or not own_safe:
            return False
        active = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if len(board.attackers(stm, sq)) and not pawn_attacks(opp, sq):
                    if rel(sq, stm) >= 2 or 2 <= chess.square_file(sq) <= 5:
                        active += 1
        if active < 2:
            return False
        back_rooks = 0
        for sq in board.pieces(chess.ROOK, opp):
            if rel(sq, opp) <= 1:
                back_rooks += 1
        return back_rooks >= 1

    def central_king_chase():
        if not no_queens or not own_safe or not (-1.5 <= mat <= 1.0):
            return False
        ef = chess.square_file(ek)
        if rel(ek, opp) < 2 or ef < 2 or ef > 5:
            return False
        if zone_attackers(stm, ek) < 3:
            return False
        has_check = False
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if p and p.color == stm and p.piece_type != chess.KING and board.gives_check(mv):
                has_check = True
                break
        return has_check and cnt(chess.ROOK, stm) >= 1 and (cnt(chess.KNIGHT, stm) + cnt(chess.BISHOP, stm) >= 1)

    def concrete_tactic():
        if not own_safe or mat > 0.8 or mat < -3.2:
            return False
        for mv in board.legal_moves:
            p = board.piece_at(mv.from_square)
            if not p or p.color != stm or p.piece_type == chess.KING:
                continue
            if board.is_capture(mv):
                t = board.piece_at(mv.to_square)
                if t and t.color == opp and t.piece_type in (chess.ROOK, chess.QUEEN):
                    gain = vals[t.piece_type] - vals[p.piece_type]
                    if gain >= 2.0:
                        b2 = board.copy(stack=False)
                        b2.push(mv)
                        oa = len(b2.attackers(opp, mv.to_square))
                        da = len(b2.attackers(stm, mv.to_square))
                        if t.piece_type == chess.QUEEN and gain >= 4.0:
                            return True
                        if oa == 0 or da >= oa:
                            return True
            if p.piece_type == chess.KNIGHT and board.gives_check(mv):
                b2 = board.copy(stack=False)
                b2.push(mv)
                hit = 0
                for tsq in b2.attacks(mv.to_square):
                    q = b2.piece_at(tsq)
                    if q and q.color == opp and q.piece_type in (chess.ROOK, chess.QUEEN):
                        hit += vals[q.piece_type]
                if hit >= 5 and len(b2.attackers(opp, mv.to_square)) <= len(b2.attackers(stm, mv.to_square)) + 1:
                    return True
        return False

    return minor_swarm() or central_king_chase() or concrete_tactic()

import chess

MOTIF_NAME = 'supported queen lift and central overload'
MOTIF_DESCRIPTION = 'With material close and a safe king, the side to move has a supported queen lift against a castled shelter, an open major-piece overload near a central king, or a queenless bishop-pair bind.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0}
    pieces = board.piece_map()
    mat = 0
    for sq, p in pieces.items():
        mat += vals[p.piece_type] if p.color == stm else -vals[p.piece_type]
    if mat < -550 or mat > 300:
        return False

    sk = board.king(stm)
    ok = board.king(opp)
    if sk is None or ok is None:
        return False

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def nonking_defended(sq, color, exclude=-1):
        for a in board.attackers(color, sq):
            if a == exclude:
                continue
            p = board.piece_at(a)
            if p and p.color == color and p.piece_type != chess.KING:
                return True
        return False

    def king_ok(sq, color):
        f = chess.square_file(sq)
        return rel(sq, color) <= 1 and (f <= 2 or f >= 5) and len(board.attackers(not color, sq)) == 0

    own_safe = king_ok(sk, stm)

    def supported_queen_lift():
        if not own_safe or rel(ok, opp) > 1:
            return False
        of = chess.square_file(ok)
        if 3 <= of <= 4:
            return False
        edge = 0 if of <= 3 else 7
        for q in board.pieces(chess.QUEEN, stm):
            for s in board.attacks(q):
                pc = board.piece_at(s)
                if pc and pc.color == stm:
                    continue
                if rel(s, opp) not in (2, 3):
                    continue
                sf = chess.square_file(s)
                if abs(sf - of) > 1 and sf != edge:
                    continue
                helper = False
                for a in board.attackers(stm, s):
                    if a == q:
                        continue
                    ap = board.piece_at(a)
                    if ap and ap.color == stm and ap.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK):
                        helper = True
                        break
                if not helper:
                    continue
                hook = False
                for ps in board.pieces(chess.PAWN, stm):
                    if rel(ps, stm) >= 3 and chess.square_distance(ps, s) <= 2 and chess.square_distance(ps, ok) <= 4:
                        if nonking_defended(ps, stm, q):
                            hook = True
                            break
                if not hook:
                    continue
                mv = chess.Move(q, s)
                if not board.is_legal(mv):
                    continue
                nb = board.copy(stack=False)
                nb.push(mv)
                own_def = 0
                enemy_low = 0
                for a in nb.attackers(stm, s):
                    ap = nb.piece_at(a)
                    if ap and ap.color == stm and ap.piece_type != chess.KING:
                        own_def += 1
                for a in nb.attackers(opp, s):
                    ap = nb.piece_at(a)
                    if ap and ap.color == opp and ap.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                        enemy_low += 1
                if enemy_low > own_def:
                    continue
                hits_shelter = False
                for t in nb.attacks(s):
                    tp = nb.piece_at(t)
                    if tp and tp.color == opp and tp.piece_type == chess.PAWN:
                        if rel(t, opp) <= 2 and chess.square_distance(t, ok) <= 2:
                            hits_shelter = True
                            break
                if hits_shelter:
                    return True
        return False

    def central_open_overload():
        if not own_safe or rel(ok, opp) > 1:
            return False
        of = chess.square_file(ok)
        if of < 2 or of > 5:
            return False
        major_hit = False
        kf = chess.square_file(ok)
        kr = chess.square_rank(ok)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                f = kf + df
                r = kr + dr
                if f < 0 or f > 7 or r < 0 or r > 7:
                    continue
                z = chess.square(f, r)
                zp = board.piece_at(z)
                if zp and zp.color == stm:
                    continue
                if abs(f - of) > 1:
                    continue
                for a in board.attackers(stm, z):
                    ap = board.piece_at(a)
                    if ap and ap.color == stm and ap.piece_type in (chess.ROOK, chess.QUEEN):
                        if chess.square_distance(a, z) >= 2 and abs(chess.square_file(a) - of) <= 2:
                            major_hit = True
                            break
                if major_hit:
                    break
            if major_hit:
                break
        if not major_hit:
            return False
        for t, tp in pieces.items():
            if tp.color != opp or tp.piece_type not in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
                continue
            if chess.square_distance(t, ok) > 2:
                continue
            att = 0
            heavy = False
            low = False
            for a in board.attackers(stm, t):
                ap = board.piece_at(a)
                if ap and ap.color == stm and ap.piece_type != chess.KING:
                    att += 1
                    if ap.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT):
                        heavy = True
                    if ap.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                        low = True
            if att >= 2 and heavy and (low or tp.piece_type in (chess.ROOK, chess.QUEEN)):
                return True
        return False

    def queenless_bishop_bind():
        if len(board.pieces(chess.QUEEN, stm)) or len(board.pieces(chess.QUEEN, opp)):
            return False
        if mat < -300 or mat > 250:
            return False
        if len(board.attackers(opp, sk)) or rel(sk, stm) > 2:
            return False
        if len(board.pieces(chess.BISHOP, stm)) < 2 or len(board.pieces(chess.BISHOP, opp)) >= 2:
            return False
        mob = 0
        pinhit = False
        for b in board.pieces(chess.BISHOP, stm):
            for x in board.attacks(b):
                xp = board.piece_at(x)
                if xp and xp.color == stm:
                    continue
                mob += 1
                if xp and xp.color == opp and xp.piece_type in (chess.KNIGHT, chess.BISHOP, chess.ROOK):
                    if rel(x, stm) >= 3 or chess.square_distance(x, ok) <= 2:
                        pinhit = True
        connected = False
        pawns = list(board.pieces(chess.PAWN, stm))
        for i in range(len(pawns)):
            a = pawns[i]
            if rel(a, stm) < 3:
                continue
            af = chess.square_file(a)
            ar = rel(a, stm)
            for b in pawns[i + 1:]:
                if rel(b, stm) >= 3 and abs(chess.square_file(b) - af) == 1 and abs(rel(b, stm) - ar) <= 1:
                    connected = True
                    break
            if connected:
                break
        return mob >= 10 and (pinhit or connected)

    return supported_queen_lift() or central_open_overload() or queenless_bishop_bind()

import chess

MOTIF_NAME = 'central file pressure with loose wedge pickup'
MOTIF_DESCRIPTION = 'With material close, the side to move has central-file rook pressure, a queen-rook battery on a weak target, or a safe pickup of an overadvanced enemy wedge.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = {
        chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
        chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 0
    }

    def ff(s):
        return chess.square_file(s)

    def rr(s, c):
        r = chess.square_rank(s)
        return r if c == chess.WHITE else 7 - r

    def mat(c):
        t = 0
        for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            t += len(board.pieces(pt, c)) * vals[pt]
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            t += 30
        return t

    adj = mat(stm) - mat(opp)

    def safe_piece_on(b, sq, c):
        pc = b.piece_at(sq)
        if pc is None:
            return False
        v = vals[pc.piece_type]
        at = list(b.attackers(not c, sq))
        if not at:
            return True
        de = len(b.attackers(c, sq))
        bad = 0
        for a in at:
            ap = b.piece_at(a)
            if ap is None:
                continue
            if ap.piece_type == chess.KING:
                if de == 0:
                    return False
            elif vals[ap.piece_type] <= v:
                bad += 1
        if bad == 0:
            return True
        return de >= bad + 1

    def clear_between(a, b):
        if ff(a) != ff(b):
            return False
        step = 8 if chess.square_rank(b) > chess.square_rank(a) else -8
        s = a + step
        while s != b:
            if board.piece_at(s) is not None:
                return False
            s += step
        return True

    def open_forward(s, c):
        step = 8 if c == chess.WHITE else -8
        t = s + step
        while 0 <= t < 64 and ff(t) == ff(s):
            p = board.piece_at(t)
            if p is not None:
                return p.color != c
            t += step
        return True

    def no_own_pawn_file(f, c):
        for p in board.pieces(chess.PAWN, c):
            if ff(p) == f:
                return False
        return True

    def minor_zone_hits(c, ksq):
        kf = ff(ksq)
        kr = chess.square_rank(ksq)
        hits = 0
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf = kf + df
                nr = kr + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    z = chess.square(nf, nr)
                    for a in board.attackers(c, z):
                        p = board.piece_at(a)
                        if p and p.piece_type in (chess.KNIGHT, chess.BISHOP):
                            hits += 1
                            break
        return hits

    def developed(c):
        d = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for s in board.pieces(pt, c):
                if rr(s, c) >= 2:
                    d += 1
        for s in board.pieces(chess.ROOK, c):
            if rr(s, c) >= 2 or (2 <= ff(s) <= 5 and no_own_pawn_file(ff(s), c)):
                d += 1
        for s in board.pieces(chess.QUEEN, c):
            if rr(s, c) >= 1:
                d += 1
        return d

    def queenless_open_file():
        if board.is_check() or len(board.pieces(chess.QUEEN, stm)) or len(board.pieces(chess.QUEEN, opp)):
            return False
        if adj < -80 or adj > 180:
            return False
        if len(board.pieces(chess.PAWN, stm)) < len(board.pieces(chess.PAWN, opp)):
            return False
        ok = board.king(opp)
        if ok is None or rr(ok, opp) > 1 or not (2 <= ff(ok) <= 5):
            return False
        if minor_zone_hits(stm, ok) < 2 or developed(stm) + 1 < developed(opp):
            return False
        for r in board.pieces(chess.ROOK, stm):
            f = ff(r)
            if 2 <= f <= 5 and abs(f - ff(ok)) <= 2 and rr(r, stm) <= 3:
                if no_own_pawn_file(f, stm) and open_forward(r, stm):
                    return True
        return False

    def queen_rook_battery():
        if board.is_check() or adj < -100 or adj > 180:
            return False
        ok = board.king(opp)
        if ok is None:
            return False
        step = 8 if stm == chess.WHITE else -8
        for q in board.pieces(chess.QUEEN, stm):
            for r in board.pieces(chess.ROOK, stm):
                f = ff(r)
                if f != ff(q) or not (2 <= f <= 5):
                    continue
                if rr(r, stm) <= rr(q, stm) or rr(r, stm) < 2:
                    continue
                if not clear_between(q, r) or not safe_piece_on(board, r, stm):
                    continue
                t = r + step
                while 0 <= t < 64 and ff(t) == f:
                    pc = board.piece_at(t)
                    if pc is not None:
                        if pc.color == opp and pc.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                            if rr(t, stm) >= 3 and (2 <= f <= 5 or chess.square_distance(t, ok) <= 2):
                                a = len(board.attackers(stm, t))
                                d = len(board.attackers(opp, t))
                                if a >= d or (pc.piece_type == chess.PAWN and d <= 1):
                                    return True
                        break
                    t += step
        return False

    def safe_check_fork():
        if adj < -180 or adj > 180:
            return False
        for m in board.legal_moves:
            pc = board.piece_at(m.from_square)
            if pc is None or pc.color != stm or pc.piece_type not in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                continue
            if m.promotion or not board.gives_check(m):
                continue
            nb = board.copy(stack=False)
            nb.push(m)
            moved = nb.piece_at(m.to_square)
            if moved is None or moved.piece_type not in (chess.PAWN, chess.KNIGHT, chess.BISHOP):
                continue
            if not safe_piece_on(nb, m.to_square, stm):
                continue
            for pt in (chess.QUEEN, chess.ROOK):
                if vals[pt] < vals[moved.piece_type] + 200:
                    continue
                for t in nb.pieces(pt, opp):
                    if t in nb.attacks(m.to_square):
                        return True
        return False

    def wedge_pickup():
        if board.is_check() or len(board.pieces(chess.QUEEN, stm)) or len(board.pieces(chess.QUEEN, opp)):
            return False
        if adj < -220 or adj > 160:
            return False
        for m in board.legal_moves:
            pc = board.piece_at(m.from_square)
            tg = board.piece_at(m.to_square)
            if pc is None or tg is None or pc.color != stm or tg.color != opp:
                continue
            if pc.piece_type not in (chess.ROOK, chess.BISHOP, chess.KNIGHT):
                continue
            f = ff(m.to_square)
            if tg.piece_type == chess.PAWN:
                if rr(m.to_square, stm) > 3 or not (2 <= f <= 5):
                    continue
                pawn_def = False
                for a in board.attackers(opp, m.to_square):
                    ap = board.piece_at(a)
                    if ap and ap.piece_type == chess.PAWN:
                        pawn_def = True
                        break
                if pawn_def or adj + 100 < -120:
                    continue
            elif tg.piece_type in (chess.KNIGHT, chess.BISHOP):
                if rr(m.to_square, stm) < 3 or len(board.attackers(opp, m.to_square)) > 0:
                    continue
                if vals[tg.piece_type] < vals[pc.piece_type] or adj + vals[tg.piece_type] < -80:
                    continue
            else:
                continue
            nb = board.copy(stack=False)
            nb.push(m)
            if safe_piece_on(nb, m.to_square, stm):
                return True
        return False

    return queenless_open_file() or queen_rook_battery() or safe_check_fork() or wedge_pickup()

import chess

MOTIF_NAME = 'compensating minor net and rook-lift spear'
MOTIF_DESCRIPTION = 'Without a large material edge, the side to move has a safe king with a minor-piece net, deep pawn wedge, or rook-lift spear aimed at the enemy king.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    mk = board.king(stm)
    ek = board.king(opp)
    if mk is None or ek is None or board.is_check():
        return False

    vals = {chess.PAWN: 1.0, chess.KNIGHT: 3.2, chess.BISHOP: 3.25, chess.ROOK: 5.0, chess.QUEEN: 9.0}
    mat = 0.0
    for pt, v in vals.items():
        mat += v * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))
    if len(board.pieces(chess.BISHOP, stm)) >= 2:
        mat += 0.35
    if len(board.pieces(chess.BISHOP, opp)) >= 2:
        mat -= 0.35
    if mat > 1.6 or mat < -5.0:
        return False

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def ring(ksq):
        kf = chess.square_file(ksq)
        kr = chess.square_rank(ksq)
        out = []
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                if df == 0 and dr == 0:
                    continue
                nf, nr = kf + df, kr + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    out.append(chess.square(nf, nr))
        return out

    def zone(color, ksq, rad):
        kf = chess.square_file(ksq)
        kr = chess.square_rank(ksq)
        c = 0
        for df in range(-rad, rad + 1):
            for dr in range(-rad, rad + 1):
                if df == 0 and dr == 0:
                    continue
                nf, nr = kf + df, kr + dr
                if 0 <= nf < 8 and 0 <= nr < 8 and len(board.attackers(color, chess.square(nf, nr))):
                    c += 1
        return c

    def central_home(ksq, color):
        return 2 <= chess.square_file(ksq) <= 5 and rel(ksq, color) <= 2

    def flank_home(ksq, color):
        return (chess.square_file(ksq) <= 1 or chess.square_file(ksq) >= 6) and rel(ksq, color) <= 1

    def own_safe():
        z = zone(opp, mk, 1)
        f = chess.square_file(mk)
        if rel(mk, stm) <= 1 and 2 <= f <= 5 and z >= (1 if f in (3, 4) else 2):
            return False
        return z <= 4

    if not own_safe():
        return False

    def central_cordon():
        if not central_home(ek, opp):
            return False
        my_min = len(board.pieces(chess.KNIGHT, stm)) + len(board.pieces(chess.BISHOP, stm))
        op_min = len(board.pieces(chess.KNIGHT, opp)) + len(board.pieces(chess.BISHOP, opp))
        near = 0
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, stm):
                if chess.square_distance(sq, ek) <= 4:
                    near += 1
        z1 = zone(stm, ek, 1)
        z2 = zone(stm, ek, 2)
        if my_min >= 4 and my_min >= op_min + 1 and near >= 2 and (z1 >= 1 or z2 >= 3):
            return True
        if mat >= -2.0 and near >= 2 and z1 >= 3 and z1 >= zone(opp, mk, 1) + 2:
            return True
        ef = chess.square_file(ek)
        for psq in board.pieces(chess.PAWN, stm):
            pf = chess.square_file(psq)
            if rel(psq, stm) < 5 or chess.square_distance(psq, ek) > 3:
                continue
            if not (2 <= pf <= 5 or abs(pf - ef) <= 1):
                continue
            if len(board.attackers(stm, psq)) == 0:
                continue
            if len(board.attackers(opp, psq)) > len(board.attackers(stm, psq)) + 1:
                continue
            if z1 >= 2 or z2 >= 4:
                return True
        return False

    def shield_count():
        kf = chess.square_file(ek)
        kr = chess.square_rank(ek)
        step = 1 if opp == chess.WHITE else -1
        nr = kr + step
        if nr < 0 or nr > 7:
            return 0
        c = 0
        for df in (-1, 0, 1):
            nf = kf + df
            if 0 <= nf < 8:
                p = board.piece_at(chess.square(nf, nr))
                if p and p.color == opp and p.piece_type == chess.PAWN:
                    c += 1
        return c

    def rook_lift_spear():
        if not flank_home(ek, opp) or not len(board.pieces(chess.QUEEN, stm)):
            return False
        if shield_count() > 1:
            return False
        kf = chess.square_file(ek)
        ext = zone(stm, ek, 2)
        if zone(opp, mk, 2) > ext + 2:
            return False
        ering = ring(ek)
        contact = 0
        for pt in (chess.QUEEN, chess.BISHOP, chess.KNIGHT):
            for sq in board.pieces(pt, stm):
                if chess.square_distance(sq, ek) <= 3:
                    contact += 2 if pt == chess.QUEEN else 1
                else:
                    ats = board.attacks(sq)
                    for ns in ering:
                        if ns in ats:
                            contact += 2 if pt == chess.QUEEN else 1
                            break
        for rsq in board.pieces(chess.ROOK, stm):
            rr = rel(rsq, stm)
            rf = chess.square_file(rsq)
            if rr not in (2, 3) or abs(rf - kf) > 2:
                continue
            if len(board.attackers(opp, rsq)) > len(board.attackers(stm, rsq)) + 1:
                continue
            strong = False
            loose = False
            for psq in board.pieces(chess.PAWN, stm):
                pr = rel(psq, stm)
                pf = chess.square_file(psq)
                if abs(pf - kf) <= 2 and chess.square_distance(psq, ek) <= 4:
                    if pr >= 4:
                        strong = True
                    elif pr >= 3 and abs(pf - kf) <= 1:
                        loose = True
            if strong and ext >= 1:
                return True
            if (loose or ext >= 3) and contact >= 1:
                return True
        return False

    return central_cordon() or rook_lift_spear()

import chess

MOTIF_NAME = 'sub-pawn exchange and sixth-rank activity'
MOTIF_DESCRIPTION = 'Without a pawn-sized material surplus, the side to move has a fractional exchange edge, a safe sixth-rank rook, a no-bishop knight storm, or a concrete low-piece capture of a trapped major piece.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    vals = (0, 100, 320, 330, 500, 900, 0)

    def rel(sq, color):
        r = chess.square_rank(sq)
        return r if color == chess.WHITE else 7 - r

    def rr(sq):
        return rel(sq, stm)

    def pawn_atk(color, sq):
        n = 0
        for a in board.attackers(color, sq):
            p = board.piece_at(a)
            if p and p.piece_type == chess.PAWN:
                n += 1
        return n

    def file_has_pawn(color, f):
        for p in board.pieces(chess.PAWN, color):
            if chess.square_file(p) == f:
                return True
        return False

    def king_safe(color):
        k = board.king(color)
        if k is None:
            return False
        if color == board.turn and board.is_check():
            return False
        enemy = not color
        danger = 0
        kf, kr = chess.square_file(k), chess.square_rank(k)
        for df in (-1, 0, 1):
            for dr in (-1, 0, 1):
                f, r = kf + df, kr + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    sq = chess.square(f, r)
                    for a in board.attackers(enemy, sq):
                        p = board.piece_at(a)
                        if p and p.piece_type != chess.KING:
                            danger += 1
        q_enemy = len(board.pieces(chess.QUEEN, enemy))
        rf = rel(k, color)
        if q_enemy:
            return rf <= 1 and (kf <= 2 or kf >= 5) and danger <= 5
        return rf <= 2 and danger <= 6

    mat = 0
    for pt in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
        mat += vals[pt] * (len(board.pieces(pt, stm)) - len(board.pieces(pt, opp)))

    own_bishops = len(board.pieces(chess.BISHOP, stm))
    opp_bishops = len(board.pieces(chess.BISHOP, opp))
    own_knights = len(board.pieces(chess.KNIGHT, stm))
    opp_knights = len(board.pieces(chess.KNIGHT, opp))
    own_rooks = len(board.pieces(chess.ROOK, stm))
    opp_rooks = len(board.pieces(chess.ROOK, opp))
    own_q = len(board.pieces(chess.QUEEN, stm))
    opp_q = len(board.pieces(chess.QUEEN, opp))

    mat_adj = mat
    if own_bishops >= 2:
        mat_adj += 50
    if opp_bishops >= 2:
        mat_adj -= 50
    if mat_adj >= 100:
        return False

    if mat_adj >= -80 and own_q == 0 and opp_q == 0 and own_rooks >= opp_rooks:
        for sq in board.pieces(chess.ROOK, stm):
            if rr(sq) >= 5:
                attackers = len(board.attackers(opp, sq))
                defenders = len(board.attackers(stm, sq))
                if attackers > defenders + 1:
                    continue
                pa = pawn_atk(opp, sq)
                if pa and defenders < pa:
                    continue
                targets = 0
                for t in board.attacks(sq):
                    p = board.piece_at(t)
                    if p and p.color == opp and p.piece_type != chess.KING:
                        targets += 1
                if targets >= 2 or (rr(sq) >= 6 and targets >= 1):
                    return True

    own_minors = own_bishops + own_knights
    opp_minors = opp_bishops + opp_knights
    if mat_adj >= -120 and own_rooks > opp_rooks and opp_minors >= own_minors + 1 and king_safe(stm):
        for sq in board.pieces(chess.ROOK, stm):
            f = chess.square_file(sq)
            if not file_has_pawn(stm, f) and (not file_has_pawn(opp, f) or rr(sq) >= 2):
                return True
            if rr(sq) >= 3:
                return True
        for pt in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(pt, opp):
                f = chess.square_file(sq)
                if f in (0, 1, 6, 7):
                    atk = len(board.attackers(stm, sq))
                    if atk and pawn_atk(opp, sq) == 0 and len(board.attackers(opp, sq)) <= atk + 1:
                        return True

    if mat_adj >= -80 and own_q and opp_q and own_bishops == 0 and opp_bishops == 0 and own_knights >= 2 and king_safe(stm):
        ek = board.king(opp)
        if ek is not None:
            ef = chess.square_file(ek)
            if rr(ek) >= 6 and (ef <= 1 or ef >= 6):
                files = []
                hook = False
                center = False
                for p in board.pieces(chess.PAWN, stm):
                    pf, pr = chess.square_file(p), rr(p)
                    if pf in (3, 4) and pr >= 3:
                        center = True
                    if abs(pf - ef) <= 2 and pr >= 3:
                        files.append(pf)
                        if pf == ef or abs(pf - ef) == 1 or pr >= 4:
                            hook = True
                u = sorted(set(files))
                if center and hook and len(u) >= 2 and u[-1] - u[0] <= 2:
                    return True

    for mv in board.legal_moves:
        if not board.is_capture(mv):
            continue
        pc = board.piece_at(mv.from_square)
        cap = board.piece_at(mv.to_square)
        if not pc or not cap or pc.color != stm or cap.color != opp:
            continue
        gain = vals[cap.piece_type] - vals[pc.piece_type]
        if mat + gain < 0:
            continue
        to_f = chess.square_file(mv.to_square)
        if cap.piece_type == chess.QUEEN and pc.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK) and gain >= 300:
            return True
        if cap.piece_type == chess.ROOK and pc.piece_type in (chess.PAWN, chess.KNIGHT, chess.BISHOP) and gain >= 160:
            if rr(mv.to_square) <= 3 or to_f in (0, 1, 6, 7):
                return True

    return False

import chess

MOTIF_NAME = 'dual-reserve central king squeeze'
MOTIF_DESCRIPTION = 'With material close, the side to move keeps flexible castling or coordinated slider pressure while the opposing king is still stuck near the center.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm
    ok = board.king(opp)
    mk = board.king(stm)
    if ok is None or mk is None:
        return False

    vals = {chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330, chess.ROOK: 500, chess.QUEEN: 900}

    def mat(c):
        s = 0
        for pt, v in vals.items():
            s += v * len(board.pieces(pt, c))
        if len(board.pieces(chess.BISHOP, c)) >= 2:
            s += 35
        return s

    score = mat(stm) - mat(opp)

    def rel(sq, c):
        r = chess.square_rank(sq)
        return r if c == chess.WHITE else 7 - r

    def central_king(sq, c, depth):
        return rel(sq, c) <= depth and 2 <= chess.square_file(sq) <= 5

    def castles(c):
        return int(board.has_kingside_castling_rights(c)) + int(board.has_queenside_castling_rights(c))

    def zone(sq, rad):
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        z = set()
        for df in range(-rad, rad + 1):
            for dr in range(-rad, rad + 1):
                if df == 0 and dr == 0:
                    continue
                nf, nr = f + df, r + dr
                if 0 <= nf < 8 and 0 <= nr < 8:
                    z.add(chess.square(nf, nr))
        return z

    def central_pawns(c):
        return sum(1 for p in board.pieces(chess.PAWN, c) if 2 <= chess.square_file(p) <= 5 and rel(p, c) >= 2)

    cp = central_pawns(stm)
    bp = len(board.pieces(chess.BISHOP, stm)) >= 2

    if -100 <= score <= 95 and central_king(ok, opp, 1):
        if castles(stm) == 2 and castles(opp) < 2 and (cp >= 2 or bp or rel(ok, opp) == 1):
            if not board.is_check() or cp >= 3 or (bp and cp >= 2):
                return True

    if -180 <= score <= 95 and central_king(ok, opp, 2):
        if len(board.pieces(chess.QUEEN, chess.WHITE)) + len(board.pieces(chess.QUEEN, chess.BLACK)) == 0:
            if len(board.pieces(chess.ROOK, stm)) >= 2:
                attackers = set()
                major = False
                for sq in zone(ok, 1):
                    for a in board.attackers(stm, sq):
                        p = board.piece_at(a)
                        if p and p.color == stm and p.piece_type not in (chess.KING, chess.PAWN):
                            attackers.add(a)
                            if p.piece_type == chess.ROOK:
                                major = True
                if major and len(attackers) >= 2:
                    enemy = set()
                    for sq in zone(mk, 1):
                        for a in board.attackers(opp, sq):
                            p = board.piece_at(a)
                            if p and p.color == opp and p.piece_type != chess.KING:
                                enemy.add(a)
                    if len(enemy) <= len(attackers) + 1:
                        return True

    if -80 <= score <= 95 and central_king(ok, opp, 1):
        if bp and len(board.pieces(chess.BISHOP, opp)) < 2:
            ext = zone(ok, 2)
            bh = 0
            for b in board.pieces(chess.BISHOP, stm):
                if any(t in ext for t in board.attacks(b)):
                    bh += 1
            qh = False
            for q in board.pieces(chess.QUEEN, stm):
                if any(t in ext for t in board.attacks(q)):
                    qh = True
                    break
            if bh >= 1 and (cp >= 2 or qh or castles(stm) > castles(opp)):
                if not board.is_check() or castles(stm) == 2 or qh:
                    return True

    return False
